Object.assign(window.MLSysGuidedLessons, {"vol1:fig-2-4-gemm":{"key":"vol1:fig-2-4-gemm","figure_id":"fig-2-4-gemm","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"2:4 Structured Sparsity GEMM","status":"ready","treatment":"annotated","question":"What must structured sparsity retain besides its nonzero weights?","scope":"Supported 2:4 sparse inner-loop example; fewer multiplied values do not imply a proportional end-to-end speedup.","regions":{"dense":{"x":0.0,"y":0.04,"w":0.46,"h":0.43,"label":"Dense dot-product path"},"sparse":{"x":0.56,"y":0.02,"w":0.35,"h":0.45,"label":"Sparse value and selection path"},"meta":{"x":0.68,"y":0.49,"w":0.15,"h":0.39,"label":"Compressed values and metadata"},"rhs":{"x":0.87,"y":0.08,"w":0.13,"h":0.37,"label":"Dense right-hand operand"},"out":{"x":0.89,"y":0.51,"w":0.11,"h":0.36,"label":"Dense result"}},"steps":[{"title":"Start from the dense multiplication","description":"The left-hand panel consumes every entry of an eight-element row and a matching dense column to form an output accumulator.","focus":["dense"]},{"title":"Retain positions with compressed values","description":"On the right, each group of four retains two nonzeros. Compact indices preserve their original positions; zeros cannot simply disappear without this information.","focus":["meta"]},{"title":"Select the matching dense elements","description":"Metadata steers selection from the uncompressed right-hand matrix. The shortened multiply path still produces a dense result, while metadata and surrounding execution contribute overhead.","focus":["sparse","rhs","out"]}],"artwork_reviewed":true,"art_sha1":"364e65f4d06ff335d4fc1651626f683a5b084d0d","art_kind":"svg","art_width":1200,"art_height":569,"art_structural_sha1":"7414cc610c76a08b6e87e233de7c417a63adfe54"},"vol1:fig-3-sections":{"key":"vol1:fig-3-sections","figure_id":"fig-3-sections","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Three Tiers of Compression","status":"ready","treatment":"annotated","question":"Why do model representation, numerical precision, and hardware execution need separate validation?","scope":"These are abstraction tiers, not a claim that optimizations compose independently or in one mandatory order.","regions":{"representation":{"x":0.21,"y":0.12,"w":0.79,"h":0.24,"label":"Efficient model representation"},"numerics":{"x":0.21,"y":0.4,"w":0.79,"h":0.24,"label":"Efficient numerics representation"},"hardware":{"x":0.21,"y":0.67,"w":0.79,"h":0.24,"label":"Efficient hardware implementation"},"direction":{"x":0,"y":0,"w":0.18,"h":1,"label":"Software to hardware axis"}},"steps":[{"title":"Change the work represented","description":"Efficient Model Representation includes structural choices such as pruning and distillation. These can change the operations and parameters the model needs.","focus":["representation"]},{"title":"Choose how values are encoded","description":"Efficient Numerics Representation changes precision and range. Fewer bits reduce raw value storage but require quality and execution-support checks.","focus":["numerics"]},{"title":"Map onto physical execution","description":"Efficient Hardware Implementation determines how kernels and supported sparsity patterns use compute and memory. A smaller representation needs a matching execution path to become faster.","focus":["hardware"]},{"title":"Validate across the boundary","description":"The vertical axis connects software to hardware. Changes at one tier affect the assumptions of the others, so savings must be checked together.","focus":["direction","representation","hardware"]}],"artwork_reviewed":true,"art_sha1":"5788987001e7758a63cb22d8c362affaaf55e636","art_kind":"svg","art_width":1200,"art_height":601,"art_structural_sha1":"004c04f22118b807b4190f972a2da38cc6d8e473"},"vol1:fig-3float":{"key":"vol1:fig-3float","figure_id":"fig-3float","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Floating-Point Bit Layouts","status":"ready","treatment":"annotated","question":"Why do FP16 and BF16 spend the same storage budget differently?","scope":"The drawing compares bit layouts, not measured compute speed. Exponent range and fraction precision have different effects.","regions":{"fp32":{"x":0,"y":0.22,"w":1,"h":0.19,"label":"FP32 layout"},"fp16":{"x":0,"y":0.49,"w":0.53,"h":0.18,"label":"FP16 layout"},"bf16":{"x":0,"y":0.76,"w":0.53,"h":0.18,"label":"BF16 layout"},"exponents":{"x":0.09,"y":0.22,"w":0.23,"h":0.72,"label":"Exponent fields"},"fractions":{"x":0.32,"y":0.22,"w":0.68,"h":0.19,"label":"FP32 fraction extent"}},"steps":[{"title":"Establish the FP32 baseline","description":"FP32 allocates one sign bit, eight exponent bits, and 23 fraction bits. Exponent and fraction serve different purposes: range and significand resolution.","focus":["fp32"]},{"title":"Spend more FP16 bits on the fraction","description":"FP16 uses five exponent bits and ten fraction bits. Its narrower exponent range can make small training updates underflow, motivating loss scaling.","focus":["fp16"]},{"title":"Preserve exponent range in BF16","description":"BF16 retains eight exponent bits but only seven fraction bits. It preserves a range similar to FP32 while sacrificing significand precision.","focus":["bf16","exponents"]},{"title":"Separate storage from arithmetic behavior","description":"Both 16-bit formats halve raw value storage relative to FP32. Their different layouts still require appropriate numerical and hardware support.","focus":["fp16","bf16","fractions"]}],"artwork_reviewed":true,"art_sha1":"fa3ef36d942fc4c6b3f704cd6c4a59b46b3e51b9","art_kind":"svg","art_width":1200,"art_height":321,"art_structural_sha1":"0e8e4421f13870576f13fb165b7ec4626edbf993"},"vol1:fig-TinyML-example":{"key":"vol1:fig-TinyML-example","figure_id":"fig-TinyML-example","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"TinyML Hardware Scale","status":"ready","treatment":"annotated","question":"Which components share a TinyML device's resource budget?","scope":"This is a prototyping board and kit, not a measured multi-year battery-life demonstration.","regions":{"kit":{"x":0,"y":0.01,"w":0.51,"h":0.98,"label":"Prototype kit"},"processor":{"x":0.79,"y":0.47,"w":0.21,"h":0.32,"label":"Processor and Bluetooth"},"imu":{"x":0.69,"y":0.31,"w":0.08,"h":0.32,"label":"IMU"},"sensors":{"x":0.6,"y":0.56,"w":0.24,"h":0.43,"label":"Temperature humidity and microphone"},"model":{"x":0.75,"y":0.13,"w":0.21,"h":0.31,"label":"TensorFlow Lite model illustration"}},"steps":[{"title":"Recognize the prototype boundary","description":"The kit places a sensor-equipped microcontroller board alongside development hardware. A finished deployment must budget more than the model weights.","focus":["kit"]},{"title":"Find the processor and radio","description":"Processor + Bluetooth identifies compute and connectivity on the same compact substrate. Radio activity and inference cadence both affect the energy budget.","focus":["processor"]},{"title":"Include sensor acquisition","description":"The IMU, microphone, and temperature/humidity sensor supply input streams. Acquisition and preprocessing consume resources before classification begins.","focus":["imu","sensors"]},{"title":"Fit the complete sensing pipeline","description":"The model illustration represents local inference. Weights and code must fit flash, while activations and runtime state fit SRAM; sleep and sensor power also matter.","focus":["model","processor"]}],"artwork_reviewed":true,"art_sha1":"20af6c17c9474b16fb942e58afcdf19963a162bc","art_kind":"png","art_width":1000,"art_height":361},"vol1:fig-accelerator-anatomy":{"key":"vol1:fig-accelerator-anatomy","figure_id":"fig-accelerator-anatomy","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"Anatomy of a Modern AI Accelerator","status":"ready","treatment":"annotated","question":"Which storage and execution boundaries must operands cross before arithmetic can run?","scope":"Generic accelerator anatomy; cache and scratchpad policies vary across actual products.","regions":{"host":{"x":0.0,"y":0.54,"w":0.15,"h":0.43,"label":"Host CPU and DRAM"},"interface":{"x":0.15,"y":0.6,"w":0.12,"h":0.16,"label":"Host interface"},"hbm":{"x":0.76,"y":0.58,"w":0.24,"h":0.18,"label":"Device memory and memory interface"},"l2":{"x":0.29,"y":0.59,"w":0.44,"h":0.15,"label":"Shared L2 storage"},"pe":{"x":0.28,"y":0.05,"w":0.44,"h":0.39,"label":"Processing-element internals"}},"steps":[{"title":"Work arrives from the host","description":"Host DRAM and the CPU are outside the accelerator boundary. The host interface carries work and transfers; it is distinct from the device-memory interface.","focus":["host","interface"]},{"title":"Device bytes enter shared storage","description":"HBM feeds the shared L2 cache through the memory interface. This path supplies operands to processing elements rather than performing the matrix arithmetic itself.","focus":["hbm","l2"]},{"title":"Locality feeds several arithmetic units","description":"Inside a processing element, local cache or scratchpad supplies the tensor, vector, and special-function units. Keeping operands nearby reduces repeated trips to external memory.","focus":["pe","l2"]}],"artwork_reviewed":true,"art_sha1":"45e804ae59a5ebcc7d3f4eb3604a42e158871b7b","art_kind":"svg","art_width":1200,"art_height":629,"art_structural_sha1":"fcbf5582532ed8ea1f44b7f39684e66df15f4c59"},"vol1:fig-activation-functions":{"key":"vol1:fig-activation-functions","figure_id":"fig-activation-functions","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Common Activation Functions","status":"ready","treatment":"annotated","question":"Which output semantics distinguish these activation functions?","scope":"Softmax plots one component with two other logits fixed at 13 and 0; its magnified vertical scale cannot be compared directly to the other panels.","regions":{"sigmoid":{"x":0.0,"y":0.0,"w":0.49,"h":0.49,"label":"Sigmoid"},"tanh":{"x":0.51,"y":0.0,"w":0.49,"h":0.49,"label":"Tanh"},"relu":{"x":0.0,"y":0.51,"w":0.49,"h":0.49,"label":"ReLU"},"softmax":{"x":0.51,"y":0.51,"w":0.49,"h":0.49,"label":"One softmax component"}},"steps":[{"title":"Compare bounded scalar outputs","description":"Sigmoid maps to (0,1), while tanh maps to (-1,1) around zero. Their saturated ends have small local slopes, which can weaken gradient propagation.","focus":["sigmoid","tanh"]},{"title":"Inspect ReLU’s two branches","description":"ReLU outputs zero on the negative branch and preserves positive inputs. Its simple comparison-and-select operation has different semantics from bounded sigmoid or tanh.","focus":["relu"]},{"title":"Read softmax as a coupled vector","description":"The bottom-right curve is only one probability component of a three-logit softmax. Changing another logit changes this component too, and all output components must sum to one.","focus":["softmax"]}],"artwork_reviewed":true,"art_sha1":"68d4612b2668ee81088601f128d155a3b8f9dca8","art_kind":"svg","art_width":1200,"art_height":815,"art_structural_sha1":"e58daee8e364b76a72005285bf0455fa9ec4c9b9"},"vol1:fig-active-learning-loop":{"key":"vol1:fig-active-learning-loop","figure_id":"fig-active-learning-loop","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"The Active Learning Closed Loop","status":"ready","treatment":"annotated","question":"How does active learning turn scoring work into new labels?","scope":"Pool-based selection cycle; oracle labels and model updates are not assumed error-free.","regions":{"pool":{"x":0,"y":0,"w":0.38,"h":0.31,"label":"Unlabeled candidate pool"},"selection":{"x":0.5,"y":0,"w":0.5,"h":0.31,"label":"Selection strategy"},"oracle":{"x":0.5,"y":0.34,"w":0.5,"h":0.31,"label":"Human oracle"},"training":{"x":0.55,"y":0.69,"w":0.45,"h":0.31,"label":"Labeled training set"},"model":{"x":0,"y":0.69,"w":0.4,"h":0.31,"label":"Updated model"}},"steps":[{"title":"Score candidates before querying","description":"The unlabeled pool feeds a selection strategy. Uncertainty, diversity, or coverage criteria choose which annotation requests are worth making.","focus":["pool","selection"]},{"title":"Acquire labels from the oracle","description":"Selected queries go to the human oracle; returned labels join the training set. Choosing a sample and obtaining its label are distinct operations.","focus":["oracle","training"]},{"title":"Close the loop with a new model","description":"Training updates the model, whose new state changes subsequent selection. Scoring and retraining consume compute even when they reduce annotation demand.","focus":["model","selection"]}],"artwork_reviewed":true,"art_sha1":"84f95b4b59039209a0d109cd4285ba36004896a3","art_kind":"svg","art_width":1200,"art_height":1051,"art_structural_sha1":"967312e4a79b8a34bf4caa8ae8867be1936ea1f6"},"vol1:fig-active-learning-multiplier":{"key":"vol1:fig-active-learning-multiplier","figure_id":"fig-active-learning-multiplier","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"The Active Learning Multiplier","status":"ready","treatment":"annotated","question":"How is the illustrated fourfold label-efficiency gap read?","scope":"Illustrative accuracy curves, not a measured guarantee for active learning.","regions":{"active":{"x":0.48,"y":0.07,"w":0.31,"h":0.27,"label":"Active learning near target quality"},"random":{"x":0.79,"y":0.15,"w":0.19,"h":0.27,"label":"Random sampling near target quality"},"arrow":{"x":0.7,"y":0.13,"w":0.24,"h":0.12,"label":"Fourfold label comparison"},"axis":{"x":0.09,"y":0.82,"w":0.87,"h":0.17,"label":"Logarithmic labeled-sample axis"}},"steps":[{"title":"Fix a target accuracy","description":"Near 90 percent accuracy, compare where each curve reaches the same vertical level. Comparing arbitrary endpoints would mix label budget and quality.","focus":["active","random"]},{"title":"Read multiplicative label counts","description":"The horizontal sample axis is logarithmic. The arrow illustrates reaching similar accuracy with roughly one quarter as many labeled samples, rather than four percentage points more accuracy.","focus":["arrow","axis"]},{"title":"Account for the other work","description":"The plot compares annotation demand. Selection scoring, model updates, and the reliability of the oracle still determine whether the full active-learning loop is worthwhile.","focus":["active","random"]}],"artwork_reviewed":true,"art_sha1":"3acad95b35ab4a5f801a6e4cfcbc287268693ae5","art_kind":"png","art_width":3278,"art_height":2245},"vol1:fig-ai-performance":{"key":"vol1:fig-ai-performance","figure_id":"fig-ai-performance","source":"books/vol1/backmatter/appendix_assumptions.qmd","title":"Advertised GPU Peak Capability Across Generations","status":"ready","treatment":"annotated","question":"Why is the advertised GPU peak curve not a same-precision speedup curve?","scope":"Single-chip advertised paths mix floating-point and integer operations, precision, and structured-sparsity assumptions; no sustained application performance claim.","regions":{"fp32":{"x":0.12,"y":0.6,"w":0.28,"h":0.27,"label":"K20X and M40 FP32"},"middle":{"x":0.28,"y":0.38,"w":0.32,"h":0.27,"label":"P40 INT8 and V100 FP16"},"sparse":{"x":0.54,"y":0,"w":0.45,"h":0.35,"label":"A100 H100 and B200 sparse paths"},"scale":{"x":0,"y":0.02,"w":0.1,"h":0.87,"label":"Logarithmic peak axis"}},"steps":[{"title":"Start with the FP32 baseline","description":"K20X and M40 labels report FP32 throughput. Their points can be interpreted only together with the operation and precision labels.","focus":["fp32"]},{"title":"Notice the quantity changes","description":"P40 uses INT8 operations while V100 reports FP16 floating-point throughput. Connecting these points does not make them one consistent same-precision measurement series.","focus":["middle"]},{"title":"Keep sparsity assumptions explicit","description":"A100, H100, and B200 labels assume structured sparsity and include narrower numerical formats. The steep advertised curve therefore combines several changes and cannot predict a general application speedup.","focus":["sparse","scale"]}],"artwork_reviewed":true,"art_sha1":"7ffe035fe5ec155b67400fbfccb83acf64b72757","art_kind":"svg","art_width":1200,"art_height":594,"art_structural_sha1":"00e865382008b6850b123b140550055815c5e2fd"},"vol1:fig-ai-timeline":{"key":"vol1:fig-ai-timeline","figure_id":"fig-ai-timeline","source":"books/vol1/01_introduction/01_introduction.qmd","title":"AI Development Timeline","status":"ready","treatment":"annotated","question":"How should a history of attention to AI be read alongside technical milestones?","scope":"The red curve measures mentions in books, not capability; winter bands denote historical intervals, not isolated hardware causes.","regions":{"early":{"x":0.04,"y":0.24,"w":0.36,"h":0.7,"label":"Early milestones"},"winter1":{"x":0.36,"y":0.015,"w":0.08,"h":0.95,"label":"First AI winter"},"winter2":{"x":0.52,"y":0.015,"w":0.085,"h":0.95,"label":"Second AI winter"},"late":{"x":0.65,"y":0.35,"w":0.31,"h":0.6,"label":"Later milestones"},"curve":{"x":0.38,"y":0.14,"w":0.25,"h":0.52,"label":"Publication-frequency rise and fall"}},"steps":[{"title":"Locate the early approaches","description":"Turing, the Dartmouth workshop, the perceptron, and ELIZA appear as dated callouts. These approaches overlapped rather than replacing one another on a fixed schedule.","focus":["early"]},{"title":"Separate attention from capability","description":"The red curve rises and falls through shaded winter intervals. Its height counts publication mentions, so a peak cannot be read as a measured level of intelligence.","focus":["winter1","winter2","curve"]},{"title":"Read advances as systems combinations","description":"Deep Blue and GPT-3 mark later milestones. Their dates locate developments, while the surrounding chapter explains how data, algorithms, and machines jointly changed the feasible systems.","focus":["late"]}],"artwork_reviewed":true,"art_sha1":"8dc2e1136f17edfd0ed04c60f59a687891de8e84","art_kind":"svg","art_width":1200,"art_height":1003,"art_structural_sha1":"9bae8012506a42044c59c151c501597f45ed3599"},"vol1:fig-ai-training-compute-growth":{"key":"vol1:fig-ai-training-compute-growth","figure_id":"fig-ai-training-compute-growth","source":"books/vol1/01_introduction/01_introduction.qmd","title":"The Era of Scale","status":"ready","treatment":"annotated","question":"What does a rising training-compute estimate imply about systems requirements?","scope":"Third-party final-training compute estimates for selected notable models; log-scale evidence, not inference cost or a capability score.","regions":{"early":{"x":0.12,"y":0.54,"w":0.3,"h":0.31,"label":"Early estimated runs"},"large":{"x":0.58,"y":0.02,"w":0.39,"h":0.4,"label":"Larger estimated runs"},"fit":{"x":0.36,"y":0.38,"w":0.28,"h":0.24,"label":"Least-squares trend"},"legend":{"x":0.47,"y":0.66,"w":0.52,"h":0.2,"label":"Threshold and fit legend"}},"steps":[{"title":"Read logarithmic orders of magnitude","description":"AlexNet and early points occupy the lower part of the FLOPs axis. Equal vertical distances represent multiplicative differences, not equal added operations.","focus":["early"]},{"title":"Distinguish estimates from requirements","description":"Later red points exceed the plotted 10²²-FLOP category threshold. They show selected training-run estimates, not a universal minimum for useful ML.","focus":["large","legend"]},{"title":"Use the trend to motivate infrastructure","description":"The fitted line summarizes rapid growth across the plotted runs. It does not establish a hardware growth law or predict the cost of a particular future training job.","focus":["fit"]}],"artwork_reviewed":true,"art_sha1":"6e0aee68f7dd38537dbc0be3627a4a3216e2d19a","art_kind":"png","art_width":3347,"art_height":2222},"vol1:fig-ai-triad":{"key":"vol1:fig-ai-triad","figure_id":"fig-ai-triad","source":"books/vol1/01_introduction/01_introduction.qmd","title":"The D·A·M Intersection Landscape","status":"ready","treatment":"annotated","question":"Which engineering questions belong at the intersections of Data, Algorithm, and Machine?","scope":"The overlaps organize joint design questions; their drawn areas are not quantitative proportions.","regions":{"data":{"x":0.34,"y":0.01,"w":0.39,"h":0.29,"label":"Data concerns"},"algorithm":{"x":0.21,"y":0.54,"w":0.24,"h":0.26,"label":"Algorithm concerns"},"machine":{"x":0.62,"y":0.54,"w":0.24,"h":0.26,"label":"Machine concerns"},"da":{"x":0.32,"y":0.31,"w":0.22,"h":0.15,"label":"What to learn from"},"dm":{"x":0.58,"y":0.28,"w":0.17,"h":0.19,"label":"How to move information"},"am":{"x":0.47,"y":0.59,"w":0.13,"h":0.16,"label":"How to execute efficiently"},"center":{"x":0.48,"y":0.42,"w":0.14,"h":0.16,"label":"ML systems engineering"}},"steps":[{"title":"Distinguish the three axes","description":"Storage and quality belong to Data, model mathematics to Algorithm, and silicon and memory to Machine. These labels identify kinds of evidence to investigate.","focus":["data","algorithm","machine"]},{"title":"Resolve pairwise questions","description":"Data–Algorithm asks what to learn from; Data–Machine asks how to move information; Algorithm–Machine asks how to execute efficiently. Each requires choices on both axes.","focus":["da","dm","am"]},{"title":"Integrate the constraints","description":"The center names ML systems engineering because a useful deployment must satisfy all three axes together. Improving one axis alone does not establish end-to-end success.","focus":["center"]}],"artwork_reviewed":true,"art_sha1":"f377b559a0565668084563050c32a6067c996044","art_kind":"svg","art_width":1200,"art_height":858,"art_structural_sha1":"0b6f0cac4007c5107ef9b18fe6b2a1f744954fc6"},"vol1:fig-alexnet":{"key":"vol1:fig-alexnet","figure_id":"fig-alexnet","source":"books/vol1/01_introduction/01_introduction.qmd","title":"AlexNet Architecture","status":"ready","treatment":"annotated","question":"How did AlexNet map one network onto two GPUs?","scope":"Historical partitioned architecture; schematic arrows are dependencies, not a measured communication schedule.","regions":{"input":{"x":0,"y":0.32,"w":0.1,"h":0.62,"label":"224×224 input streams"},"upper":{"x":0.1,"y":0.01,"w":0.75,"h":0.48,"label":"Upper convolution stream"},"lower":{"x":0.1,"y":0.45,"w":0.75,"h":0.49,"label":"Lower convolution stream"},"dense":{"x":0.85,"y":0.19,"w":0.15,"h":0.68,"label":"Fully connected outputs"}},"steps":[{"title":"Partition the convolutional work","description":"The green blocks form two parallel streams. Each holds part of the network rather than representing two independent models.","focus":["input","upper","lower"]},{"title":"Exchange only at selected connections","description":"Dashed cross-stream connections mark dependencies between the partitions. The historical design limited exchanges because the inter-GPU link was itself a constraint.","focus":["upper","lower"]},{"title":"Converge on classification","description":"After the convolution and pooling stages, the fully connected layers combine features into 1,000 outputs. The partition is a model–machine design choice, not simply a larger batch.","focus":["dense"]}],"artwork_reviewed":true,"art_sha1":"f8a0807ce23776af707d78b7945fcd9458ed50c4","art_kind":"svg","art_width":1200,"art_height":517,"art_structural_sha1":"05a0542a0606b9a4f59236726f5a332a8b695413"},"vol1:fig-algo-efficiency":{"key":"vol1:fig-algo-efficiency","figure_id":"fig-algo-efficiency","source":"books/vol1/01_introduction/01_introduction.qmd","title":"Algorithmic Efficiency Trajectory","status":"ready","treatment":"annotated","question":"What does algorithmic efficiency measure when hardware speed is held out?","scope":"Measured compute to reach AlexNet-level ImageNet accuracy; the fitted trend is descriptive rather than a forecast.","regions":{"baseline":{"x":0.1,"y":0.7,"w":0.16,"h":0.12,"label":"AlexNet baseline"},"vgg":{"x":0.33,"y":0.73,"w":0.13,"h":0.12,"label":"VGG-11 exception"},"later":{"x":0.56,"y":0.15,"w":0.4,"h":0.5,"label":"Later efficient architectures"},"fit":{"x":0.44,"y":0.32,"w":0.53,"h":0.45,"label":"Dashed fitted trajectory"}},"steps":[{"title":"Fix the quality target","description":"AlexNet provides the reference compute required to reach its accuracy. A factor above one means less training compute for this same target, not faster hardware.","focus":["baseline"]},{"title":"Keep the exception visible","description":"VGG-11 falls below the AlexNet reference despite being later. Publication date alone does not guarantee efficiency at a fixed accuracy.","focus":["vgg"]},{"title":"Read progress without treating the fit as law","description":"Later architectures reach the target with much less compute, while individual points vary around the dashed fit. The fit summarizes these measurements rather than predicting every future model.","focus":["later","fit"]}],"artwork_reviewed":true,"art_sha1":"ba5366cbc30a2e884568e46ea4cc331eb9df5b3e","art_kind":"png","art_width":3370,"art_height":2188},"vol1:fig-amortization-comparison":{"key":"vol1:fig-amortization-comparison","figure_id":"fig-amortization-comparison","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"Cost Amortization in Foundation Models","status":"ready","treatment":"annotated","question":"When does a shared pretraining cost pay off across tasks?","scope":"Illustrative compute-only GPU-hour accounting; costs exclude deployment quality and other project expenses.","regions":{"scratch":{"x":0,"y":0.03,"w":0.5,"h":0.92,"label":"Repeated scratch-training costs"},"pretrain":{"x":0.57,"y":0.12,"w":0.05,"h":0.76,"label":"One-time pretraining"},"finetune":{"x":0.61,"y":0.79,"w":0.37,"h":0.11,"label":"Small per-task fine-tuning"},"totals":{"x":0.16,"y":0.08,"w":0.76,"h":0.08,"label":"Ten-task totals"}},"steps":[{"title":"Repeat the scratch-training bill","description":"Each task on the left pays its own training-from-scratch cost. The equal-height bars accumulate linearly with the number of tasks.","focus":["scratch"]},{"title":"Pay a large fixed cost once","description":"The foundation-model strategy pays pretraining up front, then adds much smaller fine-tuning costs per task. A low marginal cost is different from a low total at the start.","focus":["pretrain","finetune"]},{"title":"Check the snapshot before declaring savings","description":"The ten-task totals are comparable and the foundation approach remains slightly more expensive at this snapshot. More reuse can cross the compute-only break-even point; the shared model must still meet task quality requirements.","focus":["totals"]}],"artwork_reviewed":true,"art_sha1":"4ed6f75a70de8aee2b766711bc2eb701bbfee21a","art_kind":"png","art_width":3659,"art_height":2220},"vol1:fig-attention":{"key":"vol1:fig-attention","figure_id":"fig-attention","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Query-Key-Value Attention Mechanism","status":"ready","treatment":"annotated","question":"How does one attention matrix connect queries, keys, and values?","scope":"Six tokens; cell colors are illustrative, not calculated attention probabilities.","regions":{"queries":{"x":0,"y":0.31,"w":0.45,"h":0.37,"label":"Query rows"},"keys":{"x":0,"y":0,"w":0.62,"h":0.36,"label":"Key columns"},"matrix":{"x":0.44,"y":0.34,"w":0.19,"h":0.33,"label":"6×6 attention matrix"},"values":{"x":0,"y":0.7,"w":0.95,"h":0.29,"label":"Value aggregation"},"out":{"x":0.94,"y":0.37,"w":0.06,"h":0.25,"label":"Output positions"}},"steps":[{"title":"Compare a query with every key","description":"Each cyan query row meets six red key paths. Six queries by six keys create 36 pairwise comparison entries.","focus":["queries","keys","matrix"]},{"title":"Distinguish structure from weights","description":"The grid represents the dense attention pattern. Its blue-to-red gradient is an illustration and cannot be read as computed probabilities.","focus":["matrix"]},{"title":"Aggregate values for each output","description":"Each attention row weights the green values to form one output position. Materializing all dense weights stores a quantity growing quadratically with sequence length.","focus":["values","out","matrix"]}],"artwork_reviewed":true,"art_sha1":"8a0b193f419f35ba84dea51859bd2e3ab2ec766e","art_kind":"svg","art_width":1200,"art_height":725,"art_structural_sha1":"dbec666d6d3cd995bfd904f688bc63feee0e5da6"},"vol1:fig-attention-weightcalc":{"key":"vol1:fig-attention-weightcalc","figure_id":"fig-attention-weightcalc","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"QKV Projection Computation","status":"ready","treatment":"annotated","question":"How can one projection multiplication produce Q, K, and V?","scope":"Only the first token output row is drawn; the declared output has six rows.","regions":{"embedding":{"x":0.02,"y":0.25,"w":0.21,"h":0.53,"label":"6×768 embedding"},"weights":{"x":0.3,"y":0.25,"w":0.2,"h":0.53,"label":"768×2304 QKV weights"},"bias":{"x":0.53,"y":0.14,"w":0.1,"h":0.64,"label":"2304-entry bias"},"result":{"x":0.66,"y":0.25,"w":0.33,"h":0.53,"label":"6×2304 QKV result"}},"steps":[{"title":"Start with six embedding rows","description":"Each of the six token pieces supplies a 768-element embedding row. The first row drawn is labeled Data.","focus":["embedding"]},{"title":"Pack three projections side by side","description":"The weight matrix has 2304 output columns: 768 each for queries, keys, and values. The color blocks preserve their separate identities within one multiplication.","focus":["weights"]},{"title":"Add bias and retain all token positions","description":"A bias vector is added to each projected row. The displayed QKV row is only the first of the six rows in the result; packing does not discard the other tokens.","focus":["bias","result"]}],"artwork_reviewed":true,"art_sha1":"c79baefb224574a734d481ac10a9680557c25e24","art_kind":"svg","art_width":1200,"art_height":626,"art_structural_sha1":"d0b97ada49fc18d5eb478cd76ccc1b71088031b4"},"vol1:fig-backprop-graph":{"key":"vol1:fig-backprop-graph","figure_id":"fig-backprop-graph","source":"books/vol1/backmatter/appendix_algorithm.qmd","title":"Backpropagation Computational Graph","status":"ready","treatment":"annotated","question":"How does reverse differentiation retrace forward dependencies?","scope":"Two-layer symbolic computational graph; reverse arrows represent gradients, not optimizer updates.","regions":{"x":{"x":0.0,"y":0.3,"w":0.11,"h":0.57,"label":"Input x"},"h":{"x":0.29,"y":0.3,"w":0.11,"h":0.57,"label":"Hidden activation h"},"prediction":{"x":0.59,"y":0.3,"w":0.11,"h":0.57,"label":"Prediction"},"loss":{"x":0.88,"y":0.3,"w":0.12,"h":0.57,"label":"Loss"},"forward":{"x":0.1,"y":0.53,"w":0.78,"h":0.24,"label":"Solid forward dependencies"},"reverse":{"x":0.08,"y":0.0,"w":0.81,"h":0.51,"label":"Dashed reverse-gradient dependencies"}},"steps":[{"title":"Compute the loss along the forward path","description":"Solid arrows carry x through W1 to h, then W2 to the prediction, then the loss. Each operation depends on its preceding forward value.","focus":["x","h","prediction","forward","loss"]},{"title":"Differentiate from the loss backward","description":"Dashed red arrows carry loss sensitivities in reverse dependency order, beginning with the prediction and continuing to h and x. Their direction differs from forward value production.","focus":["loss","reverse"]},{"title":"Keep values until their backward consumers finish","description":"Backward operations use intermediate activations produced earlier. Gradient computation therefore adds a lifetime requirement; an optimizer update is a separate stage outside this drawing.","focus":["h","prediction","reverse"]}],"artwork_reviewed":true,"art_sha1":"26cdc0937b4bb1647ebc6c8419f63413fdd9832d","art_kind":"svg","art_width":1200,"art_height":212,"art_structural_sha1":"bdd0c42962fdb4643ffc61ac58a9e504b40ad901"},"vol1:fig-bandwidth-envelope":{"key":"vol1:fig-bandwidth-envelope","figure_id":"fig-bandwidth-envelope","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"Compute and Bandwidth Across Vendors","status":"ready","treatment":"annotated","question":"What can best-device envelopes reveal, and what can they hide?","scope":"Historical dense FP16/BF16 compute and bandwidth relative to TPU v2; separate envelopes may come from different devices.","regions":{"legend":{"x":0.13,"y":0.0,"w":0.67,"h":0.16,"label":"Metric legend"},"early":{"x":0.1,"y":0.48,"w":0.3,"h":0.37,"label":"Early normalized observations"},"compute":{"x":0.43,"y":0.05,"w":0.47,"h":0.33,"label":"Best compute envelope"},"bandwidth":{"x":0.43,"y":0.34,"w":0.47,"h":0.26,"label":"Best bandwidth envelope"},"points":{"x":0.43,"y":0.58,"w":0.47,"h":0.3,"label":"Individual device observations"}},"steps":[{"title":"Use the common baseline","description":"Both metrics are normalized to TPU v2 on a logarithmic axis. This permits comparing growth factors, not dividing raw TFLOP/s by raw TB/s directly from an unnormalized value.","focus":["legend","early"]},{"title":"Separate the envelopes","description":"The red best-to-date compute line climbs faster than the blue bandwidth line. These are independent frontiers, so their ratio need not describe one specific chip.","focus":["compute","bandwidth"]},{"title":"Keep the device population visible","description":"Individual dots show variation hidden by the record-setting step lines. The late plateaus concern the plotted dense 16-bit formats rather than every precision format or workload.","focus":["points","compute"]}],"artwork_reviewed":true,"art_sha1":"f6ea5a172cf0fd8dfd59f4a824338aafda4254ff","art_kind":"png","art_width":3315,"art_height":2419},"vol1:fig-benchmark-components":{"key":"vol1:fig-benchmark-components","figure_id":"fig-benchmark-components","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Benchmark Workflow Components","status":"ready","treatment":"annotated","question":"What must be fixed to make an embedded benchmark reproducible?","scope":"This is the cited MLPerf Tiny anomaly-detection workflow, not a configurable performance model.","regions":{"definition":{"x":0.0,"y":0.0,"w":0.32,"h":0.22,"label":"Problem dataset and model selection"},"implementation":{"x":0.32,"y":0.0,"w":0.45,"h":0.22,"label":"Training quantization and implementation"},"run":{"x":0.77,"y":0.0,"w":0.23,"h":0.22,"label":"Deployment and benchmark run"},"audio":{"x":0.0,"y":0.26,"w":0.17,"h":0.71,"label":"Anomalous sound task"},"features":{"x":0.27,"y":0.26,"w":0.28,"h":0.74,"label":"Features and autoencoder"},"target":{"x":0.61,"y":0.28,"w":0.39,"h":0.67,"label":"Training artifact and embedded result"}},"steps":[{"title":"Fix the task before timing","description":"The first workflow stages specify the problem, dataset, and model. The lower-left anomaly-detection example establishes what the system must distinguish.","focus":["definition","audio"]},{"title":"Carry constraints into implementation","description":"Feature extraction and the autoencoder define the workload, while training code and quantization define the deployed artifact. These choices constrain what later latency or quality numbers mean.","focus":["features","implementation"]},{"title":"Include the harness and target","description":"Embedded implementation, harness integration, deployment, and the example run complete the benchmark. The result table belongs to that specific artifact and device boundary.","focus":["run","target"]}],"artwork_reviewed":true,"art_sha1":"501f4293c27346f09ca0e41d439faf8cfdd56a7d","art_kind":"svg","art_width":1200,"art_height":507,"art_structural_sha1":"d8f42a4246d9cdcdf314f00a2fb83ca18139e944"},"vol1:fig-benchmark-tradeoffs":{"key":"vol1:fig-benchmark-tradeoffs","figure_id":"fig-benchmark-tradeoffs","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Isolation vs. Representativeness","status":"ready","treatment":"annotated","question":"Why combine benchmark scopes instead of selecting only one?","scope":"Axes are conceptual, without numerical diagnostic or realism scores.","regions":{"micro":{"x":0.25,"y":0.2,"w":0.41,"h":0.17,"label":"Micro-benchmarks"},"macro":{"x":0.4,"y":0.43,"w":0.43,"h":0.16,"label":"Macro-benchmarks"},"end":{"x":0.55,"y":0.67,"w":0.45,"h":0.17,"label":"End-to-end benchmarks"},"vertical":{"x":0.0,"y":0.0,"w":0.17,"h":0.9,"label":"Isolation axis"},"horizontal":{"x":0.13,"y":0.89,"w":0.83,"h":0.11,"label":"Representativeness axis"}},"steps":[{"title":"Use isolation to diagnose","description":"Micro-benchmarks sit high on isolation and diagnostic power. They help attribute a change to a component, but their narrow context limits deployment claims.","focus":["micro","vertical"]},{"title":"Check composition","description":"Macro-benchmarks include model structure and dependencies. They test whether component gains survive composition while preserving more diagnostic control than a full service.","focus":["macro"]},{"title":"Validate the delivery boundary","description":"End-to-end benchmarks increase real-world representativeness while hiding some root causes. Combine them with narrower experiments to show both delivered benefit and an explanation.","focus":["end","horizontal"]}],"artwork_reviewed":true,"art_sha1":"38b8299e6c1e1a382afccb66a266b373d24b8f2b","art_kind":"svg","art_width":1200,"art_height":796,"art_structural_sha1":"e80d14e302439c3d6da4cd4f59031f8e87c5c4d6"},"vol1:fig-benchmarking-mobilenet-waterfall":{"key":"vol1:fig-benchmarking-mobilenet-waterfall","figure_id":"fig-benchmarking-mobilenet-waterfall","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"From Claimed to Delivered Speedup on the Edge Board","status":"ready","treatment":"annotated","question":"Why does a large compute speedup become a smaller end-to-end gain?","scope":"All bars are the chapter’s illustrative edge-board scenario; active energy excludes idle and other omitted power.","regions":{"fp32":{"x":0.1,"y":0.15,"w":0.08,"h":0.68,"label":"Host FP32 isolated compute"},"int8":{"x":0.2,"y":0.6,"w":0.21,"h":0.23,"label":"INT8 isolated compute"},"end":{"x":0.46,"y":0.54,"w":0.17,"h":0.29,"label":"End-to-end latency bars"},"overhead":{"x":0.46,"y":0.54,"w":0.17,"h":0.25,"label":"Hatched host preparation and link"},"energy":{"x":0.79,"y":0.26,"w":0.18,"h":0.57,"label":"Active energy bars"}},"steps":[{"title":"Inspect isolated compute","description":"The left group compares host FP32, host INT8, and accelerator INT8 model execution. These narrow timings show arithmetic-path improvements without the full input path.","focus":["fp32","int8"]},{"title":"Widen the timing boundary","description":"The end-to-end group adds hatched Host prep + link segments. This changes what is counted, not the physical work performed, and reduces the reported speedup ratio.","focus":["end","overhead"]},{"title":"Keep the energy boundary explicit","description":"The right panel compares active energy per inference. It supports the stated active-energy advantage, but total system energy also depends on host, idle, and other excluded power.","focus":["energy"]}],"artwork_reviewed":true,"art_sha1":"fb1f5e5de0379b69b0837ab07bff9006f3800326","art_kind":"png","art_width":3650,"art_height":2280},"vol1:fig-bio-nn2ai-nn":{"key":"vol1:fig-bio-nn2ai-nn","figure_id":"fig-bio-nn2ai-nn","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Biological-to-Artificial Neuron Mapping","status":"ready","treatment":"annotated","question":"Which biological ideas survive the arithmetic abstraction?","scope":"A mathematical analogy, not a faithful electrochemical model of biological neurons.","regions":{"bio":{"x":0.0,"y":0.0,"w":0.42,"h":0.99,"label":"Biological neuron"},"mapping":{"x":0.44,"y":0.07,"w":0.15,"h":0.85,"label":"Structure-to-arithmetic mapping"},"inputs":{"x":0.61,"y":0.13,"w":0.18,"h":0.8,"label":"Artificial inputs and weighted edges"},"sum":{"x":0.77,"y":0.38,"w":0.11,"h":0.33,"label":"Linear sum and activation"},"output":{"x":0.88,"y":0.39,"w":0.12,"h":0.22,"label":"Artificial output"}},"steps":[{"title":"Start from the biological roles","description":"Dendrites receive signals and the axon carries output. The biological drawing contains structure that the arithmetic model does not attempt to reproduce.","focus":["bio"]},{"title":"Map roles onto arithmetic","description":"The central labels pair dendrites with inputs, synapses with weights, soma with a linear sum, and firing with activation. These are abstraction choices.","focus":["mapping","inputs"]},{"title":"Follow the artificial signal path","description":"Weighted inputs meet at the linear sum, including the constant bias input. The activation then transforms that sum into an output.","focus":["inputs","sum","output"]}],"artwork_reviewed":true,"art_sha1":"6d54df661f6d012d8010dcfc5faccbbb1a855824","art_kind":"svg","art_width":1200,"art_height":443,"art_structural_sha1":"baaffacf3fea7dc6bfb72d6007e6c23a1736c34c"},"vol1:fig-block-sparse-gemm":{"key":"vol1:fig-block-sparse-gemm","figure_id":"fig-block-sparse-gemm","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Block Sparse Representation","status":"ready","treatment":"annotated","question":"How does block metadata connect stored weights to an output dot product?","scope":"The 3 by 3 tiles are a teaching representation, not a claim of native hardware support. Kernel shape, layout, and data type determine actual benefit.","regions":{"matrix":{"x":0,"y":0.5,"w":0.31,"h":0.37,"label":"Block-sparse weight matrix"},"values":{"x":0.39,"y":0.5,"w":0.21,"h":0.37,"label":"Packed nonzero values"},"indices":{"x":0.62,"y":0.5,"w":0.08,"h":0.37,"label":"Block index metadata"},"input":{"x":0.85,"y":0,"w":0.15,"h":0.4,"label":"Input activations"},"selected":{"x":0.38,"y":0.48,"w":0.34,"h":0.17,"label":"Selected stored block row and index"},"output":{"x":0.85,"y":0.49,"w":0.15,"h":0.38,"label":"Output activations"}},"steps":[{"title":"Identify empty blocks","description":"The left weight matrix contains dense colored sub-blocks and empty gray blocks. Grouping zeros makes regular blocks the unit the representation can skip.","focus":["matrix"]},{"title":"Store values with their coordinates","description":"The middle representation packs nonzero data separately from Block indices. Metadata is necessary to recover where those stored values belong in the logical matrix.","focus":["values","indices"]},{"title":"Match values to input positions","description":"The red outline links a selected stored region and its block metadata with an input activation column. A kernel uses this correspondence to form the required dot product.","focus":["selected","input"]},{"title":"Accumulate the output","description":"The highlighted output entry receives the matched contributions. Skipping empty blocks can save work, but the metadata and supported block execution remain part of the cost.","focus":["output","indices"]}],"artwork_reviewed":true,"art_sha1":"048cb768d0cbca653d57a741e30b10ed0e871c82","art_kind":"svg","art_width":1200,"art_height":991,"art_structural_sha1":"addb728c2e9a87a5a8970bfe2dea4fb77d0f5f85"},"vol1:fig-broadcasting-rules":{"key":"vol1:fig-broadcasting-rules","figure_id":"fig-broadcasting-rules","source":"books/vol1/backmatter/appendix_algorithm.qmd","title":"Tensor Broadcasting Rules","status":"ready","treatment":"annotated","question":"Which storage is reused, and which storage is allocated by broadcasting?","scope":"Stride-zero virtual views for shapes (3,1) and (1,4); no physical input replication is implied.","regions":{"a":{"x":0.0,"y":0.0,"w":0.16,"h":0.91,"label":"Tensor A: shape (3,1)"},"b":{"x":0.17,"y":0.0,"w":0.35,"h":0.44,"label":"Tensor B: shape (1,4)"},"result":{"x":0.6,"y":0.0,"w":0.4,"h":0.92,"label":"Allocated (3,4) result"},"firstrow":{"x":0.6,"y":0.15,"w":0.4,"h":0.22,"label":"Result row using A0"},"firstcolumn":{"x":0.6,"y":0.15,"w":0.1,"h":0.74,"label":"Result column using B0"},"note":{"x":0.13,"y":0.91,"w":0.85,"h":0.08,"label":"Stride-zero and allocation note"}},"steps":[{"title":"Compare singleton dimensions","description":"A has three rows and one column; B has one row and four columns. Complementary singleton dimensions are compatible, yielding a (3,4) result.","focus":["a","b"]},{"title":"Reuse an operand across output positions","description":"Every cell in the first result row reads A0, while every cell in the first column reads B0. Stride-zero views expose those repeated reads without copying input buffers.","focus":["firstrow","firstcolumn"]},{"title":"Allocate the actual result","description":"The twelve pairwise sums occupy the result grid. Virtual expansion saves replicated input storage; it does not remove result allocation or the arithmetic required for the output.","focus":["result","note"]}],"artwork_reviewed":true,"art_sha1":"b7b42b3da126e6fa5a073301ac5935fa81a14422","art_kind":"svg","art_width":1200,"art_height":383,"art_structural_sha1":"b7b42b3da126e6fa5a073301ac5935fa81a14422"},"vol1:fig-business-cost-curve":{"key":"vol1:fig-business-cost-curve","figure_id":"fig-business-cost-curve","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"The Business Cost Curve","status":"ready","treatment":"annotated","question":"Why can an economically useful threshold differ from the symmetric one?","scope":"Equal-class-weighted illustrative cost index, not population expected cost; prevalence must be included before extending this result to a deployment.","regions":{"fp":{"x":0.06,"y":0.58,"w":0.52,"h":0.24,"label":"False-positive cost term"},"fn":{"x":0.52,"y":0.13,"w":0.4,"h":0.69,"label":"False-negative cost term"},"minimum":{"x":0.28,"y":0.57,"w":0.17,"h":0.17,"label":"Marked minimum near 0.34"},"total":{"x":0.5,"y":0.08,"w":0.43,"h":0.6,"label":"Total-cost curve"},"legend":{"x":0.06,"y":0.01,"w":0.46,"h":0.2,"label":"Cost definitions"}},"steps":[{"title":"Keep decision and model separate","description":"A transaction is flagged when its fixed score exceeds the threshold. Lowering the threshold changes the decision policy, increasing flags without changing the scores themselves.","focus":["legend","fp"]},{"title":"Balance differently priced mistakes","description":"The dashed false-positive term falls as the threshold rises, while the false-negative term rises. Missing fraud costs more per incident in this illustration.","focus":["fp","fn"]},{"title":"Read the declared minimum with its scope","description":"Their sum reaches the marked minimum near 0.34, left of the equal-cost 0.50 baseline. This is an equal-class-weighted index; a population optimum also depends on class prevalence.","focus":["minimum","total"]}],"artwork_reviewed":true,"art_sha1":"dce703e8dc34387e3412b0c78aed675b7dbea0be","art_kind":"png","art_width":3381,"art_height":2234},"vol1:fig-calibration-ranges":{"key":"vol1:fig-calibration-ranges","figure_id":"fig-calibration-ranges","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Calibration Range Selection","status":"ready","treatment":"annotated","question":"How does an affine zero-point preserve real zero in a non-centered range?","scope":"Printed ranges illustrate symmetric and asymmetric affine maps. Rounding conventions and saturation must still match the deployed kernel.","regions":{"symmetric":{"x":0,"y":0.02,"w":0.48,"h":0.96,"label":"Symmetric mapping"},"symmetriczero":{"x":0.22,"y":0.05,"w":0.05,"h":0.89,"label":"Symmetric zero mapping"},"asymmetric":{"x":0.51,"y":0.02,"w":0.49,"h":0.96,"label":"Asymmetric mapping"},"realzero":{"x":0.67,"y":0.05,"w":0.05,"h":0.89,"label":"Real zero maps to integer z"},"integerzero":{"x":0.74,"y":0.05,"w":0.05,"h":0.89,"label":"Integer zero has a shifted real coordinate"}},"steps":[{"title":"Use equal-magnitude bounds","description":"The left mapping spans real values from -1 to 1 and integer values from -127 to 127. Real zero maps to integer zero in the symmetric case.","focus":["symmetric","symmetriczero"]},{"title":"Shift the represented interval","description":"The right mapping spans real values from -0.5 to 1.5. A generally nonzero zero-point lets a single scale represent this non-centered interval.","focus":["asymmetric"]},{"title":"Preserve exact zero","description":"The green real-zero marker maps to the integer z marker. Integer zero therefore need not correspond to real zero in the asymmetric map.","focus":["realzero","integerzero"]}],"artwork_reviewed":true,"art_sha1":"a254db71e22a2988d8cdbea11360f586e4caa754","art_kind":"svg","art_width":1200,"art_height":238,"art_structural_sha1":"b86c1cf18f958a2ea172746da8262df5dda78922"},"vol1:fig-cascades":{"key":"vol1:fig-cascades","figure_id":"fig-cascades","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Data Quality Cascades","status":"ready","treatment":"annotated","question":"How can a defect introduced early force work to be repeated late?","scope":"Arcs indicate possible cascades, not measured failure probabilities or rework costs.","regions":{"origin":{"x":0.0,"y":0.46,"w":0.2,"h":0.44,"label":"Problem statement and collection"},"middle":{"x":0.21,"y":0.39,"w":0.27,"h":0.52,"label":"Analysis and model selection"},"late":{"x":0.42,"y":0.29,"w":0.27,"h":0.62,"label":"Training through deployment"},"restart":{"x":0.02,"y":0.0,"w":0.65,"h":0.68,"label":"Dashed restart paths"},"legend":{"x":0.74,"y":0.0,"w":0.26,"h":1,"label":"Cascade legend"}},"steps":[{"title":"Find the defect origin","description":"Problem statement and Data collection and labeling sit at the start of the timeline. A defect here can survive later processing rather than producing an immediate software exception.","focus":["origin"]},{"title":"Follow the cascade","description":"Colored arcs bypass intermediate stages and terminate around evaluation and deployment. Their colors distinguish the failure sources listed in the legend, not severity scores.","focus":["late","legend"]},{"title":"Account for rework","description":"The red dashed paths return from a later stage toward earlier work. Late detection can require rebuilding data and rerunning dependent work; it does not imply every defect forces abandonment.","focus":["restart","middle"]}],"artwork_reviewed":true,"art_sha1":"9a612e5eaf2104a4bbea3531eaffe12dfec31f3c","art_kind":"svg","art_width":1200,"art_height":349,"art_structural_sha1":"1de69fed7fbf75dca2f3f2d6d52b4a01d7de6a98"},"vol1:fig-channel-layer-pruning":{"key":"vol1:fig-channel-layer-pruning","figure_id":"fig-channel-layer-pruning","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Channel vs. Layer Pruning","status":"ready","treatment":"annotated","question":"How does removing a channel differ from removing a complete layer?","scope":"The diagram shows structural rewrites, not measured proportional latency savings. Fine-tuning and interface validation remain necessary.","regions":{"channel_initial":{"x":0,"y":0.01,"w":0.47,"h":0.26,"label":"Selected channel"},"channel_adjust":{"x":0,"y":0.36,"w":0.47,"h":0.3,"label":"Channel removal and reconfiguration"},"channel_final":{"x":0,"y":0.73,"w":0.47,"h":0.27,"label":"Narrower dense network"},"layer_initial":{"x":0.54,"y":0.01,"w":0.46,"h":0.26,"label":"Selected full layer"},"layer_final":{"x":0.54,"y":0.37,"w":0.46,"h":0.63,"label":"Layer removal and rewiring"}},"steps":[{"title":"Choose a granularity","description":"The left red slice selects one channel; the right red group selects an entire layer. These cuts remove different amounts and kinds of structure.","focus":["channel_initial","layer_initial"]},{"title":"Contract feature depth","description":"Channel pruning removes a feature slice and adjusts connected tensors. The resulting network keeps the overall sequence of layers with narrower dense shapes.","focus":["channel_adjust","channel_final"]},{"title":"Bypass a complete stage","description":"Layer pruning removes all channels in one stage and rewires the graph. Remaining stages must accept the new interfaces and recover the removed function.","focus":["layer_final"]},{"title":"Profile the rewritten model","description":"Both final structures reduce nominal work. Actual latency depends on the resulting dimensions, kernels, memory traffic, and task-quality recovery.","focus":["channel_final","layer_final"]}],"artwork_reviewed":true,"art_sha1":"253095cc01ea18ca959dd2d5039a9a488f89bf4d","art_kind":"svg","art_width":1200,"art_height":762,"art_structural_sha1":"a9c3e785068e1454b0fde9c0b6d404ce02518da5"},"vol1:fig-clinaiops":{"key":"vol1:fig-clinaiops","figure_id":"fig-clinaiops","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"ClinAIOps Feedback Loops","status":"ready","treatment":"annotated","question":"How are clinical authority and developer feedback kept distinct?","scope":"Proposed clinical workflow requiring validation in its intended setting; no autonomous prescribing or clinical efficacy is implied.","regions":{"patient":{"x":0.4,"y":0.0,"w":0.18,"h":0.3,"label":"Patient"},"clinician":{"x":0.16,"y":0.49,"w":0.18,"h":0.3,"label":"Clinician"},"developer":{"x":0.66,"y":0.49,"w":0.21,"h":0.3,"label":"AI developer"},"care":{"x":0.0,"y":0.08,"w":0.41,"h":0.47,"label":"Patient–clinician exchange"},"telemetry":{"x":0.54,"y":0.07,"w":0.45,"h":0.48,"label":"Patient–developer exchange"},"governance":{"x":0.29,"y":0.72,"w":0.5,"h":0.27,"label":"Clinician–developer limits and summaries"}},"steps":[{"title":"Keep the care relationship explicit","description":"The patient–clinician pair exchanges health challenges and goals with therapy regimens. The clinical relationship supplies treatment authority rather than delegating it silently to software.","focus":["patient","clinician","care"]},{"title":"Separate telemetry from approved alerts","description":"The patient–developer exchange carries monitoring data and health reports in one direction and clinician-approved therapy-update alerts in the other. Monitoring data is not itself treatment authorization.","focus":["patient","developer","telemetry"]},{"title":"Close the governance loop","description":"Clinicians provide limits and approvals while developers return monitoring summaries and therapy-modification alerts. The developer loop supports operation inside clinical bounds.","focus":["clinician","developer","governance"]}],"artwork_reviewed":true,"art_sha1":"6ecad80057c51ed3c8946218df1d0684c1925b00","art_kind":"svg","art_width":1200,"art_height":940,"art_structural_sha1":"3951ad5133456775770d8f0207137485452b730a"},"vol1:fig-cloud-edge-TinyML-comparison":{"key":"vol1:fig-cloud-edge-TinyML-comparison","figure_id":"fig-cloud-edge-TinyML-comparison","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Distributed Intelligence Spectrum","status":"ready","treatment":"annotated","question":"Where can computation move when distance and resource budgets change?","scope":"The spans overlap: edge describes locality, while mobile and TinyML also impose device resource envelopes. Position is not measured latency.","regions":{"tiny":{"x":0.03,"y":0.04,"w":0.2,"h":0.91,"label":"Ultra-low-power devices and TinyML"},"device":{"x":0.25,"y":0.1,"w":0.16,"h":0.7,"label":"Intelligent device"},"local":{"x":0.44,"y":0.1,"w":0.31,"h":0.7,"label":"Gateway and on-premises servers"},"cloud":{"x":0.77,"y":0.08,"w":0.2,"h":0.85,"label":"Cloud"},"edge":{"x":0.03,"y":0.83,"w":0.75,"h":0.16,"label":"Edge AI span"}},"steps":[{"title":"Start at the sensor","description":"Ultra-Low-Power Devices and Sensors occupy the left end. TinyML keeps inference close to sensing but must fit the smallest memory and power envelopes.","focus":["tiny"]},{"title":"Add local resources","description":"Intelligent Device, Gateway, and On-Premises Servers add local processing options. Their proximity can avoid transmitting every raw sample to a distant cloud.","focus":["device","local"]},{"title":"Read the overlapping span","description":"The Edge AI arrow crosses several device types. It identifies proximity to data, rather than one particular processor size.","focus":["edge"]},{"title":"Centralize at cloud scale","description":"Cloud AI pools remote resources. It offers capacity and elasticity while introducing network dependence and a longer communication path.","focus":["cloud"]}],"artwork_reviewed":true,"art_sha1":"acb5a80befab41f228493029638146e737b671ba","art_kind":"svg","art_width":1200,"art_height":226,"art_structural_sha1":"f01c3bf140d9730a94d5fac8a19ad2d0eb0e7d45"},"vol1:fig-cloud-ml":{"key":"vol1:fig-cloud-ml","figure_id":"fig-cloud-ml","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Cloud ML Constraint Map","status":"ready","treatment":"annotated","question":"Which constraints does cloud deployment solve, and which does it introduce?","scope":"The branches organize deployment considerations; they are not a measured performance ranking or an automatic architecture recommendation.","regions":{"binding":{"x":0.02,"y":0.18,"w":0.18,"h":0.81,"label":"Binding constraints"},"response":{"x":0.29,"y":0.18,"w":0.18,"h":0.81,"label":"System responses"},"boundary":{"x":0.56,"y":0.18,"w":0.18,"h":0.81,"label":"Failure boundaries"},"workloads":{"x":0.83,"y":0.18,"w":0.17,"h":0.81,"label":"Workloads that fit"}},"steps":[{"title":"Recognize a scale requirement","description":"The binding branch lists scale beyond local machines, centralized data or state, relaxed latency, and elastic usage. These conditions motivate resource pooling.","focus":["binding"]},{"title":"Pool and partition work","description":"Pool Accelerators and Storage and Shard Data and Models describe responses to scale. Centralized scheduling and operations coordinate the pooled resources.","focus":["response"]},{"title":"Check the distance penalty","description":"Speed-of-Light Latency and Internet Dependence remain failure boundaries. Data sovereignty and utilization-driven cost can rule out cloud placement even when compute fits.","focus":["boundary"]},{"title":"Validate the workload match","description":"The examples include large-model training and recommendation systems. They are plausible fits only after checking the constraints for the actual application.","focus":["workloads","binding","boundary"]}],"artwork_reviewed":true,"art_sha1":"093beb92b9d79f07c2792068e740f45c3f14f5df","art_kind":"svg","art_width":1200,"art_height":502,"art_structural_sha1":"734997cd5e49257916f689e20f38a872bec456c7"},"vol1:fig-cnn":{"key":"vol1:fig-cnn","figure_id":"fig-cnn","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Convolution Operation","status":"ready","treatment":"annotated","question":"Which input values contribute to the highlighted output cell?","scope":"Valid 3×3 convolution on a 7×7 input; no numeric filter weights are supplied.","regions":{"patch":{"x":0.25,"y":0.58,"w":0.5,"h":0.24,"label":"Orange receptive field"},"connections":{"x":0.27,"y":0.16,"w":0.47,"h":0.57,"label":"Input-to-output correspondence"},"output":{"x":0.38,"y":0.1,"w":0.1,"h":0.1,"label":"Highlighted violet output cell"}},"steps":[{"title":"Nine neighboring inputs","description":"The orange 3×3 patch contains the nine spatial positions used for one output value per input channel.","focus":["patch"]},{"title":"One patch maps to one output","description":"The blue guide lines associate this patch with the violet cell in the 5×5 output. The figure depicts dependency, not physical data-transfer paths.","focus":["connections","output"]},{"title":"Share weights across positions","description":"The same learned filter is applied at other valid input positions. This reuse yields translation equivariance without allocating a separate filter for each position.","focus":["patch","output"]}],"artwork_reviewed":true,"art_sha1":"ed68d91f1c29fc166e35c5d9dc6d1cbeac3d16d7","art_kind":"svg","art_width":1200,"art_height":907,"art_structural_sha1":"757a8fbd32a980bc43c59cfd616836d0005f15e6"},"vol1:fig-cnn-spatial-processing":{"key":"vol1:fig-cnn-spatial-processing","figure_id":"fig-cnn-spatial-processing","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Spatial Feature Extraction","status":"ready","treatment":"annotated","question":"Where does spatial feature extraction become classification?","scope":"Schematic image classifier; the displayed probabilities illustrate the final output, not a measured zebra prediction.","regions":{"early":{"x":0,"y":0.18,"w":0.25,"h":0.42,"label":"Input and first convolution"},"features":{"x":0.25,"y":0.18,"w":0.35,"h":0.45,"label":"Convolution and pooling feature maps"},"flatten":{"x":0.59,"y":0.08,"w":0.06,"h":0.66,"label":"Flatten layer"},"dense":{"x":0.65,"y":0,"w":0.23,"h":0.82,"label":"Fully connected layers"},"softmax":{"x":0.88,"y":0.25,"w":0.12,"h":0.45,"label":"Softmax output"}},"steps":[{"title":"Reuse local filters","description":"The kernel samples a local patch of the zebra image. Convolution and ReLU create feature maps rather than immediately choosing a class.","focus":["early"]},{"title":"Transform spatial maps","description":"Repeated convolution and pooling stages carry spatial features forward while changing their representation. Pooling and convolution have different roles despite their neighboring positions.","focus":["features"]},{"title":"Cross the representation boundary","description":"Flattening rearranges feature-map entries into a vector consumed by dense layers; it is a layout transformation rather than a learned classifier by itself.","focus":["flatten","dense"]},{"title":"Produce class probabilities","description":"The final softmax converts classifier scores into the Horse, Zebra, and Dog probability vector.","focus":["softmax"]}],"artwork_reviewed":true,"art_sha1":"98957a91417344f2076e406880ac5df0643a9b64","art_kind":"svg","art_width":1200,"art_height":463,"art_structural_sha1":"fe3d08e72b36af2a8b19783a130405dae5e5fcce"},"vol1:fig-collective-comm":{"key":"vol1:fig-collective-comm","figure_id":"fig-collective-comm","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Data Movement Primitives","status":"ready","treatment":"annotated","question":"When does data movement copy, partition, collect, or combine values?","scope":"Four schematic primitives; arrow positions do not encode latency or bandwidth.","regions":{"broadcast":{"x":0,"y":0,"w":0.4,"h":0.49,"label":"Broadcast"},"scatter":{"x":0.61,"y":0,"w":0.39,"h":0.49,"label":"Scatter"},"gather":{"x":0,"y":0.51,"w":0.4,"h":0.49,"label":"Gather"},"reduction":{"x":0.61,"y":0.51,"w":0.39,"h":0.49,"label":"Reduction"}},"steps":[{"title":"Broadcast replicates; scatter partitions","description":"Broadcast sends the same red value to every destination. Scatter sends different elements from a collection to different destinations.","focus":["broadcast","scatter"]},{"title":"Gather preserves separate elements","description":"The bottom-left destination receives the red, yellow, green, and blue entries together. Collecting does not imply performing arithmetic on their values.","focus":["gather"]},{"title":"Reduction combines values","description":"The bottom-right primitive sums 1, 3, 5, and 7 into 16. The result is an aggregate rather than the original list.","focus":["reduction"]}],"artwork_reviewed":true,"art_sha1":"ceb18a44ca626f10c7bcf2d5fbf37e214c1e2001","art_kind":"svg","art_width":1200,"art_height":637,"art_structural_sha1":"e82dfc5f16516431a5a72bbf9c67507e74ce8c71"},"vol1:fig-color-mapping":{"key":"vol1:fig-color-mapping","figure_id":"fig-color-mapping","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"First-Layer Convolutional Filter Patterns","status":"ready","treatment":"annotated","question":"Why is a uniform-looking filter not enough evidence for pruning?","scope":"These stylized kernels are diagnostic illustrations, not measured activations or verified inactive filters.","regions":{"edge":{"x":0,"y":0.11,"w":1,"h":0.16,"label":"Oriented-edge patterns"},"color":{"x":0,"y":0.28,"w":1,"h":0.16,"label":"Color-blob patterns"},"frequency":{"x":0,"y":0.44,"w":1,"h":0.16,"label":"Frequency patterns"},"mixed":{"x":0,"y":0.61,"w":1,"h":0.16,"label":"Mixed-feature patterns"},"uniform":{"x":0,"y":0.78,"w":1,"h":0.16,"label":"Uniform-looking filters"}},"steps":[{"title":"Recognize visual pattern families","description":"The top rows group oriented edges, color blobs, and frequency-like patterns. Their appearance describes weight organization rather than measured task contribution.","focus":["edge","color","frequency"]},{"title":"Inspect mixed features","description":"The Mixed features row combines less easily classified patterns. A simple visual taxonomy does not determine importance.","focus":["mixed"]},{"title":"Treat uniformity as a question","description":"The final row is labeled Uniform-looking and Check activations. Low visual variance can motivate investigation, but cannot establish inactivity.","focus":["uniform"]},{"title":"Require behavioral evidence","description":"Before removing a candidate, measure activations or importance and validate task quality after the change. No row in this grid is automatically safe to delete.","focus":["uniform","mixed"]}],"artwork_reviewed":true,"art_sha1":"306c87d78433c225ebb5bed28fb0637eb458c350","art_kind":"svg","art_width":1200,"art_height":770,"art_structural_sha1":"95ffb936805a780ea8077321dc484c646aac0189"},"vol1:fig-communication-tax":{"key":"vol1:fig-communication-tax","figure_id":"fig-communication-tax","source":"books/vol1/08_training/08_training.qmd","title":"Communication Overhead","status":"ready","treatment":"annotated","question":"Why can adding GPUs deliver diminishing speedup?","scope":"A fixed-fraction Amdahl model is illustrative; real communication depends on topology, message size, count, and overlap.","regions":{"legend":{"x":0.12,"y":0.01,"w":0.41,"h":0.29,"label":"Modeled scaling regimes"},"ideal":{"x":0.6,"y":0.0,"w":0.36,"h":0.3,"label":"Ideal linear reference"},"compute":{"x":0.49,"y":0.36,"w":0.47,"h":0.19,"label":"Compute-heavy curve"},"comm":{"x":0.49,"y":0.57,"w":0.47,"h":0.28,"label":"Larger non-scaling fractions"}},"steps":[{"title":"Establish the reference","description":"The dashed Ideal Linear line assumes work scales perfectly with GPU count. Both axes are logarithmic, so each doubling is an equal step.","focus":["ideal"]},{"title":"Read the model assumptions","description":"The legend identifies three illustrative regimes. A compute-heavy case retains more scaling benefit than a case with a larger non-scaling fraction.","focus":["legend","compute"]},{"title":"Find the remaining floor","description":"The lower curves flatten as parallel compute shrinks around work that does not scale. Their separation from ideal is an Amdahl-style consequence, not a measured network tax that can be read as a fixed hardware constant.","focus":["comm"]}],"artwork_reviewed":true,"art_sha1":"5a19f69f3e1183e91298d5bd03092275561852b1","art_kind":"png","art_width":3316,"art_height":2041},"vol1:fig-comp-graph":{"key":"vol1:fig-comp-graph","figure_id":"fig-comp-graph","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"Simple Computational Graph","status":"ready","treatment":"annotated","question":"What does a dependency graph tell the runtime before it schedules work?","scope":"The graph specifies dependencies, not device placement or elapsed time.","regions":{"x":{"x":0,"y":0.0,"w":0.15,"h":0.37,"label":"Input x"},"y":{"x":0,"y":0.62,"w":0.15,"h":0.37,"label":"Input y"},"f":{"x":0.39,"y":0.15,"w":0.25,"h":0.7,"label":"Function f(x,y)"},"z":{"x":0.85,"y":0.31,"w":0.15,"h":0.4,"label":"Output z"}},"steps":[{"title":"Require both inputs","description":"The arrows into f(x,y) identify the values the operation consumes. Neither arrow specifies how long the operation takes.","focus":["x","y","f"]},{"title":"Evaluate the operation","description":"The runtime may schedule f only after its required inputs are available. The function node separates mathematical work from the hardware that will perform it.","focus":["f"]},{"title":"Publish the result","description":"The outgoing edge makes z available to later consumers. This dependency is the structure a framework uses for scheduling and differentiation.","focus":["f","z"]}],"artwork_reviewed":true,"art_sha1":"63d68799651df693085ae18f98ce7b9f44ec1b2c","art_kind":"svg","art_width":1200,"art_height":441,"art_structural_sha1":"2c33d24ec569a233a40bdf083943c5e0a9cb508d"},"vol1:fig-compilation-continuum":{"key":"vol1:fig-compilation-continuum","figure_id":"fig-compilation-continuum","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"The Compilation Continuum","status":"ready","treatment":"annotated","question":"When can repeated execution repay compilation cost?","scope":"Illustrative arbitrary-unit model, not a measured benchmark or a forecast for a particular model.","regions":{"eager":{"x":0.09,"y":0.75,"w":0.59,"h":0.18,"label":"Low-reuse eager region"},"jit":{"x":0.81,"y":0.53,"w":0.07,"h":0.32,"label":"Eager/JIT crossover"},"aot":{"x":0.91,"y":0.28,"w":0.05,"h":0.57,"label":"JIT/AOT crossover"},"intercepts":{"x":0.11,"y":0.56,"w":0.2,"h":0.29,"label":"Upfront cost offsets"}},"steps":[{"title":"Pay once before reuse","description":"JIT and AOT start above eager because their one-time compilation cost is nonzero. Their lower execution cost matters only after enough reuse.","focus":["intercepts"]},{"title":"Prefer eager at low counts","description":"The blue eager curve is lowest in the broad left region. Avoiding compilation wins while the program runs too few times to repay the upfront work.","focus":["eager"]},{"title":"Cross into JIT","description":"Near the first dotted boundary, the orange JIT curve falls below eager in total cost. The horizontal axis is logarithmic, so equal spacing does not mean equal additional executions.","focus":["jit"]},{"title":"Amortize the larger AOT cost","description":"At the right boundary, the green AOT curve becomes lowest. Changing compilation or execution costs moves both crossover points.","focus":["aot"]}],"artwork_reviewed":true,"art_sha1":"7ab4ea99f3ee30a76f4e6f9032137a86f6464452","art_kind":"png","art_width":3389,"art_height":2286},"vol1:fig-compression-methods":{"key":"vol1:fig-compression-methods","figure_id":"fig-compression-methods","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Compression Methods in One Reported Setting","status":"ready","treatment":"annotated","question":"What can one reported size-quality curve say about combining methods?","scope":"This is one model- and implementation-specific comparison. The plotted curves do not establish transformation order or a universal ranking.","regions":{"combined":{"x":0.13,"y":0.13,"w":0.21,"h":0.1,"label":"Combined near-baseline plateau"},"pruning":{"x":0.18,"y":0.12,"w":0.39,"h":0.74,"label":"Pruning-only curve"},"quantization":{"x":0.32,"y":0.12,"w":0.67,"h":0.74,"label":"Quantization-only curve"},"svd":{"x":0.69,"y":0.23,"w":0.3,"h":0.63,"label":"SVD curve"},"axis":{"x":0.1,"y":0.86,"w":0.89,"h":0.14,"label":"Model-size ratio"}},"steps":[{"title":"Read compressed size correctly","description":"The horizontal axis is the remaining model-size ratio, so moving left means a smaller representation. The vertical axis is accuracy change rather than absolute accuracy.","focus":["axis"]},{"title":"Inspect the combined setting","description":"Pruning + Quantization stays near baseline accuracy down to a smaller size ratio in this reported setting. The plateau is evidence for this comparison, not every model.","focus":["combined"]},{"title":"Compare the individual alternatives","description":"Pruning Only, Quantization Only, and SVD have different curves and cliffs. Their relative performance depends on the chosen setting and implementation.","focus":["pruning","quantization","svd"]},{"title":"Avoid inferring a schedule","description":"The plot compares outcomes; it does not show which method was applied first or hold every recovery budget fixed. Use it to motivate validation of a combined candidate.","focus":["combined","axis"]}],"artwork_reviewed":true,"art_sha1":"6c50407a622c27f47c978ff96eb52ee77a4d52be","art_kind":"svg","art_width":1200,"art_height":607,"art_structural_sha1":"a846077b75fac205bf78baff1d57dad6f242c0d8"},"vol1:fig-compression-waterfall":{"key":"vol1:fig-compression-waterfall","figure_id":"fig-compression-waterfall","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Compression Waterfall for the Camera Pipeline","status":"ready","treatment":"annotated","question":"Which model change crosses the camera's frame deadline in this scenario?","scope":"Weight bytes follow parameter counts; hatched times are scaled illustrative estimates. INT8 also changes the device path, and folding/fusion gains are not modeled.","regions":{"memory":{"x":0,"y":0.03,"w":0.49,"h":0.97,"label":"Weight memory stages"},"fp32":{"x":0.63,"y":0.13,"w":0.08,"h":0.86,"label":"FP32 CPU frame"},"pruned":{"x":0.75,"y":0.32,"w":0.08,"h":0.67,"label":"Channel-pruned CPU frame"},"int8":{"x":0.87,"y":0.67,"w":0.08,"h":0.32,"label":"Pruned INT8 accelerator frame"},"budget":{"x":0.59,"y":0.6,"w":0.39,"h":0.07,"label":"33 ms frame budget"}},"steps":[{"title":"Separate weights from frame time","description":"The left panel falls from 14.0 MB to 10.4 MB to 2.6 MB. These are weight footprints, not measurements of total live memory.","focus":["memory"]},{"title":"See why pruning alone is insufficient","description":"The CPU frame drops from 125 ms to 87 ms in the modeled pruning step. Both remain above the 33 ms deadline even though the model is smaller.","focus":["fp32","pruned","budget"]},{"title":"Cross the deadline on the INT8 path","description":"Pruned INT8 on the accelerator reaches the illustrated 20 ms frame. This step changes both value precision and execution device, so it is not an isolated quantization speedup.","focus":["int8","budget"]},{"title":"Read the hatching as an assumption","description":"The later frame-time bars are hatched because they scale the running case by retained arithmetic. Real deployment needs profiling and full-path validation.","focus":["pruned","int8"]}],"artwork_reviewed":true,"art_sha1":"b044f5bab2f3a868535803b26b99e0a38be12c21","art_kind":"png","art_width":3659,"art_height":2220},"vol1:fig-compute-optimal-frontier":{"key":"vol1:fig-compute-optimal-frontier","figure_id":"fig-compute-optimal-frontier","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"Illustrative Compute-Optimal Frontier","status":"ready","treatment":"annotated","question":"Why can two systems below a frontier require different interventions?","scope":"Conceptual normalized-compute illustration, not a fitted Chinchilla result or a guaranteed intervention trajectory.","regions":{"frontier":{"x":0.13,"y":0.06,"w":0.84,"h":0.7,"label":"Conceptual compute-optimal frontier"},"compute":{"x":0.28,"y":0.46,"w":0.26,"h":0.27,"label":"Compute-starved point and arrow"},"data":{"x":0.6,"y":0.31,"w":0.2,"h":0.26,"label":"Data-starved point and arrow"}},"steps":[{"title":"Read the same budget correctly","description":"At a given horizontal compute coordinate, height denotes model performance. The green curve represents a conceptual best allocation rather than measured universal limits.","focus":["frontier"]},{"title":"Distinguish a compute constraint","description":"The red compute-starved point is paired with a more-training arrow that moves both right and up. This intervention spends more compute rather than claiming free quality.","focus":["compute"]},{"title":"Distinguish a data constraint","description":"The orange better-selection arrow rises at the same plotted compute coordinate. It illustrates reallocating a fixed budget toward more useful data, not a guarantee that selection reaches the frontier.","focus":["data"]}],"artwork_reviewed":true,"art_sha1":"c0e3c3bb2a688f777d78b36ab96f3d28c5c3cd52","art_kind":"png","art_width":3398,"art_height":2095},"vol1:fig-connections":{"key":"vol1:fig-connections","figure_id":"fig-connections","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Fully Connected Layers","status":"ready","treatment":"annotated","question":"How does dense connectivity determine parameter storage?","scope":"Printed numbers illustrate parameter placement, not a consistent worked numerical forward pass.","regions":{"input":{"x":0.0,"y":0.18,"w":0.1,"h":0.72,"label":"Three input units"},"first":{"x":0.1,"y":0.1,"w":0.37,"h":0.77,"label":"First-layer dense connections"},"hidden":{"x":0.44,"y":0.0,"w":0.12,"h":0.99,"label":"Four hidden units and biases"},"second":{"x":0.56,"y":0.15,"w":0.34,"h":0.72,"label":"Second-layer dense connections"},"output":{"x":0.87,"y":0.12,"w":0.13,"h":0.76,"label":"Two output units and biases"}},"steps":[{"title":"Read one destination’s incoming edges","description":"Each hidden unit receives all three inputs. Its incoming edge weights form one column of the first weight matrix; its bias is additional state.","focus":["input","first","hidden"]},{"title":"Repeat for all destinations","description":"Four hidden units require a 3×4 matrix before biases. The next layer connects four hidden outputs to each of two destinations, requiring a 4×2 matrix.","focus":["first","second"]},{"title":"Distinguish weights from activations","description":"Edges label weights and nodes label activations; bias labels sit near their destination units. The network has two layers of weights although three layers of units are drawn.","focus":["hidden","output"]}],"artwork_reviewed":true,"art_sha1":"a3befe3df868bd43c6854884ac86db6001c540c9","art_kind":"svg","art_width":1200,"art_height":715,"art_structural_sha1":"872d84edb5171ef26a81c5071b3f495afcbbf490"},"vol1:fig-context-memory":{"key":"vol1:fig-context-memory","figure_id":"fig-context-memory","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Three Memory Regimes of a Long Context","status":"ready","treatment":"annotated","question":"Which memory term dominates as context length increases?","scope":"GPT-2 XL shape in FP16 beyond its trained context; scores are for one materialized layer, cache for one request, not total training memory.","regions":{"weights":{"x":0.12,"y":0.44,"w":0.39,"h":0.045,"label":"Fixed weights"},"kv-cross":{"x":0.4,"y":0.35,"w":0.19,"h":0.18,"label":"KV cache crosses weights"},"score-cross":{"x":0.44,"y":0.08,"w":0.45,"h":0.2,"label":"Materialized scores reach device capacity"},"legend":{"x":0.38,"y":0.65,"w":0.59,"h":0.25,"label":"Three memory categories"}},"steps":[{"title":"Separate the allocations","description":"The blue weights remain fixed; the orange request cache grows linearly; the red dashed single-layer score matrix grows quadratically. These are different objects and lifetimes.","focus":["legend","weights"]},{"title":"Cache can exceed the model weights","description":"Near the labeled 10K-token crossing, the persistent cache for one request becomes larger than the FP16 weights.","focus":["kv-cross"]},{"title":"Avoid materializing quadratic scores","description":"The red score curve reaches the device-memory line near 41K tokens. Tiled attention avoids storing this full matrix; it does not remove the need for per-request KV state.","focus":["score-cross"]}],"artwork_reviewed":true,"art_sha1":"464ebcda839d66bcff736d255fc446bdb4b3fb44","art_kind":"png","art_width":3658,"art_height":2459},"vol1:fig-coreset-selection":{"key":"vol1:fig-coreset-selection","figure_id":"fig-coreset-selection","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"Illustrative Boundary-Focused Selection","status":"ready","treatment":"annotated","question":"What changes when the selection budget stays fixed at five samples?","scope":"Illustrative boundary-focused selection; not a guarantee of representative coverage or final accuracy.","regions":{"random":{"x":0,"y":0,"w":0.44,"h":0.94,"label":"Five random selections"},"boundary":{"x":0.56,"y":0,"w":0.44,"h":0.94,"label":"Five boundary-band selections"},"band":{"x":0.58,"y":0.09,"w":0.37,"h":0.7,"label":"High-uncertainty band"}},"steps":[{"title":"Count the same sample budget","description":"The orange outlines in the left panel mark five random selections. Their distribution spreads the budget across the feature space.","focus":["random"]},{"title":"Spend the budget near the boundary","description":"The green outlines in the right panel mark five selected samples concentrated near the current boundary. The yellow band identifies the uncertain region being prioritized.","focus":["boundary","band"]},{"title":"Retain the coverage question","description":"Boundary focus can target uncertain decisions, but may neglect other regions. Its benefit must justify the scoring work and be checked on appropriate evaluation data.","focus":["random","boundary"]}],"artwork_reviewed":true,"art_sha1":"411c479be16df0e1818105579ec01dab4cecc650","art_kind":"svg","art_width":1200,"art_height":498,"art_structural_sha1":"461cf7261a128d7afe2ab63cb646134f6a047734"},"vol1:fig-correction-cascades-flowchart":{"key":"vol1:fig-correction-cascades-flowchart","figure_id":"fig-correction-cascades-flowchart","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"Correction Cascades","status":"ready","treatment":"annotated","question":"Why does changing a base model require downstream revalidation?","scope":"Dependency schematic; revalidation is required, while retraining depends on the resulting evidence.","regions":{"a":{"x":0.0,"y":0.25,"w":0.15,"h":0.42,"label":"Model A: base predictions"},"b":{"x":0.28,"y":0.25,"w":0.15,"h":0.42,"label":"Model B: corrects A"},"c":{"x":0.56,"y":0.25,"w":0.16,"h":0.42,"label":"Model C: corrects B"},"d":{"x":0.85,"y":0.25,"w":0.15,"h":0.42,"label":"Model D: corrects C"},"change":{"x":0.02,"y":0.0,"w":0.91,"h":0.25,"label":"Change and downstream propagation arcs"}},"steps":[{"title":"Build corrections against a particular predecessor","description":"Model B corrects A, C corrects B, and D corrects C. Each correction depends on the error behavior of the model before it.","focus":["a","b","c","d"]},{"title":"Change the upstream distribution of errors","description":"The change marker on A sends dashed arcs toward all later models. Altering A can invalidate the assumptions on which each correction was trained.","focus":["a","change"]},{"title":"Revalidate the full dependent chain","description":"B, C, and D are all marked must revalidate. Some may require revision or retraining, but the diagram does not imply that every upstream change necessarily harms them.","focus":["b","c","d"]}],"artwork_reviewed":true,"art_sha1":"7d9cb1d983233f18b3e4d4a22481a334a4d3439b","art_kind":"svg","art_width":1200,"art_height":375,"art_structural_sha1":"64d286ff6b0304ee67537ab152846764699e19af"},"vol1:fig-cross-entropy-loss":{"key":"vol1:fig-cross-entropy-loss","figure_id":"fig-cross-entropy-loss","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Cross-Entropy Compares a Distribution with a One-Hot Label","status":"ready","treatment":"annotated","question":"Why does the correct-class probability determine one-hot cross-entropy?","scope":"Ten-class one-hot example with the correct digit seven; the right-hand curve is a mathematical loss, not measured model calibration.","regions":{"distribution":{"x":0.0,"y":0.0,"w":0.49,"h":0.99,"label":"Prediction and one-hot target"},"truth":{"x":0.35,"y":0.27,"w":0.07,"h":0.61,"label":"Correct-class probability and target"},"low":{"x":0.55,"y":0.19,"w":0.16,"h":0.5,"label":"Small correct-class probabilities"},"confident":{"x":0.78,"y":0.75,"w":0.19,"h":0.15,"label":"Confident correct predictions"}},"steps":[{"title":"Separate the prediction from the target","description":"Blue bars distribute probability over digits, while the dashed target has its mass only at seven. The target is not the model’s output.","focus":["distribution","truth"]},{"title":"Reduce the loss to the true class","description":"Because the label is one-hot, cross-entropy becomes minus the logarithm of the probability assigned to seven. Probability on the other classes affects the result through normalization.","focus":["truth"]},{"title":"Interpret confidence in the correct answer","description":"The right curve penalizes a uniform guess more than a confident correct answer and grows without bound as the true-class probability approaches zero. This does not reward confident wrong predictions.","focus":["low","confident"]}],"artwork_reviewed":true,"art_sha1":"36ed821eebe3d528937b557862571be59fe50d05","art_kind":"png","art_width":3762,"art_height":2218},"vol1:fig-dam-axis-triad":{"key":"vol1:fig-dam-axis-triad","figure_id":"fig-dam-axis-triad","source":"books/vol1/backmatter/appendix_dam.qmd","title":"The D·A·M Axis Triad","status":"ready","treatment":"annotated","question":"Why can a change to one D·A·M axis move a bottleneck to another?","scope":"The triad is a diagnostic dependency map, not a quantitative performance model.","regions":{"algorithm":{"x":0.39,"y":0.0,"w":0.21,"h":0.53,"label":"Algorithm vertex"},"data":{"x":0.0,"y":0.45,"w":0.2,"h":0.55,"label":"Data vertex"},"machine":{"x":0.8,"y":0.45,"w":0.2,"h":0.55,"label":"Machine vertex"},"da":{"x":0.17,"y":0.27,"w":0.24,"h":0.37,"label":"Data–Algorithm coupling"},"am":{"x":0.59,"y":0.27,"w":0.24,"h":0.37,"label":"Algorithm–Machine coupling"},"dm":{"x":0.2,"y":0.69,"w":0.6,"h":0.07,"label":"Data–Machine coupling"}},"steps":[{"title":"Locate the binding axis","description":"Data describes inputs, Algorithm describes operations and dependencies, and Machine describes the resources that execute them. Begin with evidence for the constraint currently binding the workload.","focus":["data","algorithm","machine"]},{"title":"Trace algorithm coupling","description":"Changing data affects the computation that can be learned and performed; changing model structure changes the demands placed on hardware. Bidirectional edges warn that interventions have consequences in both directions.","focus":["da","am"]},{"title":"Recheck the supply path","description":"The Data–Machine edge connects storage and input supply to execution capacity. More compute cannot help if the data path remains the limiting resource.","focus":["dm"]}],"artwork_reviewed":true,"art_sha1":"094f3ac469baab0690e6a0e25b6c697bc7df592b","art_kind":"svg","art_width":1200,"art_height":551,"art_structural_sha1":"c7577549a96d611582154f0db9f26edd14960e17"},"vol1:fig-dam-axis-triad-intro":{"key":"vol1:fig-dam-axis-triad-intro","figure_id":"fig-dam-axis-triad-intro","source":"books/vol1/01_introduction/01_introduction.qmd","title":"The D·A·M Axis Triad","status":"ready","treatment":"annotated","question":"Where can a relaxed bottleneck reappear in an ML system?","scope":"A diagnostic taxonomy, not three independent optimization scores.","regions":{"data":{"x":0,"y":0.47,"w":0.22,"h":0.53,"label":"Data axis"},"algorithm":{"x":0.37,"y":0,"w":0.24,"h":0.5,"label":"Algorithm axis"},"machine":{"x":0.8,"y":0.47,"w":0.2,"h":0.53,"label":"Machine axis"},"edges":{"x":0.19,"y":0.28,"w":0.63,"h":0.53,"label":"Bidirectional dependencies"}},"steps":[{"title":"Diagnose missing information","description":"The Data vertex directs attention to coverage, labels, and distributions. Faster machines cannot supply examples that were never collected.","focus":["data"]},{"title":"Diagnose representation and execution","description":"Algorithm asks whether the model can represent the pattern; Machine asks whether execution fits latency, memory, and throughput requirements.","focus":["algorithm","machine"]},{"title":"Remeasure after an intervention","description":"Double-headed edges show coupled requirements. More model capacity can expose memory limits, and faster compute can expose an input bottleneck.","focus":["edges"]}],"artwork_reviewed":true,"art_sha1":"094f3ac469baab0690e6a0e25b6c697bc7df592b","art_kind":"svg","art_width":1200,"art_height":551,"art_structural_sha1":"c7577549a96d611582154f0db9f26edd14960e17"},"vol1:fig-data-drift":{"key":"vol1:fig-data-drift","figure_id":"fig-data-drift","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"Data Drift Impact","status":"ready","treatment":"annotated","question":"Why monitor input distributions and quality together?","scope":"Illustrative aligned telemetry; co-movement motivates a diagnostic hypothesis and does not by itself prove causation.","regions":{"samples":{"x":0.0,"y":0.0,"w":0.99,"h":0.21,"label":"Incoming channel samples"},"distribution":{"x":0.0,"y":0.27,"w":0.99,"h":0.31,"label":"Sales-channel distribution"},"quality":{"x":0.0,"y":0.64,"w":0.99,"h":0.35,"label":"Model accuracy over the same interval"},"late":{"x":0.68,"y":0.05,"w":0.3,"h":0.93,"label":"Later-time observations"}},"steps":[{"title":"Observe individual arrivals","description":"The top strip changes from mostly green online-store samples toward more orange offline-store samples. These are sales channels, not offline and online feature-store tiers.","focus":["samples"]},{"title":"Summarize the changing input mix","description":"The middle panel aggregates that changing mix as the sales_channel feature distribution. A distribution shift is evidence about inputs rather than direct proof of model degradation.","focus":["distribution"]},{"title":"Compare against fresh outcomes","description":"The lower accuracy curve declines over the same period. Joint inspection can guide investigation, while labels and additional checks are needed to establish the cause of the decline.","focus":["quality","late"]}],"artwork_reviewed":true,"art_sha1":"7b9fff727322493f4bcaf0e2f28217fcbd79b06e","art_kind":"svg","art_width":1200,"art_height":502,"art_structural_sha1":"adbee97db53d8a7e17f74d42644810a1609fa752"},"vol1:fig-data-governance-pillars":{"key":"vol1:fig-data-governance-pillars","figure_id":"fig-data-governance-pillars","source":"books/vol1/15_responsible_engr/15_responsible_engr.qmd","title":"Data Governance Framework","status":"ready","treatment":"annotated","question":"Why does governance require both organizational and technical elements?","scope":"Eight-element operating framework; circular placement denotes coordination rather than a required execution order.","regions":{"organization":{"x":0.42,"y":0,"w":0.18,"h":0.26,"label":"Organization"},"policies":{"x":0.62,"y":0.12,"w":0.29,"h":0.26,"label":"Policies"},"security":{"x":0.06,"y":0.12,"w":0.36,"h":0.26,"label":"Data security"},"operations":{"x":0,"y":0.36,"w":0.38,"h":0.26,"label":"Data operations"},"quality":{"x":0.08,"y":0.64,"w":0.34,"h":0.2,"label":"Data quality and master data"},"sourcing":{"x":0.4,"y":0.78,"w":0.23,"h":0.22,"label":"Data sourcing"},"catalogs":{"x":0.69,"y":0.38,"w":0.31,"h":0.24,"label":"Data catalogs"},"definitions":{"x":0.62,"y":0.64,"w":0.36,"h":0.2,"label":"Shared analytic definitions"}},"steps":[{"title":"Assign authority and responsibilities","description":"Organization and policies establish ownership and rules for handling data. A technical control without a responsible operating process cannot complete this governance role.","focus":["organization","policies"]},{"title":"Make data meaning and provenance inspectable","description":"Sourcing, catalogs, shared definitions, and quality records establish what data is available, where it came from, and how teams interpret it.","focus":["sourcing","catalogs","definitions","quality"]},{"title":"Operate and secure the governed lifecycle","description":"Data operations and security enact those decisions in running systems. These elements coordinate with the others; encryption or documentation alone does not establish compliance.","focus":["operations","security"]}],"artwork_reviewed":true,"art_sha1":"f4ae438cfa05ef95208433f83d6d62f5fa6466d2","art_kind":"svg","art_width":1200,"art_height":881,"art_structural_sha1":"b3e896f133213d9aec71274f393866ffeb8aa3c4"},"vol1:fig-data-pipeline":{"key":"vol1:fig-data-pipeline","figure_id":"fig-data-pipeline","source":"books/vol1/08_training/08_training.qmd","title":"CPU-to-GPU Data Flow","status":"ready","treatment":"annotated","question":"Where do training bytes cross physical machine boundaries?","scope":"Zones identify possible throughput gates; link peak bandwidth alone does not establish sustained supply.","regions":{"storage":{"x":0.0,"y":0.0,"w":0.17,"h":0.75,"label":"Storage zone"},"format":{"x":0.2,"y":0.03,"w":0.15,"h":0.53,"label":"Format conversion"},"preprocess":{"x":0.4,"y":0.03,"w":0.15,"h":0.53,"label":"CPU preprocessing"},"batch":{"x":0.59,"y":0.03,"w":0.15,"h":0.53,"label":"Batching"},"transfer":{"x":0.74,"y":0.22,"w":0.07,"h":0.18,"label":"Host-to-device transfer"},"gpu":{"x":0.81,"y":0.0,"w":0.19,"h":1,"label":"GPU training zone"}},"steps":[{"title":"Read raw records","description":"The Storage Zone supplies raw data from Disk/S3. Its read bandwidth limits supply before accelerator computation begins.","focus":["storage"]},{"title":"Prepare tensors on the host","description":"Format Conversion, Preprocessing, and Batching execute in the CPU Processing Zone. Decode and augmentation work must sustain the model’s consumption rate.","focus":["format","preprocess","batch"]},{"title":"Cross into device execution","description":"Batches traverse the Data arrow into the GPU Training Zone. Storage, host preparation, and transfer can each bind the pipeline even when GPU arithmetic is fast.","focus":["transfer","gpu"]}],"artwork_reviewed":true,"art_sha1":"8d6830946166c17d268de1827718f56fdfafa1f4","art_kind":"svg","art_width":1200,"art_height":315,"art_structural_sha1":"342c78e0ef0fe9ffe337e301536425c7ef47b5f8"},"vol1:fig-data-selection-pipeline":{"key":"vol1:fig-data-selection-pipeline","figure_id":"fig-data-selection-pipeline","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"An Example Data Selection Pipeline","status":"ready","treatment":"annotated","question":"Where can a data intervention enter the training process?","scope":"One possible combination of interventions; the arrows do not require synthetic generation to occur only after dynamic selection.","regions":{"raw":{"x":0,"y":0,"w":0.14,"h":0.94,"label":"Raw data"},"static":{"x":0.2,"y":0,"w":0.15,"h":0.97,"label":"Static pruning"},"dynamic":{"x":0.42,"y":0,"w":0.15,"h":0.97,"label":"Dynamic selection"},"synthetic":{"x":0.64,"y":0,"w":0.15,"h":0.97,"label":"Synthetic generation"},"evaluation":{"x":0.81,"y":0,"w":0.19,"h":0.97,"label":"ICR evaluation and model"}},"steps":[{"title":"Pay for static selection before training","description":"Static pruning removes or retains samples before the target training run. Its scoring work belongs in the intervention cost.","focus":["raw","static"]},{"title":"Separate selection timing from generation","description":"Dynamic selection changes which samples training consumes. Synthetic generation creates candidate data on demand and can also enter independently or feed later selection.","focus":["dynamic","synthetic"]},{"title":"Evaluate net data value","description":"The ICR evaluation asks whether quality gains justify compute costs. A visually smaller dataset does not by itself establish a cheaper or better training result.","focus":["evaluation"]}],"artwork_reviewed":true,"art_sha1":"2499ccbb9d6b143654fb0660ce725464ba41d327","art_kind":"svg","art_width":1200,"art_height":200,"art_structural_sha1":"835e048c677548bb8a888313b4f3184e264186d8"},"vol1:fig-data-selection-resnet-data-path":{"key":"vol1:fig-data-selection-resnet-data-path","figure_id":"fig-data-selection-resnet-data-path","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"ResNet-50 Data Path on One H100","status":"ready","treatment":"annotated","question":"Which stage does a data-selection technique actually relieve?","scope":"One ImageNet epoch on the chapter’s modeled ResNet-50/H100 path; loads are per full epoch at the compute-bound rate.","regions":{"storage":{"x":0,"y":0.15,"w":0.24,"h":0.66,"label":"Local NVMe"},"host":{"x":0.26,"y":0.15,"w":0.24,"h":0.66,"label":"Host decode and augmentation"},"pcie":{"x":0.51,"y":0.15,"w":0.24,"h":0.66,"label":"PCIe transfer"},"gpu":{"x":0.76,"y":0.15,"w":0.24,"h":0.66,"label":"H100 arithmetic"},"rate":{"x":0.2,"y":0.84,"w":0.47,"h":0.1,"label":"Host rate requirement"}},"steps":[{"title":"Trace all four stages","description":"Images are read from storage, decoded and augmented on the host, transferred over PCIe, then processed on the accelerator. Cutting arithmetic does not automatically cut every preceding stage.","focus":["storage","host","pcie","gpu"]},{"title":"Distinguish materialization from discard","description":"A materialized coreset avoids reading excluded images; stream-and-discard filtering still reads them. Both may reduce training arithmetic while leaving different storage and host loads.","focus":["storage","host","gpu"]},{"title":"Account for added artifacts and scoring","description":"Offline distillation logits add data to the path, and a scoring pass adds forward arithmetic. The red host outline emphasizes that decoding and augmentation must keep pace with the accelerator.","focus":["pcie","gpu","rate"]}],"artwork_reviewed":true,"art_sha1":"bb81309fa73c76aa24014f8b167e42e4a41e276d","art_kind":"png","art_width":3840,"art_height":2280},"vol1:fig-dataset-saturation":{"key":"vol1:fig-dataset-saturation","figure_id":"fig-dataset-saturation","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Dataset Saturation","status":"ready","treatment":"annotated","question":"What does crossing the human-performance baseline say about a benchmark?","scope":"Task-normalized scores are benchmark-specific; crossings do not establish general human capability or reveal over-optimization by themselves.","regions":{"baseline":{"x":0.07,"y":0.06,"w":0.77,"h":0.13,"label":"Human-performance reference"},"hand":{"x":0.11,"y":0.29,"w":0.47,"h":0.39,"label":"Handwriting trajectory"},"vision":{"x":0.43,"y":0.07,"w":0.34,"h":0.73,"label":"Image-recognition trajectory"},"language":{"x":0.66,"y":0.07,"w":0.13,"h":0.73,"label":"Reading and language trajectories"},"note":{"x":0.01,"y":0.82,"w":0.46,"h":0.18,"label":"Initial-performance normalization"}},"steps":[{"title":"Establish the reference","description":"The zero line sets reported human performance for each task. The lower annotation also normalizes each system’s initial performance to −100, so these are not shared raw accuracy units.","focus":["baseline","note"]},{"title":"Compare task histories","description":"Handwriting and image recognition approach and cross the baseline over different intervals. Their histories describe particular evaluation suites rather than universal capability scales.","focus":["hand","vision"]},{"title":"Recognize shrinking headroom","description":"Reading comprehension and language understanding cross the reference quickly in the later interval. Static suites then offer less discriminating headroom, but these crossings alone cannot separate real capability gains from optimization to the test.","focus":["language","baseline"]}],"artwork_reviewed":true,"art_sha1":"712ab476207ab86030a83dbf85dcdbf0df7e8361","art_kind":"svg","art_width":1200,"art_height":542,"art_structural_sha1":"bec4c4de4710010a23d494d750add6bb99cecbe7"},"vol1:fig-debug-flowchart":{"key":"vol1:fig-debug-flowchart","figure_id":"fig-debug-flowchart","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Data Pipeline Debugging Flowchart","status":"ready","treatment":"annotated","question":"How should a symptom become a confirmed data-pipeline diagnosis?","scope":"Every side branch is a candidate hypothesis. Several faults may coexist, and model, code, or hardware can also be responsible.","regions":{"drift":{"x":0.02,"y":0.0,"w":0.97,"h":0.19,"label":"Temporal degradation check"},"artifact":{"x":0.02,"y":0.23,"w":0.97,"h":0.18,"label":"Training-validation gap check"},"skew":{"x":0.02,"y":0.46,"w":0.97,"h":0.18,"label":"Validation-production gap check"},"coverage":{"x":0.02,"y":0.69,"w":0.97,"h":0.18,"label":"Subgroup consistency check"},"other":{"x":0.02,"y":0.9,"w":0.38,"h":0.1,"label":"Other hypotheses"}},"steps":[{"title":"Check time and validation","description":"Accuracy degrading over time suggests investigating drift; a training-validation gap suggests checking artifacts and overfitting. Neither symptom proves its candidate cause.","focus":["drift","artifact"]},{"title":"Compare serving and subgroups","description":"A validation-production gap motivates checking feature transformations and schemas. Inconsistent subgroup performance motivates slice coverage analysis.","focus":["skew","coverage"]},{"title":"Continue and confirm","description":"The downward Continue arrows keep the investigation open after a positive answer. Compare controlled artifacts before repairs, and retain model, code, and hardware faults as alternatives.","focus":["other"]}],"artwork_reviewed":true,"art_sha1":"d343ebc3c55beac08bc626207c89d598aa0750d9","art_kind":"svg","art_width":1200,"art_height":1134,"art_structural_sha1":"a4322c3f78203b1c14ffd7f1caaa258540414cb8"},"vol1:fig-deeplearning":{"key":"vol1:fig-deeplearning","figure_id":"fig-deeplearning","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Data-Driven Rule Discovery","status":"ready","treatment":"annotated","question":"What does supervised learning produce from examples?","scope":"The diagram depicts supervised training, not inference; humans still choose data, objectives, architecture, and evaluation.","regions":{"upper":{"x":0.0,"y":0.0,"w":0.24,"h":0.29,"label":"Answers input"},"lower":{"x":0.0,"y":0.69,"w":0.24,"h":0.3,"label":"Data input"},"process":{"x":0.31,"y":0.34,"w":0.38,"h":0.31,"label":"Processing stage"},"output":{"x":0.77,"y":0.34,"w":0.23,"h":0.31,"label":"Rules output"}},"steps":[{"title":"Identify the supplied information","description":"Data and target answers are both inputs. Target answers supervise learning; they are not available as answers to a new inference request.","focus":["upper","lower"]},{"title":"Follow the processing boundary","description":"Machine learning fits a decision function from examples under an engineered objective.","focus":["process"]},{"title":"Read what the system produces","description":"The output called Rules is the learned decision function. A later inference execution applies that function to new data.","focus":["output"]}],"artwork_reviewed":true,"art_sha1":"7088e15f637d518fefa62c27529cb2507b4bc71c","art_kind":"svg","art_width":1200,"art_height":319,"art_structural_sha1":"7d57dda2d684fe8c0d8848ecc558e6212f8be3cb"},"vol1:fig-depth-width-scaling":{"key":"vol1:fig-depth-width-scaling","figure_id":"fig-depth-width-scaling","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Width Costs Quadratically, Depth Costs Linearly","status":"ready","treatment":"annotated","question":"Why do width and depth impose different costs?","scope":"Fully connected networks with fixed MNIST input/output widths; curves count MACs per example, not measured latency.","regions":{"width":{"x":0.0,"y":0.0,"w":0.49,"h":0.99,"label":"Equal hidden-width sweep"},"depth":{"x":0.51,"y":0.0,"w":0.49,"h":0.99,"label":"Fixed-width depth sweep"},"wide":{"x":0.24,"y":0.06,"w":0.23,"h":0.44,"label":"Hidden-to-hidden dominated width regime"},"activation":{"x":0.89,"y":0.06,"w":0.1,"h":0.85,"label":"Retained-activation axis"}},"steps":[{"title":"Separate the experiments","description":"The left plot varies the shared width of two hidden layers. The right varies hidden-layer count while holding width at 512, so the two horizontal axes describe different interventions.","focus":["width","depth"]},{"title":"Explain the quadratic width term","description":"Once the hidden-to-hidden matrix dominates, increasing both its dimensions makes its MAC count grow quadratically with width. The dashed slope-two guide marks that regime.","focus":["wide"]},{"title":"Count sequential depth and retained outputs","description":"At fixed width, added layers increase both MACs and retained activations linearly. The activation curve uses the right-hand axis; it is not another MAC measurement.","focus":["depth","activation"]}],"artwork_reviewed":true,"art_sha1":"543c2bcaaac688b558b86d9d038b9949bbfd0c9d","art_kind":"png","art_width":3727,"art_height":2602},"vol1:fig-distributed-coreset-architecture":{"key":"vol1:fig-distributed-coreset-architecture","figure_id":"fig-distributed-coreset-architecture","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"Distributed Coreset Selection Architecture","status":"ready","treatment":"annotated","question":"What must a coordinator do after workers score separate data shards?","scope":"Processes are on one host and workers drive accelerators; coordination must cost less than the training it saves.","regions":{"coordinator":{"x":0,"y":0,"w":1,"h":0.41,"label":"Coordinator merge"},"up":{"x":0.13,"y":0.4,"w":0.72,"h":0.22,"label":"Worker scores sent upward"},"workers":{"x":0.05,"y":0.61,"w":0.9,"h":0.39,"label":"Shard-local workers"},"down":{"x":0.16,"y":0.4,"w":0.74,"h":0.22,"label":"Final indices broadcast downward"}},"steps":[{"title":"Score independent shards","description":"Worker 0, Worker 1, and Worker N perform local EL2N scoring over their assigned images. Parallel local work reduces what any one worker must score.","focus":["workers"]},{"title":"Merge a global selection","description":"Upward arrows deliver local scoring results to the coordinator. A global merge still requires work and host-memory capacity; local scores alone do not define a consistent final subset.","focus":["up","coordinator"]},{"title":"Return the selected indices","description":"Downward arrows distribute the final coreset indices to workers. The architecture is useful only if scoring and coordination overhead remain below the training time saved.","focus":["down","workers"]}],"artwork_reviewed":true,"art_sha1":"8372ba3b5773d2e8889351797f36dc917fbc698c","art_kind":"svg","art_width":1200,"art_height":485,"art_structural_sha1":"0de406bce12416c6e14e81ecc8d18bc99a292ee9"},"vol1:fig-dlrm-pipeline":{"key":"vol1:fig-dlrm-pipeline","figure_id":"fig-dlrm-pipeline","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"DLRM Pipeline","status":"ready","treatment":"annotated","question":"Why can recommendation combine compute-heavy and memory-heavy stages?","scope":"Schematic DLRM pipeline; embedding-table capacity and placement depend on workload.","regions":{"dense":{"x":0.01,"y":0.5,"w":0.23,"h":0.49,"label":"Dense-feature bottom MLP"},"ids":{"x":0.3,"y":0.86,"w":0.46,"h":0.14,"label":"Categorical IDs"},"tables":{"x":0.32,"y":0.37,"w":0.4,"h":0.44,"label":"Embedding-table gathers"},"interaction":{"x":0.06,"y":0.24,"w":0.66,"h":0.11,"label":"Pairwise interaction"},"top":{"x":0.28,"y":0.01,"w":0.24,"h":0.18,"label":"Top MLP and probability"}},"steps":[{"title":"Transform dense features","description":"Age and time-of-day features pass through the bottom MLP. Its small weight matrices support dense arithmetic.","focus":["dense"]},{"title":"Gather rather than multiply a table","description":"Each categorical ID selects one embedding row. These random reads perform little arithmetic and may require tables larger than one device’s memory.","focus":["ids","tables"]},{"title":"Combine feature representations","description":"Pairwise dot products combine the dense representation with gathered embedding vectors. The top MLP maps the interaction result to click probability.","focus":["interaction","top"]}],"artwork_reviewed":true,"art_sha1":"156078e1823374d8a5f4d9077b0ff62b65def3fb","art_kind":"svg","art_width":1200,"art_height":917,"art_structural_sha1":"b1a1495781a1c0d3b927305fbad8821e0cce204f"},"vol1:fig-dnn-fm-framework":{"key":"vol1:fig-dnn-fm-framework","figure_id":"fig-dnn-fm-framework","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Architecture Selection Decision Framework","status":"ready","treatment":"annotated","question":"Why is a plausible architecture only the start of system design?","scope":"Decision framework for dense architecture candidates; sparse high-cardinality recommendation is handled separately in the text.","regions":{"types":{"x":0,"y":0.08,"w":1,"h":0.22,"label":"Data-type candidates"},"constraints":{"x":0.34,"y":0.38,"w":0.29,"h":0.32,"label":"Memory compute and speed checks"},"accuracy":{"x":0.34,"y":0.7,"w":0.29,"h":0.1,"label":"Accuracy target"},"deployment":{"x":0.34,"y":0.81,"w":0.29,"h":0.11,"label":"Deployment compatibility"},"revision":{"x":0,"y":0.67,"w":1,"h":0.25,"label":"Revision paths"}},"steps":[{"title":"Choose an initial structural match","description":"Text, temporal sequences, images, and tabular data suggest different candidate families. These branches propose starting points rather than proving a best model.","focus":["types"]},{"title":"Check resource feasibility","description":"A candidate must fit memory and computation budgets and meet inference speed requirements. Failure sends the design toward scaling down or changing architecture.","focus":["constraints"]},{"title":"Check quality and deployment together","description":"An accuracy miss can require more capacity, while hardware incompatibility can require another design. Follow the return paths to reconsider the candidate after each change.","focus":["accuracy","deployment","revision"]}],"artwork_reviewed":true,"art_sha1":"db05c02a15f50122629e60d1aa618ef6e5736a7c","art_kind":"svg","art_width":1200,"art_height":1238,"art_structural_sha1":"c4f9c567238bc772acf5edece5423b914cb64b59"},"vol1:fig-domain-gap":{"key":"vol1:fig-domain-gap","figure_id":"fig-domain-gap","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"The Domain Gap Problem","status":"ready","treatment":"annotated","question":"Why does matching synthetic and real feature coverage require validation?","scope":"Schematic marginal densities; they do not determine class-conditional boundaries or establish a causal quality effect.","regions":{"synthetic":{"x":0.07,"y":0.27,"w":0.42,"h":0.63,"label":"Synthetic density"},"real":{"x":0.34,"y":0.33,"w":0.58,"h":0.57,"label":"Real density"},"boundary":{"x":0.43,"y":0.1,"w":0.07,"h":0.8,"label":"Synthetic boundary"},"realboundary":{"x":0.59,"y":0.25,"w":0.04,"h":0.65,"label":"Real-data boundary"}},"steps":[{"title":"Locate the feature shift","description":"The blue synthetic density is shifted left of the orange real density. Their overlap and mismatch describe feature coverage, not classifier accuracy directly.","focus":["synthetic","real"]},{"title":"Separate densities from boundaries","description":"The dashed red and dotted green lines are schematic decision boundaries drawn with the distributions. Marginal densities alone cannot establish where class boundaries belong.","focus":["boundary","realboundary"]},{"title":"Evaluate on the deployment domain","description":"Synthetic data can expand supply while preserving a domain gap. Real-domain validation and class-conditional evidence are needed before treating more generated examples as more useful training signal.","focus":["synthetic","real"]}],"artwork_reviewed":true,"art_sha1":"f7289e63ef92638face71872ab27e403ffe1cccc","art_kind":"svg","art_width":1200,"art_height":479,"art_structural_sha1":"0c21f6e8aa791f581f6d034b8f669b0754617e60"},"vol1:fig-doorbell-scorecard":{"key":"vol1:fig-doorbell-scorecard","figure_id":"fig-doorbell-scorecard","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Smart Doorbell Constraint Scorecard","status":"ready","treatment":"annotated","question":"Can a model pass the flash check and still miss its response deadline?","scope":"This is the tightened 50 ms scorecard, not the canonical 200 ms scenario. Flash fit does not establish SRAM fit or complete-path latency.","regions":{"memory":{"x":0.02,"y":0.58,"w":0.32,"h":0.22,"label":"Flash demand bar"},"latency":{"x":0.01,"y":0.18,"w":0.91,"h":0.2,"label":"Latency demand bar"},"threshold":{"x":0.48,"y":0.08,"w":0.04,"h":0.79,"label":"Saturation threshold"},"axis":{"x":0.16,"y":0.85,"w":0.83,"h":0.14,"label":"Demand over supply axis"}},"steps":[{"title":"Read demand over supply","description":"The horizontal scale normalizes each demand by its own budget. The dashed line at 1 marks exact saturation, so bars beyond it fail that check.","focus":["axis","threshold"]},{"title":"Pass the flash screen","description":"The short green Memory (flash) bar occupies only a small part of flash capacity. Runtime state and activations in SRAM remain separate checks.","focus":["memory"]},{"title":"Miss the tightened deadline","description":"The red Latency (SLA) bar reaches 202 percent of the 50 ms budget. A model can fit its stored weights yet still respond too slowly.","focus":["latency","threshold"]},{"title":"Identify the actual binding check","description":"In this tightened case latency fails while flash passes. Changing the deadline changes that verdict without shrinking the model or accelerating execution.","focus":["memory","latency"]}],"artwork_reviewed":true,"art_sha1":"6be9ec92a02e0ac50fcf5ad68c2b5beccc5b0d77","art_kind":"png","art_width":1464,"art_height":871},"vol1:fig-early-exit-transformers":{"key":"vol1:fig-early-exit-transformers","figure_id":"fig-early-exit-transformers","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Early Exit Architecture","status":"ready","treatment":"annotated","question":"When can an input stop before the final transformer layer?","scope":"This is an architecture walkthrough, not a calibrated confidence simulator. Batched execution may require compaction or otherwise fail to realize proportional savings.","regions":{"first":{"x":0.24,"y":0,"w":0.17,"h":0.18,"label":"Transformer 1"},"decision":{"x":0.24,"y":0.52,"w":0.17,"h":0.22,"label":"First confidence estimator"},"exit":{"x":0.24,"y":0.82,"w":0.17,"h":0.18,"label":"First exit"},"continue":{"x":0.43,"y":0.1,"w":0.09,"h":0.63,"label":"Continue path"},"later":{"x":0.51,"y":0,"w":0.49,"h":0.99,"label":"Later transformer stages"}},"steps":[{"title":"Compute an intermediate representation","description":"Transformer 1 processes the input before Classifier 1 forms an early prediction. The extra classifier and estimator themselves incur work.","focus":["first"]},{"title":"Test the exit policy","description":"Confidence/LTE determines whether the intermediate prediction meets the exit criterion. Confidence must be calibrated and validated for the task.","focus":["decision"]},{"title":"Stop or continue","description":"A permitted Exit skips remaining transformer stages for that input. Otherwise the Continue path sends its representation onward.","focus":["exit","continue"]},{"title":"Separate skipped work from speedup","description":"Later stages remain available for harder inputs. Savings in a batch depend on how the runtime handles examples that exit at different depths.","focus":["later"]}],"artwork_reviewed":true,"art_sha1":"b6c97b35daa19fe0461813396b16e309d6bfc25c","art_kind":"svg","art_width":1200,"art_height":370,"art_structural_sha1":"104c499320544d15ca576ce8f6bac9cc8955e120"},"vol1:fig-edge-ml":{"key":"vol1:fig-edge-ml","figure_id":"fig-edge-ml","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Edge ML Constraint Map","status":"ready","treatment":"annotated","question":"What changes when inference moves near the sensor?","scope":"Local placement removes a remote round trip from the chosen path; it does not remove every network, processing, or sensor delay.","regions":{"binding":{"x":0.02,"y":0.18,"w":0.19,"h":0.81,"label":"Edge constraints"},"response":{"x":0.29,"y":0.18,"w":0.18,"h":0.81,"label":"Local processing responses"},"boundary":{"x":0.54,"y":0.18,"w":0.2,"h":0.81,"label":"Distributed failure boundaries"},"workloads":{"x":0.83,"y":0.18,"w":0.17,"h":0.81,"label":"Edge workloads"}},"steps":[{"title":"Identify a locality requirement","description":"Sub-100 ms response, wide raw data, on-premises restrictions, and offline operation favor computation near the data source.","focus":["binding"]},{"title":"Process before upload","description":"Place Compute Near Sensors and Filter Data Before Upload reduce dependence on a remote inference path. Local accelerators still have finite capacity.","focus":["response"]},{"title":"Account for a fleet","description":"Fixed Local Capacity limits each site. Distributed Device Security, Fleet Management, and Model Update Coordination add operational work across sites.","focus":["boundary"]},{"title":"Check the deployment fit","description":"Industrial IoT, retail analytics, autonomous vehicles, and hospital imaging illustrate possible fits. Each must still satisfy its own end-to-end budget and governance rules.","focus":["workloads","boundary"]}],"artwork_reviewed":true,"art_sha1":"37ac4e554fea7e5551adc8fee449778f74f40270","art_kind":"svg","art_width":1200,"art_height":525,"art_structural_sha1":"0d87c39cc9a2144a2c44ed6e4fec2866978fe9a9"},"vol1:fig-efficiency-frontier":{"key":"vol1:fig-efficiency-frontier","figure_id":"fig-efficiency-frontier","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"The Efficiency Frontier","status":"ready","treatment":"annotated","question":"Which models offer more accuracy for a given arithmetic budget?","scope":"Published representative model reports; the dashed frontier is illustrative, not a controlled benchmark.","regions":{"mobile":{"x":0.09,"y":0.23,"w":0.26,"h":0.22,"label":"Mobile and efficient choices"},"dense":{"x":0.45,"y":0.15,"w":0.22,"h":0.28,"label":"Dense and modern CNNs"},"transformer":{"x":0.78,"y":0.22,"w":0.2,"h":0.13,"label":"ViT-B/16"}},"steps":[{"title":"Low arithmetic cost","description":"MobileNetV2 and EfficientNet-B0 occupy the low-compute side. Their different accuracies show why arithmetic cost alone does not identify a model.","focus":["mobile"]},{"title":"Accuracy at moderate cost","description":"Compare ResNet-50, Inception-v3, Swin-T, and ConvNeXt-T. A model above and left of another offers a more favorable plotted accuracy–compute pair.","focus":["dense"]},{"title":"An expensive point need not dominate","description":"ViT-B/16 lies below the illustrative frontier despite its greater reported arithmetic cost. Model variant, image resolution, and training recipe remain part of this comparison.","focus":["transformer"]}],"artwork_reviewed":true,"art_sha1":"2098f9c9508888b1538e3e376ad6780b1edebbed","art_kind":"png","art_width":3278,"art_height":2476},"vol1:fig-energy-hierarchy":{"key":"vol1:fig-energy-hierarchy","figure_id":"fig-energy-hierarchy","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"The Energy Hierarchy","status":"ready","treatment":"annotated","question":"Why can avoiding a memory access matter more than removing an arithmetic operation?","scope":"Representative 45 nm energy model from the cited source, not current universal device specifications.","regions":{"dram":{"x":0.15,"y":0.06,"w":0.79,"h":0.19,"label":"DRAM read"},"sram":{"x":0.15,"y":0.25,"w":0.47,"h":0.18,"label":"8 KB SRAM read"},"arithmetic":{"x":0.15,"y":0.44,"w":0.5,"h":0.51,"label":"FP32 and INT8 arithmetic"},"axis":{"x":0.13,"y":0.94,"w":0.81,"h":0.06,"label":"Logarithmic energy axis"}},"steps":[{"title":"Read the logarithmic axis","description":"Equal horizontal distances represent multiplicative energy ratios. The bars compare representative operations, not total application energy.","focus":["axis"]},{"title":"Distinguish arithmetic from storage","description":"FP32 multiplication costs more than FP32 addition in this model, yet both are far below the off-chip DRAM read. Operation counts alone omit this difference.","focus":["arithmetic","dram"]},{"title":"Use local storage to reuse operands","description":"The SRAM read is much cheaper than a DRAM read, though it still has a cost. Reusing a fetched value in local storage can avoid repeating the expensive off-chip access.","focus":["sram","dram"]}],"artwork_reviewed":true,"art_sha1":"e48a192eb2565918f8469bcde1872c1db4431a08","art_kind":"png","art_width":3782,"art_height":2476},"vol1:fig-energy-per-inference":{"key":"vol1:fig-energy-per-inference","figure_id":"fig-energy-per-inference","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Energy per Inference Across Deployment Tiers","status":"ready","treatment":"annotated","question":"Why are these energy bars scale anchors rather than an offload experiment?","scope":"Tasks and accounting boundaries differ. The three vision estimates share an analytical model, while the endpoints are scenario anchors; bar ratios do not identify hardware efficiency.","regions":{"tiny":{"x":0.01,"y":0.06,"w":0.4,"h":0.13,"label":"Keyword spotting anchor"},"vision":{"x":0,"y":0.21,"w":0.72,"h":0.48,"label":"Three vision estimates"},"llm":{"x":0.01,"y":0.68,"w":0.93,"h":0.15,"label":"Cloud LLM anchor"},"axis":{"x":0.21,"y":0.83,"w":0.77,"h":0.17,"label":"Logarithmic energy axis"}},"steps":[{"title":"Read the energy scale","description":"The horizontal axis is logarithmic in joules. Equal distances represent multiplicative changes, so the endpoints span many orders of magnitude.","focus":["axis"]},{"title":"Locate the always-on anchor","description":"TinyML Keyword Spotting marks a small inference energy scale. This is a different task from the vision and language examples.","focus":["tiny"]},{"title":"Check what the vision bars count","description":"The phone, Jetson module, and A100 card bars estimate device energy over a batch-1 inference window. Their accounting includes the stated device boundary.","focus":["vision"]},{"title":"Keep the endpoint caveat","description":"The Cloud LLM query is an order-of-magnitude anchor including data-center overhead. Comparing it directly with keyword spotting does not establish the savings from moving one matched workload.","focus":["llm","tiny"]}],"artwork_reviewed":true,"art_sha1":"d459f9e553d12012f475e65000aa8cee0aa6f52b","art_kind":"png","art_width":3772,"art_height":2060},"vol1:fig-etl-vs-elt":{"key":"vol1:fig-etl-vs-elt","figure_id":"fig-etl-vs-elt","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"ETL vs. ELT Architectural Paradigms","status":"ready","treatment":"annotated","question":"Where does transformation occur relative to persistent storage?","scope":"ETL and ELT shift a processing boundary; neither universally minimizes cost or guarantees quality.","regions":{"etl_sources":{"x":0.0,"y":0.0,"w":0.15,"h":0.8,"label":"ETL sources"},"etl_transform":{"x":0.18,"y":0.27,"w":0.15,"h":0.26,"label":"External transformation"},"etl_target":{"x":0.36,"y":0.15,"w":0.17,"h":0.44,"label":"ETL target"},"elt_sources":{"x":0.58,"y":0.0,"w":0.17,"h":0.8,"label":"ELT sources"},"elt_stage":{"x":0.78,"y":0.25,"w":0.09,"h":0.31,"label":"Warehouse staging tables"},"elt_final":{"x":0.88,"y":0.25,"w":0.1,"h":0.31,"label":"Warehouse final tables"}},"steps":[{"title":"Transform before loading","description":"In the left panel, three sources feed external transformation before Target storage. Cleaning and schema enforcement can protect what lands in the warehouse.","focus":["etl_sources","etl_transform","etl_target"]},{"title":"Load before transforming","description":"The right panel lands extracted data inside the Target first. Staging tables and final tables occupy the warehouse, where transformation executes.","focus":["elt_sources","elt_stage","elt_final"]},{"title":"Choose the replay boundary","description":"ELT retains raw input for revised transformations; ETL may need an external replay path. Compare warehouse footprint, computation, and governance requirements before choosing.","focus":["etl_transform","elt_stage"]}],"artwork_reviewed":true,"art_sha1":"90ac93d536acdf054e1bcacd1622b7f524d80bc8","art_kind":"svg","art_width":1200,"art_height":435,"art_structural_sha1":"8bad2a8769a0bbbdedae0c460201f54e397296c7"},"vol1:fig-example-skip-connection":{"key":"vol1:fig-example-skip-connection","figure_id":"fig-example-skip-connection","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Residual Connection Block (Original Post-Activation Form)","status":"ready","treatment":"annotated","question":"What exactly bypasses the weight layers in this residual block?","scope":"Original post-activation ResNet form, not a pre-activation block.","regions":{"residual":{"x":0.1,"y":0.2,"w":0.67,"h":0.38,"label":"Weighted residual path"},"shortcut":{"x":0.065,"y":0,"w":0.85,"h":0.2,"label":"Identity shortcut"},"addition":{"x":0.86,"y":0.23,"w":0.07,"h":0.34,"label":"Residual addition"},"relu":{"x":0.85,"y":0.65,"w":0.14,"h":0.33,"label":"Final ReLU"}},"steps":[{"title":"Compute the residual branch","description":"The main branch applies a weight layer, ReLU, and a second weight layer to form F(x).","focus":["residual"]},{"title":"Retain the original input","description":"The upper path carries x around both weight layers without those transformations. The addition combines F(x) with this retained input.","focus":["shortcut","addition"]},{"title":"Apply the final activation","description":"The bottom ReLU acts after addition, so the block output is ReLU(F(x)+x). The post-addition nonlinearity matters when reasoning about gradients.","focus":["addition","relu"]}],"artwork_reviewed":true,"art_sha1":"35505070b843ae5044ebe0de7a60a2bc9222ffd9","art_kind":"svg","art_width":1200,"art_height":270,"art_structural_sha1":"91e473eb0db63d7f52588eae87bfc946968fc9be"},"vol1:fig-eye-dr":{"key":"vol1:fig-eye-dr","figure_id":"fig-eye-dr","source":"books/vol1/03_ml_lifecycle/03_ml_lifecycle.qmd","title":"Retinal Hemorrhages in DR Screening","status":"ready","treatment":"annotated","question":"Why must a screening pipeline preserve fine image detail?","scope":"These labeled example images illustrate input requirements, not a diagnostic tool or a measured classifier comparison.","regions":{"healthy":{"x":0.01,"y":0.0,"w":0.47,"h":0.99,"label":"Panel A: healthy retina"},"diseased":{"x":0.51,"y":0.0,"w":0.48,"h":0.99,"label":"Panel B: diseased retina"},"lesion":{"x":0.62,"y":0.24,"w":0.29,"h":0.19,"label":"Printed hemorrhage callout"}},"steps":[{"title":"Establish the image comparison","description":"Panel A and panel B retain retinal vessels and local texture. Their labels supply example categories; no model confidence or automated diagnosis is shown.","focus":["healthy","diseased"]},{"title":"Inspect the indicated local feature","description":"The printed arrow identifies a small hemorrhage in panel B. A coarse resize or poor acquisition can remove details much smaller than the full retinal image.","focus":["lesion"]},{"title":"Treat acquisition as part of the system","description":"Preserving resolution and validating lighting and camera quality are deployment requirements. These pictures alone do not establish clinical sensitivity or field readiness.","focus":["diseased"]}],"artwork_reviewed":true,"art_sha1":"f67f75018cb77a64a89348eb209355ffaaaf04ae","art_kind":"png","art_width":632,"art_height":255},"vol1:fig-fairness-frontier":{"key":"vol1:fig-fairness-frontier","figure_id":"fig-fairness-frontier","source":"books/vol1/15_responsible_engr/15_responsible_engr.qmd","title":"An Illustrative Fairness-Accuracy Pareto Frontier","status":"ready","treatment":"annotated","question":"How should the three operating points on this fairness frontier be compared?","scope":"Hypothetical demographic-disparity frontier with inverted horizontal axis; no universal or empirical trade-off is claimed.","regions":{"a":{"x":0.14,"y":0.03,"w":0.3,"h":0.14,"label":"Point A unconstrained accuracy"},"b":{"x":0.38,"y":0.29,"w":0.49,"h":0.18,"label":"PointB balanced compromise"},"c":{"x":0.6,"y":0.67,"w":0.38,"h":0.2,"label":"Point C strict equality"},"axis":{"x":0.12,"y":0.89,"w":0.87,"h":0.11,"label":"Inverted disparity axis"}},"steps":[{"title":"Read the axis direction","description":"Disparity decreases toward the right. Point A has the highest plotted accuracy and larger demographic disparity than B and C.","focus":["axis","a"]},{"title":"Interpret the stated ratio narrowly","description":"B’s disparity 0.05 is 3.6 times smaller than A’s 0.18. The label does not define a universal multiplier for fairness or a causal effect of one intervention.","focus":["b","a"]},{"title":"Identify the assumed cost of equality","description":"Point C has zero disparity and lower accuracy on this constructed curve. The example illustrates an operating choice rather than proving that real systems must sacrifice this much accuracy.","focus":["c"]}],"artwork_reviewed":true,"art_sha1":"a94a8b7de7c98d29a98509c94066ef3186fe9269","art_kind":"png","art_width":3347,"art_height":2234},"vol1:fig-fairness-threshold":{"key":"vol1:fig-fairness-threshold","figure_id":"fig-fairness-threshold","source":"books/vol1/15_responsible_engr/15_responsible_engr.qmd","title":"Threshold Effects on Subgroup Outcomes","status":"ready","treatment":"annotated","question":"How can aggregate accuracy improve while one subgroup receives worse outcomes?","scope":"Sixteen illustrative cases; approve markers to the left of a boundary. Boundary labels show achieved accuracy, not score cutoff.","regions":{"a":{"x":0,"y":0.12,"w":0.99,"h":0.25,"label":"Subgroup A cases"},"b":{"x":0,"y":0.39,"w":0.99,"h":0.27,"label":"Subgroup B cases"},"first":{"x":0.38,"y":0,"w":0.045,"h":0.7,"label":"75 percent boundary"},"second":{"x":0.65,"y":0,"w":0.05,"h":0.7,"label":"81.25 percent boundary"},"legend":{"x":0.24,"y":0.7,"w":0.69,"h":0.3,"label":"Outcome shapes and subgroup colors"}},"steps":[{"title":"Decode the markers before classifying","description":"Circles denote loan repayment and plus signs default; color identifies subgroup. Approval is determined by position to the left of the selected boundary.","focus":["legend","a","b"]},{"title":"Apply the75 percent boundary","description":"At the left boundary, count approved and rejected markers against their true outcomes. Overall accuracy alone hides which subgroup contributes each error.","focus":["first","a","b"]},{"title":"Inspect who receives the accuracy gain","description":"Moving to the right boundary perfectly separates Subgroup A. Subgroup B’s errors rise from one to three even as aggregate accuracy reaches 81.25 percent, so the aggregate gain does not establish subgroup improvement.","focus":["second","a","b"]}],"artwork_reviewed":true,"art_sha1":"880e1c546893e224421d9039589b6d8aae2d0bf5","art_kind":"svg","art_width":1200,"art_height":360,"art_structural_sha1":"a971dcef80d0b97703b57f3d08a9a88e71c73f62"},"vol1:fig-fetching-naive":{"key":"vol1:fig-fetching-naive","figure_id":"fig-fetching-naive","source":"books/vol1/08_training/08_training.qmd","title":"Illustrative Sequential Data Fetching","status":"ready","treatment":"annotated","question":"Where is accelerator time lost in a sequential input schedule?","scope":"Durations are illustrative assumptions; the paired overlap figure preserves the individual stage lengths.","regions":{"open1":{"x":0.09,"y":0.08,"w":0.08,"h":0.14,"label":"Open 1"},"reads":{"x":0.16,"y":0.28,"w":0.22,"h":0.15,"label":"Read 1 and Read 2"},"train12":{"x":0.37,"y":0.48,"w":0.29,"h":0.15,"label":"Train 1 and Train 2"},"second":{"x":0.66,"y":0.08,"w":0.34,"h":0.56,"label":"Second file and training stage"},"epoch":{"x":0.09,"y":0.68,"w":0.91,"h":0.16,"label":"Epoch spans"}},"steps":[{"title":"Wait for the first input","description":"Open 1 completes before the first read begins. Read 1 and Read 2 occupy time before the training row becomes active.","focus":["open1","reads"]},{"title":"Observe serialized work","description":"Train 1 and Train 2 begin only after earlier input work. The blank training intervals during file operations represent accelerator idle opportunities.","focus":["train12","second"]},{"title":"Measure the whole schedule","description":"The Epoch row spans all serial operations through the second file. Its total includes input work as well as training, which is why a kernel-only timing misses this loss.","focus":["epoch"]}],"artwork_reviewed":true,"art_sha1":"1381f1517c9f7e3c83dc0c3ba2a74daf6234a417","art_kind":"svg","art_width":1200,"art_height":377,"art_structural_sha1":"578d160bf3fdc71dbbbb673767b139baf44753b2"},"vol1:fig-fetching-optimized":{"key":"vol1:fig-fetching-optimized","figure_id":"fig-fetching-optimized","source":"books/vol1/08_training/08_training.qmd","title":"Illustrative Overlapped Data Prefetching","status":"ready","treatment":"annotated","question":"How does prefetching shorten elapsed time without shortening each stage?","scope":"Overlap assumes buffering and independent resources. It is not a guarantee that all I/O can be hidden.","regions":{"first":{"x":0.07,"y":0.08,"w":0.31,"h":0.35,"label":"Initial open and read"},"overlap":{"x":0.34,"y":0.27,"w":0.46,"h":0.33,"label":"Reads overlapping training"},"open2":{"x":0.49,"y":0.08,"w":0.13,"h":0.15,"label":"Open 2"},"train":{"x":0.34,"y":0.48,"w":0.66,"h":0.14,"label":"Continuous training blocks"},"epoch":{"x":0.06,"y":0.68,"w":0.94,"h":0.15,"label":"Overlapped epoch span"}},"steps":[{"title":"Pay the startup dependency","description":"The schedule still opens a file and reads its first input before training starts. Prefetching does not remove the first producer-consumer dependency.","focus":["first"]},{"title":"Prepare future work during compute","description":"Read 2 and Open 2 overlap active training; Read 3 overlaps a later training block. They stage future input rather than reducing the cost of the same reads.","focus":["overlap","open2"]},{"title":"Compare elapsed time","description":"Train 1 through Train 3 run without the serial schedule’s intervening input gap. The shorter Epoch span comes from overlap, which requires sufficient host resources and buffer memory.","focus":["train","epoch"]}],"artwork_reviewed":true,"art_sha1":"fee5f06d43facc2a7454352f35b42236d41d6631","art_kind":"svg","art_width":1200,"art_height":348,"art_structural_sha1":"ab702f7ccf7e3f5cf17075b3815d929b677b78c4"},"vol1:fig-float-formats":{"key":"vol1:fig-float-formats","figure_id":"fig-float-formats","source":"books/vol1/backmatter/appendix_machine.qmd","title":"Numerical Format Bit Layouts","status":"ready","treatment":"annotated","question":"How do the numerical formats allocate bits differently?","scope":"Bit width alone does not determine numerical quality, actual throughput, or total memory use; INT8 is not floating point.","regions":{"fp32":{"x":0.0,"y":0.0,"w":1,"h":0.17,"label":"FP32 layout"},"bf16":{"x":0.0,"y":0.25,"w":0.8,"h":0.17,"label":"BF16 layout"},"fp16":{"x":0.0,"y":0.5,"w":0.6,"h":0.17,"label":"FP16 layout"},"int8":{"x":0.0,"y":0.75,"w":0.41,"h":0.17,"label":"INT8 layout"}},"steps":[{"title":"Read the FP32 reference","description":"FP32 allocates a sign bit, eight exponent bits, and 23 mantissa bits. The colored fields separate range-related exponent allocation from precision-related mantissa allocation.","focus":["fp32"]},{"title":"Compare equal-width formats","description":"BF16 and FP16 both use 16 bits but partition them differently. BF16 retains the eight-bit exponent field; FP16 uses five exponent bits and ten mantissa bits.","focus":["bf16","fp16"]},{"title":"Separate integer quantization","description":"INT8 is an eight-bit integer field, not a shorter floating-point exponent/mantissa split. Mapping real-valued tensors into it requires quantization scale and related metadata outside this raw layout.","focus":["int8"]}],"artwork_reviewed":true,"art_sha1":"27b0db8ebfd719ce9181752c3b5ebb9cd4e04afa","art_kind":"svg","art_width":1200,"art_height":426,"art_structural_sha1":"a3a8d400a89dcc6050ddd6b6d89b69f1ae710160"},"vol1:fig-forward-propagation":{"key":"vol1:fig-forward-propagation","figure_id":"fig-forward-propagation","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Training Loop Architecture","status":"ready","treatment":"annotated","question":"How are predictions, gradients, and parameter updates different stages?","scope":"Symbolic training loop; arrows show dependencies and direction, not measured time.","regions":{"forward":{"x":0.0,"y":0.0,"w":0.53,"h":0.51,"label":"Forward network and direction"},"prediction":{"x":0.58,"y":0.29,"w":0.16,"h":0.16,"label":"Prediction"},"truth":{"x":0.79,"y":0.29,"w":0.17,"h":0.16,"label":"True value"},"loss":{"x":0.74,"y":0.51,"w":0.12,"h":0.19,"label":"Loss"},"gradient":{"x":0.61,"y":0.75,"w":0.19,"h":0.17,"label":"Parameter gradients"},"optimizer":{"x":0.43,"y":0.74,"w":0.17,"h":0.17,"label":"Optimizer"},"parameters":{"x":0.07,"y":0.74,"w":0.18,"h":0.17,"label":"Weights and bias"}},"steps":[{"title":"Compute a prediction before evaluating loss","description":"The network propagates activations to the prediction. The true value is a separate supervised input to the loss, not an input to inference computation.","focus":["forward","prediction","truth","loss"]},{"title":"Differentiate the loss","description":"Backpropagation computes parameter gradients through the network’s dependencies. Forward intermediates must remain available until their backward consumers finish.","focus":["loss","gradient","forward"]},{"title":"Apply the update as a separate operation","description":"The optimizer consumes gradients to update weights and biases for the next forward pass. A gradient is a sensitivity, not already an updated weight.","focus":["gradient","optimizer","parameters"]}],"artwork_reviewed":true,"art_sha1":"e4ea9a9df206eb0e059b24723376f91116f19145","art_kind":"svg","art_width":1200,"art_height":599,"art_structural_sha1":"1e92d3e96cf9ee58f2434b77a1afe36092b1db8d"},"vol1:fig-four-pillars":{"key":"vol1:fig-four-pillars","figure_id":"fig-four-pillars","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"The Four Pillars of Data Engineering","status":"ready","treatment":"annotated","question":"Why must data-system improvements be checked against neighboring constraints?","scope":"The links are qualitative trade-offs, not fixed weights or universal conflicts.","regions":{"quality":{"x":0.0,"y":0.0,"w":0.27,"h":0.27,"label":"Quality"},"reliability":{"x":0.73,"y":0.0,"w":0.27,"h":0.27,"label":"Reliability"},"governance":{"x":0.0,"y":0.72,"w":0.27,"h":0.28,"label":"Governance"},"scale":{"x":0.73,"y":0.72,"w":0.27,"h":0.28,"label":"Scalability"},"center":{"x":0.4,"y":0.31,"w":0.2,"h":0.39,"label":"ML data system"},"validation":{"x":0.27,"y":0.03,"w":0.46,"h":0.14,"label":"Validation versus throughput"},"privacy":{"x":0.27,"y":0.83,"w":0.46,"h":0.14,"label":"Performance versus privacy"}},"steps":[{"title":"State the contribution","description":"Quality supplies accurate and suitable training data; Reliability supplies consistent processing. The solid connections point toward the ML Data System that needs both.","focus":["quality","reliability","center"]},{"title":"Check the neighboring cost","description":"The top dashed connection names validation overhead versus throughput. Tightening quality checks can add processing work, so the pipeline must be measured again.","focus":["validation"]},{"title":"Keep growth accountable","description":"Scalability handles growing volumes while Governance supplies compliance and accountability. Their dashed link names performance versus privacy constraints, a design tension rather than permission to discard either requirement.","focus":["scale","governance","privacy"]}],"artwork_reviewed":true,"art_sha1":"2a74331eaf451ebd5c1c6d3fc0f2755cf7547384","art_kind":"svg","art_width":1200,"art_height":576,"art_structural_sha1":"4f9c2c737ee7fe2a491d2e2a48f9a3e71c269d02"},"vol1:fig-frontier-training-cost":{"key":"vol1:fig-frontier-training-cost","figure_id":"fig-frontier-training-cost","source":"books/vol1/15_responsible_engr/15_responsible_engr.qmd","title":"Cost of Training Notable Models","status":"ready","treatment":"annotated","question":"What do estimated frontier-training costs say about access to large training runs?","scope":"Historical final-run compute costs in constant 2023 dollars, not full research budgets, current hardware quotes, or inference expense.","regions":{"early":{"x":0.13,"y":0.31,"w":0.3,"h":0.36,"label":"Earlier frontier estimates"},"recent":{"x":0.59,"y":0.02,"w":0.31,"h":0.34,"label":"Recent frontier estimates"},"gray":{"x":0.36,"y":0.33,"w":0.57,"h":0.44,"label":"Other notable models"},"legend":{"x":0.18,"y":0.87,"w":0.72,"h":0.12,"label":"Frontier-only fitted trend"}},"steps":[{"title":"Separate frontier and notable runs","description":"Red points are models flagged as frontier at release; gray points are other notable models. Both are estimated training-run costs, not every expense of producing a model.","focus":["early","gray"]},{"title":"Read constant-dollar log costs","description":"The vertical log axis represents multiplicative differences in constant 2023 US dollars. Recent frontier estimates extend into the highest plotted cost region.","focus":["recent"]},{"title":"Restrict the fitted trend to its evidence","description":"The dashed fit is calculated over frontier points. It summarizes these historical estimates and motivates access constraints without forecasting the cost of every future model.","focus":["legend","recent"]}],"artwork_reviewed":true,"art_sha1":"671dbe8a5832df296808ac9b3e7dedf1c2ed956f","art_kind":"png","art_width":3315,"art_height":2739},"vol1:fig-governance-layers":{"key":"vol1:fig-governance-layers","figure_id":"fig-governance-layers","source":"books/vol1/15_responsible_engr/15_responsible_engr.qmd","title":"Responsible AI Governance Layers","status":"ready","treatment":"annotated","question":"How do external requirements reach the team that builds a system?","scope":"Nested oversight model, not a certification checklist or automatic proof of compliance.","regions":{"government":{"x":0.31,"y":0,"w":0.44,"h":0.1,"label":"Government regulation"},"industry":{"x":0.32,"y":0.11,"w":0.4,"h":0.1,"label":"Industry oversight"},"organization":{"x":0.28,"y":0.22,"w":0.47,"h":0.13,"label":"Organizational safety culture"},"team":{"x":0.25,"y":0.36,"w":0.38,"h":0.44,"label":"Team reliable systems"},"annotation":{"x":0.16,"y":0.92,"w":0.68,"h":0.07,"label":"Requirements flow inward"}},"steps":[{"title":"Identify the outer requirements","description":"Government regulation establishes applicable duties; industry certification and review provide additional oversight structures. Their applicability depends on the system and setting.","focus":["government","industry"]},{"title":"Translate oversight into operating practice","description":"The organization supplies safety culture, design, leadership commitment, training, and review. These structures connect external requirements with engineering work.","focus":["organization"]},{"title":"Build auditable technical evidence","description":"At the team center, audit trails, verification and bias testing, explainable interfaces, and software-engineering workflows supply inspectable practices. The inward requirements do not become satisfied merely because a control is named.","focus":["team","annotation"]}],"artwork_reviewed":true,"art_sha1":"6bef458dcc4ecfc89acebe0ce9b37aee1468db3b","art_kind":"svg","art_width":1200,"art_height":712,"art_structural_sha1":"5a6834b75564c74db487aad735b7ef443fb7fd4c"},"vol1:fig-grad-accumulation":{"key":"vol1:fig-grad-accumulation","figure_id":"fig-grad-accumulation","source":"books/vol1/08_training/08_training.qmd","title":"Gradient Accumulation","status":"ready","treatment":"annotated","question":"How can several micro-batches contribute to one optimizer update?","scope":"Apply consistent loss normalization; batch-dependent layers and randomness can prevent exact equivalence to a single larger batch.","regions":{"batch1":{"x":0.02,"y":0.09,"w":0.39,"h":0.24,"label":"First micro-batch loss"},"batch2":{"x":0.02,"y":0.37,"w":0.39,"h":0.24,"label":"Second micro-batch loss"},"batch3":{"x":0.02,"y":0.65,"w":0.39,"h":0.24,"label":"Third micro-batch loss"},"gradients":{"x":0.55,"y":0.0,"w":0.2,"h":0.98,"label":"Individual gradients"},"sum":{"x":0.79,"y":0.28,"w":0.21,"h":0.48,"label":"Combined gradient"}},"steps":[{"title":"Keep each micro-batch distinct","description":"Batch 1, Batch 2, and Batch 3 each produce a loss. Sequential micro-batches can reuse sample and activation storage rather than holding the whole logical batch at once.","focus":["batch1","batch2","batch3"]},{"title":"Accumulate parameter gradients","description":"Each loss produces its own gradient tensor. Parameters remain fixed while these contributions accumulate for the same logical optimizer step.","focus":["gradients"]},{"title":"Update after combining","description":"The Sum box combines g₁, g₂, and g₃ for one update. Scale or average consistently with the intended loss; accumulation reduces sample residency, not persistent model or optimizer state.","focus":["sum"]}],"artwork_reviewed":true,"art_sha1":"4c6da2315eb024fa79197fd2522bf03bebc6ad88","art_kind":"svg","art_width":1200,"art_height":309,"art_structural_sha1":"c0dd4ab1e89a22edfa67570a6dce93098f516722"},"vol1:fig-gradient-descent-steps":{"key":"vol1:fig-gradient-descent-steps","figure_id":"fig-gradient-descent-steps","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Gradient Descent on One Weight","status":"ready","treatment":"annotated","question":"How does learning rate change motion on the same loss curve?","scope":"One-dimensional illustrative loss and gradient descent; not a guarantee about a high-dimensional training objective.","regions":{"stable":{"x":0.0,"y":0.0,"w":0.49,"h":0.9,"label":"Well-chosen learning rate"},"oscillation":{"x":0.51,"y":0.0,"w":0.49,"h":0.9,"label":"Overshooting learning rate"},"early":{"x":0.06,"y":0.13,"w":0.11,"h":0.55,"label":"Steep initial descent"},"minimum":{"x":0.2,"y":0.75,"w":0.15,"h":0.13,"label":"Approach to the minimum"}},"steps":[{"title":"Use the local slope","description":"The dashed tangent on the left shows the initial slope. Gradient descent moves opposite that slope, with the learning rate scaling the update.","focus":["early"]},{"title":"Watch updates shrink near the minimum","description":"The green steps become smaller as the slope flattens. The left trajectory reaches the low-loss region without repeatedly crossing far to the other side.","focus":["stable","minimum"]},{"title":"Distinguish oscillation from useful progress","description":"The red path overshoots on every step and converges slowly in the illustrated case. A slightly larger rate would diverge; a longer drawn path is not faster learning.","focus":["oscillation"]}],"artwork_reviewed":true,"art_sha1":"83a645ce625a4bbc36d85ed4e86077fbc73d454f","art_kind":"png","art_width":3660,"art_height":2388},"vol1:fig-granularity":{"key":"vol1:fig-granularity","figure_id":"fig-granularity","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Benchmarking Granularity","status":"ready","treatment":"annotated","question":"Which bottlenecks enter as a benchmark’s boundary expands?","scope":"Four panels show distinct scopes; their measurements are not additive independent components.","regions":{"micro":{"x":0.0,"y":0.0,"w":0.17,"h":1,"label":"ML layers"},"macro":{"x":0.2,"y":0.0,"w":0.18,"h":1,"label":"ML model"},"application":{"x":0.42,"y":0.0,"w":0.19,"h":1,"label":"AI task"},"end":{"x":0.64,"y":0.0,"w":0.36,"h":1,"label":"End-to-end application"}},"steps":[{"title":"Isolate a kernel","description":"ML Layers exposes operations inside a model. A micro-benchmark can isolate kernel behavior while leaving surrounding computation outside its timing boundary.","focus":["micro"]},{"title":"Compose the workload","description":"ML Model adds relationships between models, and AI Task adds Supporting Compute. A gain inside one layer can change when these dependencies share resources.","focus":["macro","application"]},{"title":"Follow the complete request","description":"The End-to-End Application includes Non-AI Compute Nodes. Host and surrounding service work can dominate latency even when isolated AI kernels improve.","focus":["end"]}],"artwork_reviewed":true,"art_sha1":"2217170c38dfa6bcc691d9330397d97b38d3ce5a","art_kind":"svg","art_width":1200,"art_height":201,"art_structural_sha1":"b335172c464368b304fa42cd8bda279a1fdbfc01"},"vol1:fig-hard-labels":{"key":"vol1:fig-hard-labels","figure_id":"fig-hard-labels","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Pervasive Label Errors","status":"ready","treatment":"annotated","question":"Why can a curated benchmark still need expert label review?","scope":"These are documented examples, not estimates of error frequency.","regions":{"mnist":{"x":0.0,"y":0.0,"w":0.14,"h":1,"label":"MNIST digit"},"frog":{"x":0.14,"y":0.0,"w":0.17,"h":1,"label":"CIFAR-10 frog"},"crab":{"x":0.31,"y":0.0,"w":0.17,"h":1,"label":"CIFAR-100 crab"},"teapot":{"x":0.48,"y":0.0,"w":0.16,"h":1,"label":"Caltech-256 teapot"},"stork":{"x":0.64,"y":0.0,"w":0.18,"h":1,"label":"ImageNet stork"},"eye":{"x":0.82,"y":0.0,"w":0.18,"h":1,"label":"QuickDraw eye"}},"steps":[{"title":"Compare pixels and labels","description":"The MNIST digit was assigned 5 and corrected to 3. The CIFAR-10 image was assigned cat and corrected to frog. Read the assigned and corrected labels separately.","focus":["mnist","frog"]},{"title":"Check category semantics","description":"Crab versus lobster and teapot versus ewer expose category distinctions that annotation rubrics and qualified reviewers must resolve.","focus":["crab","teapot"]},{"title":"Route difficult cases","description":"The stork requires fine-grained identification, while the eye drawing illustrates a striking label mismatch. Filtering degraded inputs and routing expertise-sensitive cases address different failure modes.","focus":["stork","eye"]}],"artwork_reviewed":true,"art_sha1":"c13db866d1727ab54702dac446dcfaeb0c51fa78","art_kind":"png","art_width":1386,"art_height":323},"vol1:fig-hog":{"key":"vol1:fig-hog","figure_id":"fig-hog","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"HOG Method","status":"ready","treatment":"annotated","question":"How do local pixel directions become a fixed feature descriptor?","scope":"The figure draws eight orientation bins; cell size and bin count are design choices and differ from the chapter’s separate illustrative cost calculation.","regions":{"image":{"x":0.0,"y":0.15,"w":0.27,"h":0.64,"label":"Input grid and selected patch"},"cell":{"x":0.33,"y":0.21,"w":0.27,"h":0.67,"label":"Magnified gradient cell"},"directions":{"x":0.62,"y":0.25,"w":0.14,"h":0.36,"label":"Eight-direction guide"},"histogram":{"x":0.77,"y":0.23,"w":0.23,"h":0.62,"label":"HOG feature histogram"}},"steps":[{"title":"Choose a local image cell","description":"The red selection links one image patch to the magnified cell. HOG builds local descriptors before a classifier consumes them.","focus":["image","cell"]},{"title":"Accumulate gradient directions","description":"The arrows encode pixel-gradient orientations within the cell. The direction guide specifies the bins into which these local measurements are accumulated.","focus":["cell","directions"]},{"title":"Produce the feature representation","description":"The histogram summarizes local directions, rather than retaining the original pixel layout. This fixed extractor makes preprocessing cost and descriptor design part of the deployed pipeline.","focus":["histogram"]}],"artwork_reviewed":true,"art_sha1":"2f30f93a9ea3c8f4095e7c6707c074180ddffc72","art_kind":"png","art_width":684,"art_height":257},"vol1:fig-host-accelerator-data-movement":{"key":"vol1:fig-host-accelerator-data-movement","figure_id":"fig-host-accelerator-data-movement","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"Host-Accelerator Data Transfer Sequence","status":"ready","treatment":"annotated","question":"Which transfers and dispatches surround accelerator arithmetic?","scope":"Illustrated synchronous discrete host-device execution; arrow spacing does not encode measured duration.","regions":{"copyin":{"x":0.08,"y":0.15,"w":0.56,"h":0.13,"label":"1: input copy to device memory"},"dispatch":{"x":0.33,"y":0.29,"w":0.57,"h":0.13,"label":"2: CPU kernel dispatch"},"compute":{"x":0.7,"y":0.42,"w":0.3,"h":0.21,"label":"3: GPU execution"},"writeback":{"x":0.58,"y":0.64,"w":0.35,"h":0.11,"label":"Device result storage"},"copyout":{"x":0.08,"y":0.74,"w":0.56,"h":0.13,"label":"4: result copy to host"}},"steps":[{"title":"Copy inputs into device memory","description":"Step 1 transfers processing data from main memory to memory for the GPU. Device arithmetic depends on the required operands being available.","focus":["copyin"]},{"title":"Dispatch work separately from data","description":"Step 2 instructs the GPU from the CPU. Sending a kernel instruction does not itself transfer its full input tensors.","focus":["dispatch"]},{"title":"Compute, then store the result","description":"The GPU executes parallel work in step 3 and writes its results to device memory. These are distinct from returning results to the host.","focus":["compute","writeback"]},{"title":"Return the output across the boundary","description":"Step 4 copies the result back to main memory. In this synchronous sequence, copies and dispatch can dominate small kernels even when arithmetic throughput is high.","focus":["copyout"]}],"artwork_reviewed":true,"art_sha1":"78434d3c71b51d45ecee5881aa56dc964c573ff4","art_kind":"svg","art_width":1200,"art_height":503,"art_structural_sha1":"d7b5e4cbd8a29774d2f04620e85c514f8c3d3e67"},"vol1:fig-hw-acceleration-h100-roofline-lighthouses":{"key":"vol1:fig-hw-acceleration-h100-roofline-lighthouses","figure_id":"fig-hw-acceleration-h100-roofline-lighthouses","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"ResNet-50 and GPT-2 XL on the H100 Roofline","status":"ready","treatment":"annotated","question":"When does narrower arithmetic move a layer to a compute ceiling?","scope":"Dense roofline bounds with declared operand-width assumptions, not benchmarked throughput or a model-quality guarantee.","regions":{"decode":{"x":0.12,"y":0.75,"w":0.26,"h":0.2,"label":"GPT-2 XL low-batch decode"},"small":{"x":0.38,"y":0.4,"w":0.29,"h":0.26,"label":"Classifier and stage-2 expansion"},"conv":{"x":0.69,"y":0.13,"w":0.2,"h":0.27,"label":"Stage-3 convolution precision cases"},"ridges":{"x":0.6,"y":0.87,"w":0.3,"h":0.12,"label":"FP16 and INT8 ridge labels"},"ceilings":{"x":0.68,"y":0.06,"w":0.26,"h":0.13,"label":"Dense precision ceilings"}},"steps":[{"title":"Locate low-reuse decoding","description":"GPT-2 XL decode at batch 1 sits far left on the bandwidth slope. Raising a compute ceiling alone does not lift this part of the bound.","focus":["decode"]},{"title":"Compare layers within one model","description":"The classifier and stage-2 expansion also sit on the slope, while stage-3 convolution has much higher intensity. A model does not have one bottleneck shared by every layer.","focus":["small","conv"]},{"title":"Keep operand width explicit","description":"The stage-3 convolution can reach either ceiling when activations use the format width. The point retaining FP16 activations remains below the INT8 ridge, so narrower arithmetic alone is insufficient.","focus":["conv","ridges","ceilings"]}],"artwork_reviewed":true,"art_sha1":"d4348c048b6e857332e172a12bf2b40445b174e9","art_kind":"png","art_width":3315,"art_height":2476},"vol1:fig-hw-lottery":{"key":"vol1:fig-hw-lottery","figure_id":"fig-hw-lottery","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Hardware-Dependent Latency–Accuracy Trade-offs","status":"ready","treatment":"annotated","question":"Why must model selection be measured on the intended hardware path?","scope":"Panels have different latency scales. Compare model variants and accuracy operating points, not visual x-position alone.","regions":{"cpu":{"x":0.0,"y":0.0,"w":0.32,"h":0.45,"label":"CPU float panel"},"uint":{"x":0.34,"y":0.0,"w":0.32,"h":0.45,"label":"CPU uint8 panel"},"gpu":{"x":0.67,"y":0.0,"w":0.33,"h":0.45,"label":"GPU panel"},"tpu":{"x":0.0,"y":0.53,"w":0.32,"h":0.47,"label":"EdgeTPU panel"},"dsp":{"x":0.34,"y":0.53,"w":0.32,"h":0.47,"label":"DSP panel"},"legend":{"x":0.76,"y":0.56,"w":0.22,"h":0.35,"label":"Model-family legend"}},"steps":[{"title":"Match models and axes","description":"The legend identifies model families while each panel uses target-specific latency units and ranges. A point farther left in one panel need not be faster than one in another.","focus":["legend","cpu","uint"]},{"title":"Trace the hardware shift","description":"The purple arrow links MobileNetV3 Large near equal accuracy on CPU float and DSP. It demonstrates a target-dependent latency change, not a claim that every architecture improves by the same factor.","focus":["cpu","dsp"]},{"title":"Select an operating point","description":"GPU and EdgeTPU frontiers reshuffle the choices. Compare the exact model variant at the required accuracy on the intended execution path before choosing the lowest-latency option.","focus":["gpu","tpu"]}],"artwork_reviewed":true,"art_sha1":"90d0eaf3975239746ee63a61b9d763e098ee081e","art_kind":"svg","art_width":1200,"art_height":668,"art_structural_sha1":"e96099d59cc1977c49b9c435ea13dcce2afc7d93"},"vol1:fig-hybrid":{"key":"vol1:fig-hybrid","figure_id":"fig-hybrid","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Hybrid System Interactions","status":"ready","treatment":"annotated","question":"How do deployment artifacts and runtime data travel in opposite directions?","scope":"The five connection labels denote different responsibilities; arrows are not timing measurements, and synchronization does not guarantee instantaneous consistency.","regions":{"cloud":{"x":0.24,"y":0.15,"w":0.49,"h":0.18,"label":"Cloud training and analytics"},"edge":{"x":0.05,"y":0.4,"w":0.19,"h":0.37,"label":"Edge inference and processing"},"mobile":{"x":0.74,"y":0.4,"w":0.19,"h":0.37,"label":"Mobile inference and processing"},"tiny":{"x":0.39,"y":0.63,"w":0.2,"h":0.37,"label":"TinyML sensors and inference"},"deploy":{"x":0.17,"y":0.33,"w":0.7,"h":0.11,"label":"Downward deployment path"},"data":{"x":0.94,"y":0.23,"w":0.06,"h":0.41,"label":"Upward data path"},"sync":{"x":0.64,"y":0.62,"w":0.11,"h":0.1,"label":"State synchronization"}},"steps":[{"title":"Separate training from inference","description":"Cloud Training creates model artifacts while local tiers host inference. The Deploy path distributes those artifacts downward to execution points.","focus":["cloud","deploy"]},{"title":"Follow sensing upward","description":"TinyML Sensors feed local Inference. Data and Results paths carry observations or derived outputs toward other processing tiers and Cloud Analytics.","focus":["tiny","data","cloud"]},{"title":"Coordinate local processing","description":"Edge and Mobile each separate Inference from Processing. Results and Assist connections support cooperation without making every operation a cloud request.","focus":["edge","mobile"]},{"title":"Keep state compatible","description":"The Sync connection denotes coordinated state such as feature definitions and model versions. Hybrid placement adds this consistency obligation alongside compute and bandwidth budgets.","focus":["sync","tiny","mobile"]}],"artwork_reviewed":true,"art_sha1":"d2bd92b21f8f4b99f6705ea6c8791e253420e1a8","art_kind":"svg","art_width":1200,"art_height":716,"art_structural_sha1":"5073ddaf675f6ed6377fd4b89adcc6cb05a1b1bc"},"vol1:fig-im2col-diagram":{"key":"vol1:fig-im2col-diagram","figure_id":"fig-im2col-diagram","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"im2col Transformation","status":"ready","treatment":"annotated","question":"What extra representation does im2col create before matrix multiplication?","scope":"Two 3×3 channels and two 2×2 kernels; output multiplication is not drawn.","regions":{"maps":{"x":0,"y":0.08,"w":0.16,"h":0.9,"label":"Two input feature maps"},"kernels":{"x":0.23,"y":0.18,"w":0.12,"h":0.75,"label":"Two filter kernels"},"matrix":{"x":0.46,"y":0.3,"w":0.39,"h":0.46,"label":"Lowered 4×8 matrix"},"column":{"x":0.94,"y":0.02,"w":0.06,"h":0.93,"label":"Stacked 8×1 filter"}},"steps":[{"title":"Collect one patch from each channel","description":"The red outline on the blue channel selects 1, 2, 4, and 5. Each sliding-window position also includes four entries from the orange channel.","focus":["maps"]},{"title":"Store patches as rows","description":"The 4×8 matrix contains one row per window position and eight columns for the two channels. Overlapping input positions appear in multiple rows, increasing temporary storage.","focus":["matrix"]},{"title":"Align the kernel vector","description":"The two 2×2 kernels become one 8×1 column. Multiplying the lowered matrix by this column produces four output positions, although the product is not shown.","focus":["kernels","column","matrix"]}],"artwork_reviewed":true,"art_sha1":"ea57f53fbef055c5966825bd25dc3db5422852a8","art_kind":"svg","art_width":1200,"art_height":503,"art_structural_sha1":"37058b427163f91ee0721755c8e56c13e9ad6702"},"vol1:fig-imagenet-gpus":{"key":"vol1:fig-imagenet-gpus","figure_id":"fig-imagenet-gpus","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"ImageNet Error and GPU Adoption","status":"ready","treatment":"annotated","question":"What does coincident GPU adoption and lower ImageNet error actually establish?","scope":"Historical paired trends show association; the plot cannot isolate hardware’s causal contribution.","regions":{"early":{"x":0.16,"y":0.05,"w":0.28,"h":0.69,"label":"2010–2011 error points"},"alexnet":{"x":0.46,"y":0.32,"w":0.1,"h":0.46,"label":"2012 transition"},"later":{"x":0.61,"y":0.12,"w":0.27,"h":0.66,"label":"2013–2014 trends"},"left":{"x":0.0,"y":0.0,"w":0.12,"h":0.83,"label":"Top-5 error axis"},"right":{"x":0.88,"y":0.0,"w":0.12,"h":0.83,"label":"GPU-entry count axis"}},"steps":[{"title":"Read each axis separately","description":"The blue line uses the left Top-5 Error Rate axis. Green bars use the right count of entries using GPUs, so heights are not values in a shared unit.","focus":["left","right"]},{"title":"Locate the historical transition","description":"The 2012 point shows a marked error reduction alongside emerging GPU-using entries. It locates an event in time without separating architecture, training, data, and hardware contributions.","focus":["early","alexnet"]},{"title":"Choose a controlled comparison","description":"Later entries show lower error and more GPU adoption. A systems benchmark fixes workload and quality targets to attribute stack performance more clearly than these historical co-trends can.","focus":["later"]}],"artwork_reviewed":true,"art_sha1":"92e40beaa3ff2443775f7061840600cc798827ab","art_kind":"svg","art_width":1200,"art_height":556,"art_structural_sha1":"385af4022790f38d5621e4af3427b340a5a63126"},"vol1:fig-intelligence-deflation":{"key":"vol1:fig-intelligence-deflation","figure_id":"fig-intelligence-deflation","source":"books/vol1/13_model_serving/13_model_serving.qmd","title":"Intelligence Deflation","status":"ready","treatment":"annotated","question":"What does a historical API price floor show about serving economics?","scope":"Dated input-token list prices for named versions; not current quotes, equivalent-quality measurements, or full operating costs.","regions":{"early":{"x":0.14,"y":0.15,"w":0.16,"h":0.36,"label":"Early listed prices"},"later":{"x":0.48,"y":0.25,"w":0.28,"h":0.58,"label":"Later low-price versions"},"floor":{"x":0.15,"y":0.29,"w":0.79,"h":0.68,"label":"Fitted historical price floor"},"deepseek":{"x":0.78,"y":0.57,"w":0.14,"h":0.1,"label":"Later non-floor point"}},"steps":[{"title":"Read the dated unit","description":"The vertical axis gives dollars per one million input tokens on a log scale. Each point belongs to a model version and announcement date.","focus":["early"]},{"title":"Distinguish a floor from every model price","description":"Later models show a wide range of prices. The fit uses successive new lows, so a non-floor point such as DeepSeek-V3 need not lie on it.","focus":["later","deepseek"]},{"title":"Limit the economic inference","description":"The falling historical floor motivates new workflow economics. It does not compare equal quality or account for output tokens, cache policies, and a complete deployed service.","focus":["floor"]}],"artwork_reviewed":true,"art_sha1":"78be0755f07ba94f6ace1e74925c017cde868180","art_kind":"png","art_width":3520,"art_height":2419},"vol1:fig-interactive-loop":{"key":"vol1:fig-interactive-loop","figure_id":"fig-interactive-loop","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"Hypertension Management Loops","status":"ready","treatment":"annotated","question":"Which clinical exchanges appear in these three panels?","scope":"Proposed hypertension workflow, not medical advice; AI recommendations stay within validated authorized clinician-set limits. Developer feedback is outside these three panels.","regions":{"patientai":{"x":0.0,"y":0.0,"w":0.43,"h":0.48,"label":"Patient–AI loop and text"},"clinicalai":{"x":0.5,"y":0.0,"w":0.5,"h":0.48,"label":"Clinical–AI loop and text"},"patientclinical":{"x":0.17,"y":0.51,"w":0.66,"h":0.49,"label":"Patient–clinical loop and text"}},"steps":[{"title":"Read the patient–AI exchange","description":"The patient supplies blood-pressure readings and the AI issues bounded dose recommendations within authorized limits. The panel does not grant unrestricted treatment authority.","focus":["patientai"]},{"title":"Read clinician oversight","description":"The clinical–AI panel connects severe-reading alerts with clinician-set titration limits. Escalation and updating boundaries are distinct from routine automated recommendations.","focus":["clinicalai"]},{"title":"Preserve direct clinical review","description":"The patient–clinical panel retains trend review, adverse-event checks, and shared decisions. These three panels do not depict the separate developer feedback loop.","focus":["patientclinical"]}],"artwork_reviewed":true,"art_sha1":"f3e67a356fd2cb910e9c95b208089f1a186e30a3","art_kind":"svg","art_width":1200,"art_height":317,"art_structural_sha1":"ca021e5850ded0b10537b0b528067a5927a7ac2e"},"vol1:fig-interpretability-spectrum":{"key":"vol1:fig-interpretability-spectrum","figure_id":"fig-interpretability-spectrum","source":"books/vol1/15_responsible_engr/15_responsible_engr.qmd","title":"Model Interpretability Spectrum","status":"ready","treatment":"annotated","question":"What kind of evidence is needed to audit different model families?","scope":"Schematic grouping; interpretability depends on model size and feature meaning, not just family name.","regions":{"intrinsic":{"x":0.16,"y":0,"w":0.34,"h":0.95,"label":"Intrinsically interpretable grouping"},"posthoc":{"x":0.51,"y":0,"w":0.33,"h":0.95,"label":"Post-hoc explanation grouping"},"continuum":{"x":0.15,"y":0.18,"w":0.7,"h":0.24,"label":"Schematic continuum"}},"steps":[{"title":"Inspect model logic when it is tractable","description":"Decision trees, linear regression, and logistic regression occupy the intrinsic group. Direct inspection still depends on manageable size and meaningful input features.","focus":["intrinsic"]},{"title":"Validate a separate explanation","description":"Random forests, neural networks, and CNN/transformer models are grouped as requiring post-hoc explanation here. Methods such as LIME or SHAP introduce a fidelity question rather than exposing the complete model directly.","focus":["posthoc"]},{"title":"Avoid treating the spectrum as quality ranking","description":"The continuum frames an auditability trade-off. A farther-right model is not automatically more accurate, less safe, or impossible to understand in every application.","focus":["continuum"]}],"artwork_reviewed":true,"art_sha1":"15d43d1b184c52895ec42d8663b6387d0e0edb6b","art_kind":"svg","art_width":1200,"art_height":277,"art_structural_sha1":"ad1dd2dd429e2b1e33f7c5727044cf58ea695737"},"vol1:fig-invariants-cycle":{"key":"vol1:fig-invariants-cycle","figure_id":"fig-invariants-cycle","source":"books/vol1/16_conclusion/16_conclusion.qmd","title":"The Cycle of ML Systems (13 Principles)","status":"ready","treatment":"annotated","question":"How do deployment lessons feed the next systems design pass?","scope":"The labels include bounds, diagnostics, policies, and heuristics, not thirteen universal laws.","regions":{"foundations":{"x":0.0,"y":0.17,"w":0.35,"h":0.4,"label":"Foundations and principles 1–2"},"development":{"x":0.45,"y":0.0,"w":0.55,"h":0.38,"label":"Development and principles 3–4"},"optimization":{"x":0.72,"y":0.42,"w":0.28,"h":0.44,"label":"Optimization and principles 5–8"},"deployment":{"x":0.0,"y":0.62,"w":0.48,"h":0.38,"label":"Deployment and principles 9–13"},"center":{"x":0.43,"y":0.35,"w":0.17,"h":0.32,"label":"Conservation of Complexity"}},"steps":[{"title":"Carry foundation constraints forward","description":"Foundations contributes Data as Code and Data Gravity. Development adds the Iron Law and Silicon Contract as the system moves from inputs to an executable model.","focus":["foundations","development"]},{"title":"Optimize within a budget","description":"The optimization transition names Pareto, arithmetic intensity, energy movement, and Amdahl considerations. An improvement must satisfy the relevant assumptions rather than maximize one isolated metric.","focus":["optimization"]},{"title":"Return evidence to design","description":"Deployment diagnostics identify drift, skew, latency, and feedback risks. The cycle returns this evidence to foundations; Conservation of Complexity asks where displaced engineering burden has landed.","focus":["deployment","center"]}],"artwork_reviewed":true,"art_sha1":"87ed111f4d0c4983c501168e320d81f7924fbfa0","art_kind":"svg","art_width":1200,"art_height":711,"art_structural_sha1":"ac23738357d64c5795c7781e2fd7ec8595f5a7b2"},"vol1:fig-iron-law-heatmap":{"key":"vol1:fig-iron-law-heatmap","figure_id":"fig-iron-law-heatmap","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"The Iron Law Heatmap","status":"ready","treatment":"annotated","question":"Why can a much faster accelerator yield only a small system speedup?","scope":"Amdahl model for one specified intervention; the accelerated fraction is not a fixed property of all hardware.","regions":{"low":{"x":0.1,"y":0.52,"w":0.71,"h":0.36,"label":"Substantial unaffected work"},"high":{"x":0.42,"y":0.07,"w":0.4,"h":0.24,"label":"High accelerated fraction"},"gain":{"x":0.1,"y":0.89,"w":0.75,"h":0.1,"label":"Accelerator-gain axis"},"scale":{"x":0.84,"y":0.06,"w":0.15,"h":0.84,"label":"Overall-speedup scale"}},"steps":[{"title":"Separate gain from coverage","description":"The horizontal axis changes gain on the accelerated work. The vertical axis changes how much original runtime that intervention can affect. These are independent requirements.","focus":["gain"]},{"title":"Unaffected time sets a ceiling","description":"In the lower band, contours flatten as accelerator gain grows. With accelerated fraction 0.9, the remaining tenth of runtime limits total speedup to 10× even at infinite gain.","focus":["low"]},{"title":"Large gains require broad coverage","description":"Only near the upper-right corner do high accelerator gain and high coverage coincide. Read the color scale as total speedup, not accelerator throughput.","focus":["high","scale"]}],"artwork_reviewed":true,"art_sha1":"caed2becf3373a48dcc6b1d444c70f55862e9b7c","art_kind":"png","art_width":3548,"art_height":2370},"vol1:fig-iterative-pruning":{"key":"vol1:fig-iterative-pruning","figure_id":"fig-iterative-pruning","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Illustrative Iterative Pruning Performance","status":"ready","treatment":"annotated","question":"How does recovery training fit between successive structural cuts?","scope":"These illustrative runs do not control total recovery budget against one-shot pruning; their accuracy values are not a universal pruning curve.","regions":{"cycle1":{"x":0,"y":0,"w":1,"h":0.32,"label":"First prune and fine-tune cycle"},"cycle2":{"x":0,"y":0.34,"w":1,"h":0.32,"label":"Second cycle"},"cycle3":{"x":0,"y":0.69,"w":1,"h":0.31,"label":"Third cycle"},"prune":{"x":0.51,"y":0.07,"w":0.13,"h":0.87,"label":"Post-prune accuracy boxes"},"recover":{"x":0.88,"y":0.07,"w":0.12,"h":0.87,"label":"Recovered accuracy boxes"}},"steps":[{"title":"Make the first cut","description":"The first row starts at 0.995 and prunes selected channels. Test accuracy immediately drops to 0.971, separating structural removal from recovery.","focus":["cycle1","prune"]},{"title":"Recover before cutting again","description":"Fine-tuning raises the first result to 0.992. The second row starts from that recovered model and repeats the cut-and-recovery pattern.","focus":["cycle1","cycle2","recover"]},{"title":"Track the final state","description":"The third row ends at 0.991 after the third recovery stage. The final network has fewer channels, while all recovery rounds have incurred training cost.","focus":["cycle3","recover"]},{"title":"Compare schedules fairly","description":"The intermediate drops explain why gradual cuts can help recovery. Comparing with one-shot pruning still requires matched final geometry and total fine-tuning budget.","focus":["prune","recover"]}],"artwork_reviewed":true,"art_sha1":"12994364219f49cf684e1288c7aec586a003a569","art_kind":"svg","art_width":1200,"art_height":882,"art_structural_sha1":"24101cc1f92b15703b0a35e11456ac02fee905cf"},"vol1:fig-kd-overview":{"key":"vol1:fig-kd-overview","figure_id":"fig-kd-overview","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Knowledge Distillation Workflow","status":"ready","treatment":"annotated","question":"Why does student training need both soft and hard supervision paths?","scope":"Only the student is optimized by the shown training losses; the diagram does not imply copying teacher parameters or guaranteeing teacher-level quality.","regions":{"input":{"x":0,"y":0.26,"w":0.08,"h":0.15,"label":"Shared input"},"teacher":{"x":0.12,"y":0,"w":0.46,"h":0.25,"label":"Teacher network"},"student":{"x":0.12,"y":0.35,"w":0.46,"h":0.25,"label":"Student network"},"soft":{"x":0.61,"y":0.08,"w":0.39,"h":0.38,"label":"Temperature-scaled distillation path"},"hard":{"x":0.61,"y":0.56,"w":0.39,"h":0.44,"label":"Hard-label task path"}},"steps":[{"title":"Share the example","description":"Input x feeds both networks. The teacher supplies a target distribution while the smaller student produces predictions for training.","focus":["input","teacher","student"]},{"title":"Match softened predictions","description":"The teacher's soft labels and the student's soft predictions use temperature greater than 1. Distillation loss compares these distributions.","focus":["soft"]},{"title":"Retain task supervision","description":"The student also produces predictions at temperature 1. Student loss compares them against the ground-truth hard label rather than the teacher distribution.","focus":["hard"]},{"title":"Deploy the trained student","description":"The two objectives train the student architecture. Its size and supported execution path determine deployment savings; the larger teacher is a training resource.","focus":["student","soft","hard"]}],"artwork_reviewed":true,"art_sha1":"92277dc28b11ff1378400aefaef6d76df1c7189d","art_kind":"svg","art_width":1200,"art_height":505,"art_structural_sha1":"8b891cbf658d37d3c505286114215113587b97fc"},"vol1:fig-kd-targets":{"key":"vol1:fig-kd-targets","figure_id":"fig-kd-targets","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Soft Target Distribution","status":"ready","treatment":"annotated","question":"What information can a soft target contain beyond the top class?","scope":"The printed probabilities are a teaching distribution, not proof that a student will inherit all teacher behavior.","regions":{"cat":{"x":0.23,"y":0.09,"w":0.17,"h":0.72,"label":"Cat probability"},"dog":{"x":0.49,"y":0.69,"w":0.17,"h":0.12,"label":"Dog probability"},"fox":{"x":0.75,"y":0.73,"w":0.17,"h":0.08,"label":"Fox probability"},"axis":{"x":0,"y":0,"w":0.16,"h":0.85,"label":"Probability scale"}},"steps":[{"title":"Find the leading class","description":"Cat has 85 percent probability and is the teacher's preferred class. A hard one-hot target would keep only the correct-class distinction.","focus":["cat","axis"]},{"title":"Inspect the alternatives","description":"Dog retains 10 percent and Fox 5 percent. Their relative probabilities provide additional relationships among classes for the distillation objective.","focus":["dog","fox"]},{"title":"Use a richer training signal","description":"The student can learn from the full distribution rather than only the top label. What transfers depends on the student, data, temperature, and loss weighting.","focus":["cat","dog","fox"]}],"artwork_reviewed":true,"art_sha1":"2bbd912242c98e542656ed39180c96ecd76ec03a","art_kind":"svg","art_width":1200,"art_height":698,"art_structural_sha1":"2294a816e26f67a6d6689c0aa5f65cbdeb45c1ec"},"vol1:fig-keywords":{"key":"vol1:fig-keywords","figure_id":"fig-keywords","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Keyword Spotting in Action","status":"ready","treatment":"annotated","question":"How does a wake word gate the rest of a voice interaction?","scope":"This is an illustrative exchange; the greeting is not required device behavior.","regions":{"speaker":{"x":0.01,"y":0.09,"w":0.48,"h":0.87,"label":"Smart speaker"},"wake":{"x":0.8,"y":0.01,"w":0.19,"h":0.25,"label":"Wake word"},"reply":{"x":0.58,"y":0.29,"w":0.17,"h":0.27,"label":"Acknowledgment"},"command":{"x":0.63,"y":0.61,"w":0.36,"h":0.28,"label":"Command"}},"steps":[{"title":"Listen for the keyword","description":"The speaker must monitor incoming audio before a user issues a command. A lightweight wake-word detector performs this continuous task.","focus":["speaker"]},{"title":"Recognize Alexa","description":"The first blue bubble contains the wake word. Recognition triggers the main assistant interaction rather than requiring the full assistant to process every sound.","focus":["wake"]},{"title":"Open the command exchange","description":"The gray acknowledgment separates detection from the later command. The final blue bubble supplies “dim the lights” after the wake word.","focus":["reply","command"]}],"artwork_reviewed":true,"art_sha1":"d628924289b211a84f4ad37ce8d2c64f744e0597","art_kind":"png","art_width":940,"art_height":373},"vol1:fig-kv-cache-growth":{"key":"vol1:fig-kv-cache-growth","figure_id":"fig-kv-cache-growth","source":"books/vol1/13_model_serving/13_model_serving.qmd","title":"The KV-Cache Explosion","status":"ready","treatment":"annotated","question":"Why do context length and concurrency compete for the same memory?","scope":"FP16 KV cache for a 70B-class GQA model after INT4 weights; budget is before runtime overhead and chart rounds it to 51 GB.","regions":{"budget":{"x":0.11,"y":0.45,"w":0.88,"h":0.1,"label":"Post-weight KV budget"},"b32":{"x":0.18,"y":0.4,"w":0.09,"h":0.19,"label":"Batch 32 budget crossing"},"b16":{"x":0.31,"y":0.4,"w":0.12,"h":0.19,"label":"Batch 16 growth"},"lower":{"x":0.48,"y":0.52,"w":0.45,"h":0.32,"label":"Batch1 and batch4 growth"}},"steps":[{"title":"Subtract persistent weights first","description":"The dashed red line is the remaining cache budget after model weights, not the entire accelerator capacity. Runtime workspace can reduce the usable remainder further.","focus":["budget"]},{"title":"Grow all concurrent request caches","description":"Each curve rises with context length, and its slope increases with batch size. Batch 32 reaches the budget near 4.8K tokens because 32 request caches draw from the same remaining HBM.","focus":["b32"]},{"title":"Trade context for concurrency","description":"Batch 16 can sustain longer contexts before reaching the same budget; batches 1 and 4 use less cache at a given context. Allocation schemes can reduce waste but cannot remove these required KV entries.","focus":["b16","lower"]}],"artwork_reviewed":true,"art_sha1":"97be06d05e7c524ada56a9c07aa2bcffbaa902e5","art_kind":"png","art_width":3550,"art_height":2221},"vol1:fig-labels":{"key":"vol1:fig-labels","figure_id":"fig-labels","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Data Annotation Modalities","status":"ready","treatment":"annotated","question":"How does the task change the annotation a pipeline must store?","scope":"These rows show different label representations, not interchangeable supervision for one objective.","regions":{"class":{"x":0.0,"y":0.11,"w":1,"h":0.18,"label":"Classification row"},"box":{"x":0.0,"y":0.29,"w":1,"h":0.18,"label":"Bounding-box row"},"mask":{"x":0.0,"y":0.47,"w":1,"h":0.18,"label":"Segmentation row"},"caption":{"x":0.0,"y":0.65,"w":1,"h":0.18,"label":"Caption row"},"audio":{"x":0.0,"y":0.83,"w":1,"h":0.17,"label":"Transcript row"}},"steps":[{"title":"Label the scene","description":"Classification attaches coarse labels to the whole dog-and-blanket image. It does not encode the dog’s boundary.","focus":["class"]},{"title":"Localize the object","description":"The bounding box records an object’s extent. The segmentation mask instead assigns labels to individual pixels, changing annotation work and storage requirements.","focus":["box","mask"]},{"title":"Describe the input","description":"The caption represents the image as language; the transcript represents audio as words. Label schemas must match the input modality and learning task.","focus":["caption","audio"]}],"artwork_reviewed":true,"art_sha1":"804de25e3e5c89f4ae93f8a3e1490ed9d4d42c27","art_kind":"png","art_width":1468,"art_height":853},"vol1:fig-layers":{"key":"vol1:fig-layers","figure_id":"fig-layers","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Layered Network Architecture","status":"ready","treatment":"annotated","question":"Which network widths are fixed by the task, and which are design choices?","scope":"Feedforward schematic; the drawn hidden widths do not specify a trained model or measured feature hierarchy.","regions":{"input":{"x":0.0,"y":0.33,"w":0.08,"h":0.4,"label":"Four-feature input layer"},"hidden1":{"x":0.18,"y":0.1,"w":0.08,"h":0.79,"label":"First hidden layer"},"hidden2":{"x":0.36,"y":0.17,"w":0.09,"h":0.62,"label":"Second hidden layer"},"hidden3":{"x":0.53,"y":0.0,"w":0.09,"h":0.99,"label":"Third hidden layer"},"hidden4":{"x":0.71,"y":0.21,"w":0.09,"h":0.57,"label":"Fourth hidden layer"},"output":{"x":0.9,"y":0.4,"w":0.1,"h":0.26,"label":"Two-output layer"}},"steps":[{"title":"Fix the task interfaces","description":"The input layer represents four features and the output layer represents two predictions. These widths follow the input representation and target task.","focus":["input","output"]},{"title":"Choose hidden capacity","description":"The interior layers widen and narrow. Hidden widths are architectural decisions, so they change parameters and computation without changing the task interfaces.","focus":["hidden1","hidden2","hidden3","hidden4"]},{"title":"Preserve layer dependencies","description":"Each hidden layer transforms the preceding representation before the next layer can consume it. Parallel neurons within a layer do not remove dependencies between layers.","focus":["hidden2","hidden3"]}],"artwork_reviewed":true,"art_sha1":"4d374f7188a9cb64974724f8be6519fc14deec84","art_kind":"svg","art_width":1200,"art_height":493,"art_structural_sha1":"f6fa877fc73e5e8f153cb288c6885b27b147b5bc"},"vol1:fig-layers-blocks":{"key":"vol1:fig-layers-blocks","figure_id":"fig-layers-blocks","source":"books/vol1/08_training/08_training.qmd","title":"Layer-Wise Model Partitioning","status":"ready","treatment":"annotated","question":"Why does layerwise partitioning leave devices waiting for one micro-batch?","scope":"The diagram allocates contiguous blocks; it does not include a micro-batch pipeline schedule.","regions":{"d1":{"x":0.0,"y":0.0,"w":0.17,"h":1,"label":"Device 1 blocks 1–6"},"d2":{"x":0.28,"y":0.0,"w":0.17,"h":1,"label":"Device 2 blocks 7–12"},"d3":{"x":0.56,"y":0.0,"w":0.17,"h":1,"label":"Device 3 blocks 13–18"},"d4":{"x":0.83,"y":0.0,"w":0.17,"h":1,"label":"Device 4 blocks 19–24"},"links":{"x":0.17,"y":0.35,"w":0.66,"h":0.21,"label":"Activation transfers"}},"steps":[{"title":"Read the allocation","description":"The 24 blocks are divided into four contiguous six-block partitions. This spreads layer storage across GPUs rather than replicating all layers everywhere.","focus":["d1","d2","d3","d4"]},{"title":"Follow the dependency","description":"Activations cross each boundary from one partition to the next. For a single micro-batch, Device 2 waits for Device 1’s boundary result, and later devices wait in turn.","focus":["d1","links","d2"]},{"title":"Separate capacity from utilization","description":"Device 4 enables the final partition to fit, but a four-device placement alone does not create four independent simultaneous computations. Improving utilization needs an explicit schedule such as micro-batch pipelining.","focus":["d3","d4"]}],"artwork_reviewed":true,"art_sha1":"4568bf20aa92a6bcf8e10b9f3098936bf8bd5f1d","art_kind":"svg","art_width":1200,"art_height":321,"art_structural_sha1":"999d210a366fb6639630a4e35777871243ef75ee"},"vol1:fig-lifecycle-overview":{"key":"vol1:fig-lifecycle-overview","figure_id":"fig-lifecycle-overview","source":"books/vol1/03_ml_lifecycle/03_ml_lifecycle.qmd","title":"Simplified Lifecycle with Feedback","status":"ready","treatment":"annotated","question":"Where does production evidence reenter the ML lifecycle?","scope":"Six-stage lifecycle abstraction; the diagram does not prescribe one fixed release cadence.","regions":{"problem":{"x":0.0,"y":0.0,"w":0.23,"h":0.49,"label":"1: problem definition"},"data":{"x":0.25,"y":0.0,"w":0.23,"h":0.49,"label":"2: collection and preparation"},"model":{"x":0.49,"y":0.0,"w":0.25,"h":0.49,"label":"3: development and training"},"evaluation":{"x":0.75,"y":0.0,"w":0.25,"h":0.49,"label":"4: evaluation and validation"},"deployment":{"x":0.75,"y":0.54,"w":0.25,"h":0.45,"label":"5: deployment and integration"},"monitoring":{"x":0.5,"y":0.53,"w":0.24,"h":0.46,"label":"6: monitoring and maintenance"},"feedback":{"x":0.41,"y":0.35,"w":0.18,"h":0.4,"label":"Monitoring-to-data feedback path"}},"steps":[{"title":"Define success before producing a model","description":"Problem definition establishes targets and constraints. Collection and preparation then produce the data on which development depends.","focus":["problem","data"]},{"title":"Require evidence before release","description":"Training produces weights; evaluation checks them against the targets. Deployment installs an approved artifact rather than treating training completion as sufficient evidence.","focus":["model","evaluation","deployment"]},{"title":"Close the loop with production evidence","description":"Monitoring observes the deployed system. The dashed feedback path returns its discoveries to data collection and preparation when the production setting no longer matches the existing data.","focus":["monitoring","feedback","data"]}],"artwork_reviewed":true,"art_sha1":"c11201c5d167a0667445365fe5c74643f8dab51e","art_kind":"svg","art_width":1200,"art_height":481,"art_structural_sha1":"b226b0ce8bd1bf0a4f8f873bed9fa962db579ea5"},"vol1:fig-linear-scaling-failure":{"key":"vol1:fig-linear-scaling-failure","figure_id":"fig-linear-scaling-failure","source":"books/vol1/08_training/08_training.qmd","title":"Illustrative Linear-Scaling Scenario","status":"ready","treatment":"annotated","question":"Why does a larger batch require an optimization check as well as a throughput check?","scope":"Synthetic curves in arbitrary units illustrate a scenario; linear learning-rate scaling is not a convergence guarantee.","regions":{"legend":{"x":0.55,"y":0.02,"w":0.43,"h":0.21,"label":"Batch and learning-rate legend"},"early":{"x":0.1,"y":0.06,"w":0.29,"h":0.65,"label":"Early loss trajectories"},"late":{"x":0.51,"y":0.62,"w":0.46,"h":0.26,"label":"Later loss trajectories"},"gap":{"x":0.79,"y":0.57,"w":0.19,"h":0.23,"label":"Optimization gap"}},"steps":[{"title":"Hold the baseline clear","description":"The blue curve is batch 32. The legend distinguishes two batch-256 runs by learning-rate policy, so batch size is not the only changed setting.","focus":["legend"]},{"title":"Inspect the fixed-rate scenario","description":"The dashed batch-256 trajectory decreases more slowly in this illustration. Compare it with the blue baseline at the same epoch rather than reading wall-clock throughput from the x-axis.","focus":["early","late"]},{"title":"Verify quality after scaling","description":"The red Optimization Gap marks the remaining loss difference; the green scaled-rate curve lies near the baseline. Faster hardware execution is useful only if the training recipe still reaches its quality target.","focus":["gap","late"]}],"artwork_reviewed":true,"art_sha1":"e655050b0e005a2884a3a0a907850a968012608d","art_kind":"png","art_width":3293,"art_height":2110},"vol1:fig-matrix-factorization":{"key":"vol1:fig-matrix-factorization","figure_id":"fig-matrix-factorization","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Low-Rank Factorization","status":"ready","treatment":"annotated","question":"When can two factors represent a weight matrix with fewer parameters?","scope":"W is approximated by U times V-transpose. Lower storage requires k(m+n) to be below mn, and accuracy and runtime must be validated.","regions":{"w":{"x":0,"y":0,"w":0.26,"h":0.98,"label":"Original m by n matrix W"},"u":{"x":0.41,"y":0,"w":0.18,"h":0.98,"label":"Left m by k factor U"},"vt":{"x":0.74,"y":0.18,"w":0.26,"h":0.58,"label":"Right k by n factor V transpose"}},"steps":[{"title":"Count the original representation","description":"W contains m times n stored values. Its full dense operation provides the reference against which compression is evaluated.","focus":["w"]},{"title":"Introduce the shared rank","description":"U has shape m by k and V-transpose has shape k by n. The shared dimension k makes their product compatible with W.","focus":["u","vt"]},{"title":"Trade one operation for two","description":"The factors store k(m+n) values and execute two factor operations. Choosing a small k may save storage but introduces approximation error and additional kernel boundaries.","focus":["w","u","vt"]}],"artwork_reviewed":true,"art_sha1":"73986b9029f3fa1dfb1af65ade2c664b4a5111f3","art_kind":"svg","art_width":1200,"art_height":560,"art_structural_sha1":"045770d638365ca92e7ebf96898dd3371819d8c3"},"vol1:fig-memory-hierarchy":{"key":"vol1:fig-memory-hierarchy","figure_id":"fig-memory-hierarchy","source":"books/vol1/backmatter/appendix_machine.qmd","title":"The Memory Hierarchy","status":"ready","treatment":"annotated","question":"Why stage data near computation instead of reading everything from storage?","scope":"The pyramid is qualitative. Access ratios in the caption are illustrative; tier access costs depend on the platform and operation.","regions":{"registers":{"x":0.39,"y":0.0,"w":0.18,"h":0.28,"label":"Registers"},"cache":{"x":0.32,"y":0.27,"w":0.32,"h":0.25,"label":"L1/L2/L3 cache"},"memory":{"x":0.24,"y":0.51,"w":0.48,"h":0.25,"label":"HBM/DRAM"},"storage":{"x":0.17,"y":0.75,"w":0.63,"h":0.25,"label":"Storage"},"capacity":{"x":0.0,"y":0.0,"w":0.15,"h":1,"label":"Capacity and cost direction"},"latency":{"x":0.84,"y":0.0,"w":0.16,"h":1,"label":"Speed and latency direction"}},"steps":[{"title":"Start from capacity","description":"Storage forms the broad base, with HBM/DRAM above it. Lower tiers provide larger capacity at lower cost but do not offer the lowest access latency.","focus":["storage","memory","capacity"]},{"title":"Stage for reuse","description":"Caches and registers sit closer to arithmetic. Reusing staged values avoids repeatedly paying a lower-tier access cost, while their limited capacity constrains what can remain resident.","focus":["cache","registers"]},{"title":"Balance both directions","description":"The side arrows oppose capacity and cost against speed and latency. A hierarchy works because no single medium supplies every desired property at once.","focus":["capacity","latency"]}],"artwork_reviewed":true,"art_sha1":"752b49a096512567967fd4a933307a3bc9561886","art_kind":"svg","art_width":1200,"art_height":502,"art_structural_sha1":"422978b6ce562629327bbcdc8014ff7511888279"},"vol1:fig-memory-wall":{"key":"vol1:fig-memory-wall","figure_id":"fig-memory-wall","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"Model Size vs. Hardware Bandwidth","status":"ready","treatment":"annotated","question":"What does the widening gap between the two growth indices establish?","scope":"Historical normalized growth comparison, not a measured per-token latency plot; sparse total parameters are excluded from the dense fit.","regions":{"baseline":{"x":0.09,"y":0.63,"w":0.24,"h":0.23,"label":"2014 baseline and early observations"},"dense":{"x":0.43,"y":0.08,"w":0.43,"h":0.4,"label":"Dense model-parameter observations"},"bandwidth":{"x":0.45,"y":0.48,"w":0.41,"h":0.3,"label":"Per-device bandwidth observations"},"sparse":{"x":0.77,"y":0.04,"w":0.22,"h":0.2,"label":"Open sparse-model marker"},"gap":{"x":0.44,"y":0.37,"w":0.29,"h":0.25,"label":"Gap between fitted log-growth trends"}},"steps":[{"title":"Normalize before comparing","description":"Both series measure base-10 logarithmic growth relative to 2014. A vertical unit is a tenfold change, not one byte or one bandwidth unit.","focus":["baseline"]},{"title":"Compare demand with supply carefully","description":"Dense parameters grow much faster across the plotted decade than per-device bandwidth. In streamed dense decoding, this can increase the weight-traffic burden relative to available bandwidth.","focus":["dense","bandwidth","gap"]},{"title":"Keep sparse totals separate","description":"The open marker reports total parameters of a sparse expert model and is not used in the dense trend fit. Selected experts, rather than all stored parameters, determine its active weight traffic.","focus":["sparse"]}],"artwork_reviewed":true,"art_sha1":"d92199154687945c3a6699972593e2ec925ebc8d","art_kind":"png","art_width":3378,"art_height":2616},"vol1:fig-microprocessor-trends":{"key":"vol1:fig-microprocessor-trends","figure_id":"fig-microprocessor-trends","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Fifty Years of Microprocessor Trends","status":"ready","treatment":"annotated","question":"Why did rising transistor counts stop guaranteeing faster single-thread execution?","scope":"Historical cross-chip observations with series-specific units on a logarithmic axis; the plot does not isolate a controlled causal intervention.","regions":{"legend":{"x":0.13,"y":0.01,"w":0.83,"h":0.14,"label":"Series and units"},"band":{"x":0.67,"y":0.17,"w":0.05,"h":0.71,"label":"End of Dennard scaling"},"transistors":{"x":0.72,"y":0.18,"w":0.26,"h":0.26,"label":"Later transistor counts"},"clock":{"x":0.72,"y":0.53,"w":0.26,"h":0.09,"label":"Later clock frequencies"},"cores":{"x":0.72,"y":0.62,"w":0.26,"h":0.25,"label":"Later power and core counts"}},"steps":[{"title":"Separate the quantities","description":"The legend assigns different units to transistor count, benchmark performance, frequency, power, and cores. Their vertical positions cannot be compared as if they were the same resource.","focus":["legend"]},{"title":"Locate the architectural transition","description":"The gray band marks the end of broad Dennard scaling in the mid-2000s. It is a historical reference interval, not a measured discontinuity on every chip.","focus":["band"]},{"title":"Compare capacity with clock rate","description":"Red transistor points keep rising while green frequency points remain in a much narrower band. More transistors no longer translate into proportional clock increases.","focus":["transistors","clock"]},{"title":"Look for parallel resources","description":"Logical core counts rise after staying near one in earlier decades. This motivates parallel execution and specialization rather than relying on faster sequential code.","focus":["cores"]}],"artwork_reviewed":true,"art_sha1":"7e369c66b635212eea4cd408adb0d39e593ece34","art_kind":"png","art_width":3315,"art_height":2896},"vol1:fig-misalignment":{"key":"vol1:fig-misalignment","figure_id":"fig-misalignment","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Shared Dataset Bias Propagation","status":"ready","treatment":"annotated","question":"Why are failures from several models not necessarily independent?","scope":"Shared data can correlate blind spots; the figure does not measure correlation or assert identical errors.","regions":{"repository":{"x":0.33,"y":0.0,"w":0.34,"h":0.26,"label":"Central training dataset"},"fanout":{"x":0.03,"y":0.26,"w":0.94,"h":0.16,"label":"Shared-data fan-out"},"models":{"x":0.01,"y":0.4,"w":0.97,"h":0.2,"label":"Models A through E"},"issues":{"x":0.05,"y":0.6,"w":0.94,"h":0.17,"label":"Convergent limitations"},"alignment":{"x":0.34,"y":0.77,"w":0.32,"h":0.23,"label":"Limited real-world alignment"}},"steps":[{"title":"Locate the common dependency","description":"All five models draw from one Central Training Dataset Repository. Model diversity therefore does not automatically provide diverse training evidence.","focus":["repository","fanout"]},{"title":"Separate models from evidence","description":"Models A through E are distinct model boxes, but their incoming data path is shared. A coverage omission in that data can remain across several models.","focus":["models"]},{"title":"Trace correlated risk","description":"Bias propagation, shared limits, blind spots, common weaknesses, and systemic issues converge on Limited Real-World Alignment. Test coverage independently rather than assuming an ensemble cancels these risks.","focus":["issues","alignment"]}],"artwork_reviewed":true,"art_sha1":"819f1b01926de9a320456d33a1bf8620c99ec0ad","art_kind":"svg","art_width":1200,"art_height":763,"art_structural_sha1":"be94aad8a260a7aeac0303ea6c7d9f01ed5ffb68"},"vol1:fig-mixed-precision":{"key":"vol1:fig-mixed-precision","figure_id":"fig-mixed-precision","source":"books/vol1/08_training/08_training.qmd","title":"Conventional FP16 Mixed-Precision Training","status":"ready","treatment":"annotated","question":"How does conventional FP16 training preserve an FP32 update path?","scope":"This is one conventional recipe; frameworks vary, and BF16 commonly omits loss scaling.","regions":{"master":{"x":0.65,"y":0.0,"w":0.35,"h":0.22,"label":"FP32 master weights"},"cast":{"x":0.65,"y":0.24,"w":0.35,"h":0.38,"label":"Cast and FP16 weights"},"forward":{"x":0.65,"y":0.64,"w":0.35,"h":0.35,"label":"FP16 forward computation"},"scale":{"x":0.0,"y":0.75,"w":0.35,"h":0.24,"label":"Scaled FP32 loss"},"grad":{"x":0.0,"y":0.36,"w":0.35,"h":0.29,"label":"Scaled FP16 gradients"},"unscale":{"x":0.0,"y":0.0,"w":0.35,"h":0.35,"label":"FP32 gradients and unscale"}},"steps":[{"title":"Keep the master copy","description":"FP32 Master Weights are cast for FP16 computation. The lower-precision weights serve the forward path while the master copy supports the later update.","focus":["master","cast"]},{"title":"Scale before backward","description":"The forward path produces a loss; Step 3 scales it before backpropagation. The scaled FP16 gradient path helps avoid losing small gradient values.","focus":["forward","scale","grad"]},{"title":"Unscale before updating","description":"Step 5 copies and unscales gradients into the FP32 path. Only then does Step 6 update the FP32 master weights, preserving the meaning of the optimizer step.","focus":["unscale","master"]}],"artwork_reviewed":true,"art_sha1":"be615f477359c4de720d46eadd5fc3f910306d06","art_kind":"svg","art_width":1200,"art_height":719,"art_structural_sha1":"0b75973d4e20dccac195cead7df2d5a6e9431522"},"vol1:fig-ml-lifecycle":{"key":"vol1:fig-ml-lifecycle","figure_id":"fig-ml-lifecycle","source":"books/vol1/03_ml_lifecycle/03_ml_lifecycle.qmd","title":"Dual-Pipeline ML Development","status":"ready","treatment":"annotated","question":"Why do the data and model pipelines need different feedback loops?","scope":"Ten-block abstraction; loop arrows indicate iteration rather than measured execution speed.","regions":{"collection":{"x":0.0,"y":0.12,"w":0.12,"h":0.27,"label":"Collection"},"curation":{"x":0.17,"y":0.12,"w":0.3,"h":0.27,"label":"Ingestion and curation"},"validation":{"x":0.53,"y":0.12,"w":0.47,"h":0.27,"label":"Labeling, validation, preparation"},"train":{"x":0.75,"y":0.72,"w":0.14,"h":0.28,"label":"Training"},"evaluate":{"x":0.54,"y":0.72,"w":0.13,"h":0.28,"label":"Model evaluation"},"release":{"x":0.11,"y":0.72,"w":0.36,"h":0.28,"label":"System validation and deployment"},"datafixes":{"x":0.03,"y":0.0,"w":0.75,"h":0.12,"label":"Upstream data feedback"}},"steps":[{"title":"Prepare a versioned learning input","description":"The top row proceeds from collection through ingestion, curation, labeling, validation, and preparation. Its output is data suitable for the model pipeline.","focus":["collection","curation","validation"]},{"title":"Iterate on model and system evidence","description":"Read the lower row from right to left: training, evaluation, system validation, then deployment. Model metrics and deployment constraints are different checks.","focus":["train","evaluate","release"]},{"title":"Return discoveries to the data pipeline","description":"The upper curved paths carry data fixes and data needs upstream. Faster model iteration cannot repair missing coverage without collection and curation work.","focus":["datafixes","collection","curation"]}],"artwork_reviewed":true,"art_sha1":"d709d5b16b15f2d9827cbba8fa7c14175e8c9110","art_kind":"svg","art_width":1200,"art_height":450,"art_structural_sha1":"2b91fefdb127ab9667cb5ebeec5b282d0f22f1c1"},"vol1:fig-ml-lifecycle-feedback":{"key":"vol1:fig-ml-lifecycle-feedback","figure_id":"fig-ml-lifecycle-feedback","source":"books/vol1/03_ml_lifecycle/03_ml_lifecycle.qmd","title":"Feedback Paths Across Lifecycle Stages","status":"ready","treatment":"annotated","question":"Which upstream work does each downstream discovery require?","scope":"Return paths motivate investigation and correction, not automatic retraining for every alert.","regions":{"collection":{"x":0.0,"y":0.79,"w":0.19,"h":0.21,"label":"Data collection"},"preparation":{"x":0.0,"y":0.48,"w":0.19,"h":0.2,"label":"Data preparation"},"training":{"x":0.2,"y":0.24,"w":0.2,"h":0.21,"label":"Model training"},"evaluation":{"x":0.44,"y":0.48,"w":0.2,"h":0.2,"label":"Model evaluation"},"deployment":{"x":0.65,"y":0.24,"w":0.19,"h":0.21,"label":"Model deployment"},"monitoring":{"x":0.81,"y":0.48,"w":0.19,"h":0.2,"label":"Monitoring and maintenance"},"gaps":{"x":0.19,"y":0.69,"w":0.37,"h":0.2,"label":"Data-gaps return path"},"quality":{"x":0.05,"y":0.0,"w":0.91,"h":0.22,"label":"Production quality and model-update paths"}},"steps":[{"title":"Use evaluation to locate data gaps","description":"The data-gaps return path sends evaluation discoveries toward collection. More training on unchanged data may leave these coverage gaps intact.","focus":["evaluation","gaps","collection"]},{"title":"Separate validation from deployment constraints","description":"Validation issues return evaluation evidence to training. Deployment constraints also return work to training, but concern the running system rather than only a prediction metric.","focus":["training","evaluation","deployment"]},{"title":"Trace production evidence upstream","description":"Monitoring can motivate data preparation, model updates, or renewed collection. The long return paths make deployment the start of an operating cycle rather than the final handoff.","focus":["monitoring","quality","preparation","collection"]}],"artwork_reviewed":true,"art_sha1":"aaf87756eb6daef3e91445bc7f553512ebdd05cb","art_kind":"svg","art_width":1200,"art_height":503,"art_structural_sha1":"5463bdc17a093e77bd53c47df77c8b705e0fedd7"},"vol1:fig-ml-lifecycle-overview":{"key":"vol1:fig-ml-lifecycle-overview","figure_id":"fig-ml-lifecycle-overview","source":"books/vol1/01_introduction/01_introduction.qmd","title":"ML System Lifecycle","status":"ready","treatment":"annotated","question":"Why do evaluation failure and production degradation lead to different rework?","scope":"A lifecycle schematic; return arrows express decisions rather than fixed iteration durations.","regions":{"data":{"x":0,"y":0,"w":0.27,"h":0.69,"label":"Collection and preparation"},"training":{"x":0.33,"y":0,"w":0.12,"h":0.69,"label":"Training"},"evaluation":{"x":0.5,"y":0,"w":0.12,"h":0.69,"label":"Evaluation"},"production":{"x":0.68,"y":0,"w":0.32,"h":0.69,"label":"Deployment and monitoring"},"evalreturn":{"x":0.21,"y":0.69,"w":0.35,"h":0.17,"label":"Needs improvement return"},"monitorreturn":{"x":0.04,"y":0.85,"w":0.91,"h":0.15,"label":"Performance degrades return"}},"steps":[{"title":"Validate before deployment","description":"Collection and preparation feed model training, followed by evaluation. Only a model meeting requirements advances along the labeled deployment path.","focus":["data","training","evaluation"]},{"title":"Revise a failed candidate","description":"The Needs Improvement arrow returns from evaluation to preparation. Evidence at this gate can require changing data preparation before training again.","focus":["evalreturn"]},{"title":"Use production evidence to revisit the data","description":"Monitoring observes deployed behavior. The longer Performance Degrades return reaches data collection because production problems can require new evidence rather than just another training run.","focus":["production","monitorreturn"]}],"artwork_reviewed":true,"art_sha1":"470f9fcd5376122b1424107bcd8ecb59148dffcc","art_kind":"svg","art_width":1200,"art_height":235,"art_structural_sha1":"5778a21240f6dcc0e13caa66c630898f71acafb7"},"vol1:fig-ml-ops-dlrm-node-day":{"key":"vol1:fig-ml-ops-dlrm-node-day","figure_id":"fig-ml-ops-dlrm-node-day","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"One Ranking Node's Day","status":"ready","treatment":"annotated","question":"Why must rollback capacity be reserved before scheduling retraining and canaries?","scope":"One illustrative eight-accelerator, 24-hour schedule built from the chapter’s worked footprint assumptions.","regions":{"serving":{"x":0.09,"y":0.02,"w":0.88,"h":0.19,"label":"Serving copy on GPU 0–1"},"standby":{"x":0.09,"y":0.22,"w":0.88,"h":0.19,"label":"Hot standby on GPU 2–3"},"training":{"x":0.09,"y":0.43,"w":0.23,"h":0.42,"label":"Six-hour retraining on GPU 4–7"},"canary":{"x":0.32,"y":0.43,"w":0.65,"h":0.21,"label":"Canary after retraining"},"free":{"x":0.32,"y":0.65,"w":0.65,"h":0.2,"label":"Free capacity after retraining"},"time":{"x":0.08,"y":0.87,"w":0.91,"h":0.12,"label":"Hours from retraining start"}},"steps":[{"title":"Reserve the immediate rollback path","description":"The serving copy and hot standby occupy two accelerators each throughout the day. The standby is resident capacity, not free space available to a new job.","focus":["serving","standby"]},{"title":"Fit retraining into the remaining lanes","description":"The four-accelerator retraining job fills GPU 4–7 for six hours. During that interval, another full canary or shadow copy would exceed the shown reserve.","focus":["training","time"]},{"title":"Reuse released capacity deliberately","description":"After retraining finishes, two lanes can host the new candidate as a canary and two become free. Keeping the standby resident preserves the depicted immediate rollback option.","focus":["canary","free","standby"]}],"artwork_reviewed":true,"art_sha1":"5d8b4b9bacb889f016268188979b58e46c5d4a32","art_kind":"png","art_width":3656,"art_height":2099},"vol1:fig-ml-systems-convergence":{"key":"vol1:fig-ml-systems-convergence","figure_id":"fig-ml-systems-convergence","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Convergence of ML Systems","status":"ready","treatment":"annotated","question":"Which systems responsibilities remain when deployment resources change?","scope":"The layers organize common responsibilities; they do not assert identical implementations or budgets at every tier.","regions":{"tiers":{"x":0,"y":0.02,"w":1,"h":0.3,"label":"ML system implementations"},"pipeline":{"x":0.01,"y":0.38,"w":0.24,"h":0.27,"label":"Data pipeline"},"resources":{"x":0.39,"y":0.38,"w":0.24,"h":0.27,"label":"Resource management"},"architecture":{"x":0.76,"y":0.38,"w":0.24,"h":0.27,"label":"System architecture"},"concerns":{"x":0,"y":0.71,"w":1,"h":0.29,"label":"System considerations"}},"steps":[{"title":"Change the deployment envelope","description":"Cloud ML, Edge ML, Mobile ML, and TinyML differ in scale and constraints. None escapes the need to turn observations into reliable decisions.","focus":["tiers"]},{"title":"Preserve the pipeline","description":"Data Pipeline includes collection, processing, and deployment. Moving inference closer to a sensor changes this path, rather than eliminating it.","focus":["pipeline"]},{"title":"Manage resources and architecture","description":"Resource Management includes compute, memory, energy, and network. System Architecture connects models, hardware, and software under those budgets.","focus":["resources","architecture"]},{"title":"Evaluate the running system","description":"Optimization & Efficiency, Operational Aspects, and Trustworthy AI remain across tiers. Their concrete tests must match the chosen deployment envelope.","focus":["concerns"]}],"artwork_reviewed":true,"art_sha1":"1c6b66c701011fbefbbad2a9cb318fda8099139c","art_kind":"svg","art_width":1200,"art_height":1018,"art_structural_sha1":"b5abbf0f64b8868b88afd720f7d849092cbbb98d"},"vol1:fig-mlfm-comp-graph":{"key":"vol1:fig-mlfm-comp-graph","figure_id":"fig-mlfm-comp-graph","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"Computation Graph with System Interactions","status":"ready","treatment":"annotated","question":"How does an operation graph support memory and placement decisions?","scope":"This schematic shows runtime responsibilities; it does not provide measured tensor sizes or a concrete allocation schedule.","regions":{"dag":{"x":0,"y":0,"w":0.42,"h":1,"label":"Operation DAG"},"mem":{"x":0.67,"y":0.13,"w":0.27,"h":0.29,"label":"Memory management"},"device":{"x":0.68,"y":0.46,"w":0.25,"h":0.45,"label":"Device placement"},"link":{"x":0.42,"y":0.39,"w":0.24,"h":0.17,"label":"Graph/runtime interface"}},"steps":[{"title":"Follow dependencies","description":"The six blue operation nodes form a directed graph. An operation waits for the values on its incoming edges, rather than following an arbitrary drawing order.","focus":["dag"]},{"title":"Determine value lifetimes","description":"Memory management uses the graph to identify consumers. Storage becomes reusable only after its last required consumer finishes.","focus":["dag","link","mem"]},{"title":"Choose an execution target","description":"Device placement assigns operations to supported hardware. The explicit graph lets the runtime coordinate those choices with memory ownership.","focus":["link","device"]}],"artwork_reviewed":true,"art_sha1":"4fbcf1dcf8ce89595dac768fea9cccde689e41b2","art_kind":"svg","art_width":1200,"art_height":564,"art_structural_sha1":"fb1357c30fa676cef9a749f4397e8391b40e386a"},"vol1:fig-mlfm-core-ops":{"key":"vol1:fig-mlfm-core-ops","figure_id":"fig-mlfm-core-ops","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"Core Operations Stack","status":"ready","treatment":"annotated","question":"Which responsibilities connect a Python operation to hardware execution?","scope":"These functional tiers are responsibilities, not a guaranteed one-to-one call stack or a latency decomposition.","regions":{"system":{"x":0,"y":0,"w":0.3,"h":1,"label":"System-level operations"},"numeric":{"x":0.33,"y":0,"w":0.3,"h":1,"label":"Basic numerical operations"},"hardware":{"x":0.66,"y":0,"w":0.34,"h":1,"label":"Hardware operations"}},"steps":[{"title":"Coordinate the graph","description":"Scheduling decides when operations can run; memory management tracks storage; resource optimization coordinates the workload. These are system-level decisions.","focus":["system"]},{"title":"Express numerical work","description":"GEMM, BLAS, and element-wise operations supply the numerical building blocks. A high-level tensor call can lower into one or several such routines.","focus":["numeric"]},{"title":"Bind work to the device","description":"Compute Kernel Management, Memory Abstraction, and Execution Control issue work against hardware resources. Efficient arithmetic still depends on data placement and correct scheduling across these tiers.","focus":["hardware","system"]}],"artwork_reviewed":true,"art_sha1":"c303311ac39b343fc2e78620576f5d59d6b7618c","art_kind":"svg","art_width":1200,"art_height":282,"art_structural_sha1":"a1c365b44eb76b01148778d53b13924e4528daf4"},"vol1:fig-mlfm-dynamic-graph-flow":{"key":"vol1:fig-mlfm-dynamic-graph-flow","figure_id":"fig-mlfm-dynamic-graph-flow","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"Dynamic Graph Execution Flow","status":"ready","treatment":"annotated","question":"Why does eager execution expose only one Python call at a time?","scope":"The GPU box denotes dispatch of device work; asynchronous execution does not imply Python waits for kernel completion.","regions":{"define":{"x":0.17,"y":0.17,"w":0.19,"h":0.46,"label":"Python defines an operation"},"execute":{"x":0.4,"y":0.17,"w":0.19,"h":0.46,"label":"Device operation"},"decision":{"x":0.61,"y":0.02,"w":0.22,"h":0.7,"label":"More operations decision"},"loop":{"x":0.25,"y":0.68,"w":0.48,"h":0.3,"label":"Yes return path"}},"steps":[{"title":"Encounter a call","description":"Python reaches Define Operation and asks the framework to issue the corresponding work. This makes the current operation directly inspectable.","focus":["define"]},{"title":"Dispatch device work","description":"The runtime enqueues the GPU operation. The device may execute asynchronously while the host continues; the drawing is not a synchronization barrier.","focus":["execute"]},{"title":"Return for another call","description":"The Yes branch returns to Python for the next operation. That boundary limits visibility into future Python calls and opportunities for optimization across them.","focus":["decision","loop","define"]},{"title":"Finish the sequence","description":"The No branch ends this sequence of calls. Completion of host dispatch and completion of asynchronous device work remain distinct events.","focus":["decision"]}],"artwork_reviewed":true,"art_sha1":"a0776e74cd174674af843e3eb24389b9967d0c68","art_kind":"svg","art_width":1200,"art_height":170,"art_structural_sha1":"3381b78195d525a9d51d97fd0b01ecdaa0374c6c"},"vol1:fig-mlfm-static-graph":{"key":"vol1:fig-mlfm-static-graph","figure_id":"fig-mlfm-static-graph","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"Static Graph Execution Lifecycle","status":"ready","treatment":"annotated","question":"What changes between defining a symbolic graph and executing it?","scope":"The figure describes a static-graph lifecycle, not every modern tracing API or its allocation behavior.","regions":{"define":{"x":0,"y":0.02,"w":0.49,"h":0.96,"label":"Definition phase"},"load":{"x":0.52,"y":0.31,"w":0.13,"h":0.52,"label":"Load data"},"run":{"x":0.68,"y":0.31,"w":0.14,"h":0.52,"label":"Run graph"},"result":{"x":0.84,"y":0.31,"w":0.14,"h":0.52,"label":"Get results"}},"steps":[{"title":"Describe computation","description":"Define Operations, Declare Variables, and Build Graph create the symbolic computation. Concrete inputs have not yet been run through the graph.","focus":["define"]},{"title":"Bind concrete input","description":"Load Data begins execution with actual values. Buffer requirements and target placement now matter in addition to the symbolic dependencies.","focus":["load"]},{"title":"Execute the captured region","description":"Run Graph executes work whose structure was visible in advance. Compilers can exploit that visibility for fusion, buffer reuse, and layout choices.","focus":["run"]},{"title":"Retrieve the result","description":"Get Results exposes the graph output. The two phases trade an upfront definition step for an execution region the runtime can analyze together.","focus":["result"]}],"artwork_reviewed":true,"art_sha1":"10d28f481c04d3da76e39a197b6a2943a45681f9","art_kind":"svg","art_width":1200,"art_height":159,"art_structural_sha1":"f7e3749984d92ed64651d94fbf88990354905c5b"},"vol1:fig-mlops-diagram":{"key":"vol1:fig-mlops-diagram","figure_id":"fig-mlops-diagram","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"Iterative MLOps Loop","status":"ready","treatment":"annotated","question":"How does production become input to the next engineering cycle?","scope":"Three-stage operating abstraction; loop size and arrow spacing do not encode relative time or cost.","regions":{"design":{"x":0.0,"y":0.0,"w":0.36,"h":0.97,"label":"Design loop and responsibilities"},"development":{"x":0.35,"y":0.0,"w":0.31,"h":0.97,"label":"Model-development loop and responsibilities"},"operations":{"x":0.65,"y":0.0,"w":0.35,"h":0.97,"label":"Operations loop and responsibilities"}},"steps":[{"title":"Specify requirements and data feasibility","description":"The design loop includes requirements engineering, use-case prioritization, and data availability. These decisions constrain what development should attempt.","focus":["design"]},{"title":"Build and validate the candidate","description":"The middle loop joins data engineering, model engineering, and model testing and validation. Producing weights is only part of this work.","focus":["development"]},{"title":"Use operation to revise the next cycle","description":"Deployment, CI/CD, monitoring, and triggering occupy the right loop. Their evidence returns through the connected cycle to requirements and development rather than ending at launch.","focus":["operations","design"]}],"artwork_reviewed":true,"art_sha1":"b01f8f21cd8ebb821ab20e920b549230fac4076a","art_kind":"svg","art_width":1200,"art_height":516,"art_structural_sha1":"8bdf4531514f52528782096330768ce262f48e02"},"vol1:fig-mlp":{"key":"vol1:fig-mlp","figure_id":"fig-mlp","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Multilayer Perceptron Architecture","status":"ready","treatment":"annotated","question":"How does one densely connected neuron become a matrix operation?","scope":"The drawn network is schematic; the MNIST dimensions in the caption describe a larger example.","regions":{"network":{"x":0,"y":0,"w":0.28,"h":0.9,"label":"Dense neuron graph"},"input":{"x":0.29,"y":0.25,"w":0.13,"h":0.35,"label":"Input vector"},"weights":{"x":0.45,"y":0.1,"w":0.16,"h":0.68,"label":"Weight matrix and selected column"},"hidden":{"x":0.64,"y":0.25,"w":0.15,"h":0.35,"label":"Hidden activation vector"},"output":{"x":0.82,"y":0.1,"w":0.18,"h":0.7,"label":"Output projection"}},"steps":[{"title":"Every input contributes","description":"The green hidden neuron receives an edge from every input neuron. Each edge carries a learned weight.","focus":["network"]},{"title":"One column produces one activation","description":"The highlighted weight-matrix column collects those incoming weights. Multiplying the input vector by this column forms the corresponding hidden activation before its nonlinearity.","focus":["input","weights","hidden"]},{"title":"Repeat the dense pattern","description":"The next matrix maps hidden activations to output activations. Dense connectivity means arithmetic and weight storage grow with both adjacent layer widths.","focus":["output","hidden"]}],"artwork_reviewed":true,"art_sha1":"4d77922ae21c5cbf920acb4f829bf9f92a8be738","art_kind":"svg","art_width":1200,"art_height":268,"art_structural_sha1":"616767f6d1b56cd2fdcdd4ffbbb690ed40d7d012"},"vol1:fig-mlperf-training-improve":{"key":"vol1:fig-mlperf-training-improve","figure_id":"fig-mlperf-training-improve","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"MLPerf Training Progress","status":"ready","treatment":"annotated","question":"How does benchmark progress differ from transistor scaling alone?","scope":"Workload series retain their benchmark-version normalization and combine hardware and software progress.","regions":{"legend":{"x":0.12,"y":0.84,"w":0.78,"h":0.14,"label":"Workload and Moore baseline legend"},"early":{"x":0.05,"y":0.35,"w":0.38,"h":0.44,"label":"Early benchmark rounds"},"late":{"x":0.66,"y":0.03,"w":0.33,"h":0.67,"label":"Later workload endpoints"},"baseline":{"x":0.58,"y":0.59,"w":0.41,"h":0.21,"label":"Moore cumulative baseline"}},"steps":[{"title":"Identify the comparison","description":"The legend names workloads and the orange Moore’s Law Cumulative reference. Relative performance is normalized; it is not absolute throughput across different tasks.","focus":["legend"]},{"title":"Follow progress by workload","description":"Each series tracks results over successive rounds. Hardware, software, distributed scaling, and implementation changes contribute to the full-system trajectory.","focus":["early","late"]},{"title":"Interpret the gap cautiously","description":"Latest workload points exceed the orange baseline at their corresponding dates. This demonstrates combined system progress beyond that reference, without isolating a single cause such as competition or compiler changes.","focus":["late","baseline"]}],"artwork_reviewed":true,"art_sha1":"4abe5de2110414cf249b625517eb8d2fd74b0761","art_kind":"svg","art_width":1200,"art_height":545,"art_structural_sha1":"ee6a56cfe8e588e88b6786499baf9fea52e2821d"},"vol1:fig-mlsys-playbook-flowchart":{"key":"vol1:fig-mlsys-playbook-flowchart","figure_id":"fig-mlsys-playbook-flowchart","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Deployment Decision Screening","status":"ready","treatment":"annotated","question":"Why must every deployment gate preserve earlier exclusions?","scope":"The figure screens candidate sets; passing gates does not prove complete-path feasibility or task quality.","regions":{"start":{"x":0,"y":0,"w":0.46,"h":0.11,"label":"Candidate set"},"privacy":{"x":0,"y":0.17,"w":1,"h":0.12,"label":"Privacy gate and exclusion"},"latency":{"x":0,"y":0.35,"w":1,"h":0.12,"label":"Latency gate and exclusion"},"resource":{"x":0,"y":0.53,"w":1,"h":0.12,"label":"Resource gate and exclusion"},"cost":{"x":0,"y":0.71,"w":1,"h":0.12,"label":"Cost gate and exclusion"},"remaining":{"x":0,"y":0.89,"w":1,"h":0.11,"label":"Remaining set and redesign path"}},"steps":[{"title":"Begin with candidates","description":"Cloud, edge, mobile, and TinyML enter as a candidate set. The process removes infeasible paths rather than choosing a favorite label first.","focus":["start"]},{"title":"Apply privacy before physical screening","description":"The privacy gate removes forbidden transmission or processing. The latency gate then tests only survivors; it cannot restore a path privacy already excluded.","focus":["privacy","latency"]},{"title":"Require sustainable resources","description":"The resource gate checks memory, sustained compute, and energy. A candidate that lacks capacity cannot be rescued by a favorable purchase price.","focus":["resource"]},{"title":"Compare lifecycle costs","description":"The cost gate compares matched lifecycle budgets for candidates still feasible. Upstream exclusions stay in force.","focus":["cost"]},{"title":"Validate survivors or redesign","description":"Remaining candidates need complete-path and quality validation. If any gate empties the set, redesign or partition the workload rather than silently relaxing a failed requirement.","focus":["remaining"]}],"artwork_reviewed":true,"art_sha1":"f85972d7a2be50ecabf4d540fdf49ecebad27c99","art_kind":"svg","art_width":1200,"art_height":1265,"art_structural_sha1":"3d8b8f36b04129f1a3829a956c18cd525243fca5"},"vol1:fig-mnist-roofline":{"key":"vol1:fig-mnist-roofline","figure_id":"fig-mnist-roofline","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"The Running Network on the Roofline","status":"ready","treatment":"annotated","question":"Why does batching help even when both machines remain bandwidth limited?","scope":"Main-memory traffic roofline model; this small network can instead reside in CPU cache, changing its effective supply bandwidth.","regions":{"cpu":{"x":0.11,"y":0.55,"w":0.51,"h":0.34,"label":"CPU bandwidth slope and batch points"},"accelerator":{"x":0.11,"y":0.22,"w":0.51,"h":0.36,"label":"Accelerator bandwidth slope and batch points"},"ridge":{"x":0.58,"y":0.21,"w":0.05,"h":0.67,"label":"Both approximate FP32 ridges"},"ceilings":{"x":0.61,"y":0.2,"w":0.36,"h":0.3,"label":"Flat compute ceilings"}},"steps":[{"title":"Locate batch-one inference","description":"The two circle markers sit far left on each bandwidth slope. Under the declared traffic model, attainable throughput is limited by the rate at which operands arrive.","focus":["cpu","accelerator"]},{"title":"Amortize each weight fetch","description":"The square batch-32 markers lie farther right: the same weight read serves more examples. Both remain left of the ridges, so reuse raises the bandwidth-bound throughput.","focus":["accelerator","cpu","ridge"]},{"title":"Keep the ceiling distinct from delivery","description":"The flat roofs show peak arithmetic capacity. At these intensities the accelerator’s modeled advantage follows memory bandwidth, while cache residency can change the CPU comparison.","focus":["ceilings","ridge"]}],"artwork_reviewed":true,"art_sha1":"97481bf3a87441e80323c4b6305a88a29f4f8050","art_kind":"png","art_width":3658,"art_height":2454},"vol1:fig-mnist-topology-1":{"key":"vol1:fig-mnist-topology-1","figure_id":"fig-mnist-topology-1","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"MNIST Network Topology","status":"ready","treatment":"annotated","question":"What changes when a digit image is flattened for a dense network?","scope":"Both panels depict the same network; flattening changes representation without introducing a different architecture.","regions":{"image":{"x":0.0,"y":0.27,"w":0.17,"h":0.43,"label":"28×28 image"},"networka":{"x":0.17,"y":0.0,"w":0.24,"h":0.98,"label":"Panel a network"},"vector":{"x":0.65,"y":0,"w":0.06,"h":0.97,"label":"784-element flattened vector"},"networkb":{"x":0.81,"y":0.0,"w":0.19,"h":0.98,"label":"Panel b network"}},"steps":[{"title":"Keep the input values identifiable","description":"Panel a begins with a two-dimensional 28×28 digit. Flattening retains its 784 pixel values while assigning them positions in a one-dimensional vector.","focus":["image","vector"]},{"title":"Use the dense input interface","description":"Panel b explicitly draws the long input vector feeding the same connectivity. A dense layer consumes feature positions rather than directly operating on a two-dimensional neighborhood.","focus":["vector","networkb"]},{"title":"Do not count a new model","description":"The two panels are alternative representations of one network. Flattening does not itself add learned parameters or change hidden widths.","focus":["networka","networkb"]}],"artwork_reviewed":true,"art_sha1":"d513e291f5f4f5f80d1e12f4485dbebfc2e4eee8","art_kind":"svg","art_width":1200,"art_height":606,"art_structural_sha1":"21bf835d8b392cbb381d3728849a33e1cc369b25"},"vol1:fig-mobile-ml":{"key":"vol1:fig-mobile-ml","figure_id":"fig-mobile-ml","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"Mobile ML Constraint Map","status":"ready","treatment":"annotated","question":"Why can a responsive on-device model still be unsustainable?","scope":"The map concerns sustained mobile deployment; battery energy and thermal power limits are distinct constraints.","regions":{"binding":{"x":0.02,"y":0.19,"w":0.18,"h":0.8,"label":"Mobile constraints"},"response":{"x":0.28,"y":0.19,"w":0.17,"h":0.8,"label":"On-device responses"},"boundary":{"x":0.53,"y":0.19,"w":0.2,"h":0.8,"label":"Battery and thermal limits"},"workloads":{"x":0.82,"y":0.19,"w":0.18,"h":0.8,"label":"Mobile workloads"}},"steps":[{"title":"Identify the shared envelope","description":"The phone shares its battery and passive cooling with other functions. Private sensor data and offline use also favor local execution.","focus":["binding"]},{"title":"Use the local accelerator","description":"Run Inference on Device, Use NPU and Fused Kernels, and Compress Model and Activations target useful work per resource consumed.","focus":["response"]},{"title":"Separate energy from heat","description":"Battery Tax spends finite stored energy over time. Thermal Throttling limits sustainable power even when the phone is plugged in. Storage and Memory Limits remain additional checks.","focus":["boundary"]},{"title":"Match the feature workload","description":"Computational Photography, Speech and Translation, Health Monitoring, and Personalization need different invocation rates. A short burst and an always-on feature impose different sustained loads.","focus":["workloads","boundary"]}],"artwork_reviewed":true,"art_sha1":"b4207462c4d77d825a6697dc1d8800979fb1fe8e","art_kind":"svg","art_width":1200,"art_height":433,"art_structural_sha1":"be6328b81f500736b405ea08658cfb9ea900eb27"},"vol1:fig-model-bytes-tiers":{"key":"vol1:fig-model-bytes-tiers","figure_id":"fig-model-bytes-tiers","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Where the Bytes Live","status":"ready","treatment":"annotated","question":"Why can training move a model across a memory-capacity boundary?","scope":"FP32 weights versus weights plus gradients and two Adam buffers, before activation storage; capacity fit does not imply a performance guarantee.","regions":{"mnist":{"x":0.0,"y":0.13,"w":0.4,"h":0.2,"label":"MNIST weights and training-state bars"},"resnet":{"x":0.0,"y":0.38,"w":0.66,"h":0.19,"label":"ResNet-50 state"},"gpt":{"x":0.0,"y":0.62,"w":0.83,"h":0.2,"label":"GPT-2 state"},"sram":{"x":0.16,"y":0.0,"w":0.18,"h":0.85,"label":"Microcontroller SRAM boundary"},"l2":{"x":0.46,"y":0.0,"w":0.19,"h":0.85,"label":"Accelerator L2 boundary"},"hbm":{"x":0.79,"y":0.0,"w":0.19,"h":0.85,"label":"Accelerator HBM boundary"}},"steps":[{"title":"Keep the state recipes explicit","description":"Blue bars contain weights alone. Orange bars add gradients and two Adam buffers, but still exclude activations, so they are not total peak training memory.","focus":["mnist","resnet","gpt"]},{"title":"Find the small-model boundary crossing","description":"MNIST’s weights fit below the microcontroller SRAM line, whereas its training state crosses it. The same parameter count can therefore fit inference but not the training-state recipe.","focus":["mnist","sram"]},{"title":"Read larger footprints against device tiers","description":"ResNet-50 and GPT-2 occupy device memory in both cases. Their training bars claim substantially more capacity; cache or HBM fit alone does not establish execution latency.","focus":["resnet","gpt","l2","hbm"]}],"artwork_reviewed":true,"art_sha1":"2b32ad73f9c063c1d411dfbe4e0dffa4932990cb","art_kind":"png","art_width":3657,"art_height":2046},"vol1:fig-model-parallelism":{"key":"vol1:fig-model-parallelism","figure_id":"fig-model-parallelism","source":"books/vol1/08_training/08_training.qmd","title":"Model Parallelism","status":"ready","treatment":"annotated","question":"How does partitioning model layers change data movement?","scope":"The figure shows layerwise partitioning, not AlexNet’s exact split or an automatically overlapped pipeline.","regions":{"input":{"x":0.0,"y":0.25,"w":0.18,"h":0.49,"label":"Input data"},"first":{"x":0.2,"y":0.25,"w":0.18,"h":0.49,"label":"Layers 1–16"},"second":{"x":0.41,"y":0.25,"w":0.18,"h":0.49,"label":"Layers 17–32"},"third":{"x":0.61,"y":0.25,"w":0.18,"h":0.49,"label":"Layers 33–48"},"forward":{"x":0.04,"y":0.0,"w":0.89,"h":0.2,"label":"Forward activation path"},"backward":{"x":0.04,"y":0.83,"w":0.89,"h":0.17,"label":"Backward gradient path"}},"steps":[{"title":"Distribute the layers","description":"Device 1 holds Layers 1–16, Device 2 holds 17–32, and Device 3 holds 33–48. Each holds a part of the model rather than a full replica.","focus":["first","second","third"]},{"title":"Follow boundary activations","description":"The forward pass moves left to right. A downstream partition needs the preceding partition’s output before it can process this input.","focus":["input","forward"]},{"title":"Return boundary gradients","description":"The backward pass carries gradients in reverse. Aggregate capacity can increase, but sequential dependencies and inter-device transfers remain costs.","focus":["backward"]}],"artwork_reviewed":true,"art_sha1":"0d00c5f3cfe923fbdbd4d72856b8f69341fdbe08","art_kind":"svg","art_width":1200,"art_height":197,"art_structural_sha1":"f1662a4ca58edab8b1ac906b63df5b91bb69d578"},"vol1:fig-model-serving-request-timeline":{"key":"vol1:fig-model-serving-request-timeline","figure_id":"fig-model-serving-request-timeline","source":"books/vol1/13_model_serving/13_model_serving.qmd","title":"One Request on One Node","status":"ready","treatment":"annotated","question":"How much of one request is actually spent on the accelerator?","scope":"Reference single ResNet-50 request; network, serialization, and batching delay are excluded.","regions":{"cpu":{"x":0.12,"y":0.1,"w":0.44,"h":0.24,"label":"CPU decode resize normalize"},"pcie":{"x":0.55,"y":0.37,"w":0.09,"h":0.2,"label":"PCIe input copy"},"gpu":{"x":0.6,"y":0.64,"w":0.35,"h":0.16,"label":"GPU forward pass"},"idle":{"x":0.12,"y":0.64,"w":0.49,"h":0.16,"label":"Accelerator idle while input is prepared"},"post":{"x":0.72,"y":0.1,"w":0.25,"h":0.23,"label":"CPU postprocessing"}},"steps":[{"title":"Prepare the input on the host","description":"JPEG decoding, resizing, and normalization occupy the CPU before the device can run. The GPU remains idle during this preparation interval.","focus":["cpu","idle"]},{"title":"Transfer before compute","description":"The input crosses PCIe after host preparation. The ResNet-50 forward pass begins only after that dependent copy completes.","focus":["pcie","gpu"]},{"title":"Finish the request beyond the GPU bar","description":"Softmax and top-5 selection return to the host. Accelerator busy time is therefore only part of the request’s displayed latency budget.","focus":["post","gpu"]}],"artwork_reviewed":true,"art_sha1":"bd894c52e0830b2a3410a1bc1a6f1037a77a0ede","art_kind":"png","art_width":3657,"art_height":2100},"vol1:fig-model-vs-data":{"key":"vol1:fig-model-vs-data","figure_id":"fig-model-vs-data","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Development Paradigms","status":"ready","treatment":"annotated","question":"What stays fixed in model-centric and data-centric iteration?","scope":"These are complementary development strategies; neither guarantees improved quality or lower computation.","regions":{"modeldata":{"x":0.0,"y":0.31,"w":0.14,"h":0.65,"label":"Locked data in model-centric AI"},"modeliterate":{"x":0.22,"y":0.23,"w":0.18,"h":0.72,"label":"Model feedback loop"},"dataloop":{"x":0.63,"y":0.23,"w":0.16,"h":0.72,"label":"Data feedback loop"},"lockedmodel":{"x":0.83,"y":0.3,"w":0.17,"h":0.65,"label":"Locked architecture in data-centric AI"},"complement":{"x":0.42,"y":0.4,"w":0.18,"h":0.3,"label":"Complementary strategies"}},"steps":[{"title":"Fix data and iterate on the model","description":"The left padlock sits on Data while the feedback path returns to Model. Holding the dataset fixed helps compare model changes against a stable input.","focus":["modeldata","modeliterate"]},{"title":"Fix architecture and improve data","description":"The right padlock sits on Model while the feedback loop returns to Data. Annotation quality, diversity, and bias become explicit intervention targets.","focus":["dataloop","lockedmodel"]},{"title":"Combine controlled experiments","description":"The double arrow marks the strategies as Complementary. Vary one side deliberately, evaluate against the same requirements, and record which change produced the observed effect.","focus":["complement"]}],"artwork_reviewed":true,"art_sha1":"958350d3ce4f7061901d78b48b296ba34228dc21","art_kind":"svg","art_width":1200,"art_height":265,"art_structural_sha1":"f99ea8be42d5a1c8b9f101aea26f4f7c6bab4e5f"},"vol1:fig-mswc":{"key":"vol1:fig-mswc","figure_id":"fig-mswc","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Multilingual Data Preparation","status":"ready","treatment":"annotated","question":"How do paired recordings and transcripts become keyword examples?","scope":"Forced alignment estimates word boundaries; large-scale extraction still requires quality and provenance checks.","regions":{"input":{"x":0.0,"y":0.0,"w":0.21,"h":0.45,"label":"Paired input"},"align":{"x":0.26,"y":0.0,"w":0.21,"h":0.45,"label":"Forced alignment"},"extract":{"x":0.52,"y":0.0,"w":0.21,"h":0.45,"label":"Keyword extraction"},"train":{"x":0.79,"y":0.0,"w":0.21,"h":0.45,"label":"KWS training"},"timing":{"x":0.01,"y":0.49,"w":0.36,"h":0.45,"label":"Per-word timing"},"words":{"x":0.4,"y":0.49,"w":0.43,"h":0.45,"label":"Extracted keywords"},"corpus":{"x":0.86,"y":0.5,"w":0.13,"h":0.41,"label":"MSWC corpus"}},"steps":[{"title":"Start with paired evidence","description":"Input Data pairs each sentence transcript with an audio recording. The transcript supplies candidate words; audio supplies the acoustic examples.","focus":["input"]},{"title":"Estimate boundaries","description":"Forced Alignment locates transcript words within a waveform. The lower-left expansion shows per-word timing rather than a new manual annotation for every clip.","focus":["align","timing"]},{"title":"Extract labeled windows","description":"Extract Keyword Samples cuts a one-second window for a word such as bank. The lower strip shows the resulting vocabulary-specific audio fragments.","focus":["extract","words"]},{"title":"Build and validate the corpus","description":"The corpus feeds the KWS model, including keyword and noise examples. Automation increases scale but does not establish accent coverage or alignment correctness by itself.","focus":["corpus","train"]}],"artwork_reviewed":true,"art_sha1":"03997b5d6d9cd4226b25f0bc4601172973b765e6","art_kind":"png","art_width":2846,"art_height":1232},"vol1:fig-nas-flow":{"key":"vol1:fig-nas-flow","figure_id":"fig-nas-flow","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Neural Architecture Search Flow","status":"ready","treatment":"annotated","question":"How does architecture search use evaluation feedback?","scope":"Search quality depends on its defined space, estimator, and resource bounds. The feedback loop does not guarantee a globally optimal architecture.","regions":{"space":{"x":0,"y":0.34,"w":0.15,"h":0.65,"label":"Search space"},"strategy":{"x":0.4,"y":0.31,"w":0.15,"h":0.68,"label":"Search strategy"},"proposal":{"x":0.55,"y":0.33,"w":0.24,"h":0.22,"label":"Candidate architecture path"},"estimate":{"x":0.79,"y":0.27,"w":0.2,"h":0.72,"label":"Performance estimation"},"feedback":{"x":0.55,"y":0.57,"w":0.24,"h":0.23,"label":"Performance feedback"}},"steps":[{"title":"Define the allowable designs","description":"Search Space determines which architectures can be proposed. A useful hardware-efficient design outside this space cannot be discovered by the loop.","focus":["space"]},{"title":"Propose a candidate","description":"Search Strategy selects an architecture from that space and sends it to evaluation. The proposal is a model structure, not an already validated deployment.","focus":["strategy","proposal"]},{"title":"Evaluate the target requirements","description":"Performance Estimation assesses candidate quality and relevant hardware constraints. Measured or estimated latency can differ from a simple FLOP count.","focus":["estimate"]},{"title":"Use feedback for the next proposal","description":"The return arrow carries the performance estimate to the strategy. Search spends evaluation resources to steer later candidates toward the desired trade-off.","focus":["feedback","strategy"]}],"artwork_reviewed":true,"art_sha1":"3cadff748d7c05c67e00664682df82f840750fd7","art_kind":"svg","art_width":1200,"art_height":285,"art_structural_sha1":"c344c085b644b1b84a616932a4918084f8f354bc"},"vol1:fig-neuron-to-machine":{"key":"vol1:fig-neuron-to-machine","figure_id":"fig-neuron-to-machine","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"From Neuron to Machine","status":"ready","treatment":"annotated","question":"How does a neuron dot product become a reusable hardware workload?","scope":"Schematic matrix mapping; the array is illustrative and does not imply perfect utilization or one fixed accelerator dataflow.","regions":{"neuron":{"x":0.0,"y":0.0,"w":0.28,"h":0.95,"label":"One neuron: row-column dot product"},"batch":{"x":0.37,"y":0.0,"w":0.3,"h":0.95,"label":"One layer and one batch"},"machine":{"x":0.72,"y":0.0,"w":0.28,"h":0.98,"label":"Weight tile and streaming input rows"}},"steps":[{"title":"Count work for one output","description":"An input row meets one weight column to form a dot product. Each output requires the products and accumulation over the input width.","focus":["neuron"]},{"title":"Stack outputs and examples","description":"A batch matrix X multiplies the layer’s weight matrix W to produce Z. Batch size, input width, and output width jointly set the multiply-accumulate count.","focus":["batch"]},{"title":"Reuse the fetched weight tile","description":"The right-hand array holds a weight tile while rows of X stream through. Batching lets each fetched weight serve more examples, provided the implementation captures the reuse.","focus":["machine"]}],"artwork_reviewed":true,"art_sha1":"bed476162a9649b4d91892f7955f54eb418c6a3b","art_kind":"svg","art_width":1200,"art_height":383,"art_structural_sha1":"bed114443ecba1ad4c13b5e6298b3a0063b6e525"},"vol1:fig-nonlinear":{"key":"vol1:fig-nonlinear","figure_id":"fig-nonlinear","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Linear vs. Nonlinear Decision Boundaries","status":"ready","treatment":"annotated","question":"What changes when a network includes nonlinear activations?","scope":"Illustrative representational comparison on fixed points, not a guarantee that optimization discovers the curved partition.","regions":{"linear":{"x":0.0,"y":0.0,"w":0.44,"h":0.98,"label":"Network without activation"},"nonlinear":{"x":0.55,"y":0.0,"w":0.45,"h":0.98,"label":"Network with activation"},"line":{"x":0.0,"y":0.13,"w":0.44,"h":0.68,"label":"Straight decision boundary"},"curve":{"x":0.57,"y":0.32,"w":0.41,"h":0.44,"label":"Curved decision boundary"}},"steps":[{"title":"Hold the data fixed","description":"Both panels contain the same point configuration. The comparison changes the representable decision boundary rather than replacing the dataset.","focus":["linear","nonlinear"]},{"title":"Inspect the linear restriction","description":"Without nonlinear activations, stacked linear transformations collapse into one linear transformation. The straight boundary cannot follow the curved class separation.","focus":["line"]},{"title":"Inspect the nonlinear capability","description":"Activations permit curved decision regions. This expanded function class introduces a possibility, while data coverage and training still determine the learned result.","focus":["curve"]}],"artwork_reviewed":true,"art_sha1":"5a9d48413862d2cac00ef62fc4022efecdf29a29","art_kind":"svg","art_width":1200,"art_height":499,"art_structural_sha1":"2cd30634252e616e27dc334ca4984eae9549336b"},"vol1:fig-oneshot-pruning":{"key":"vol1:fig-oneshot-pruning","figure_id":"fig-oneshot-pruning","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Illustrative One-Shot Pruning Impact","status":"ready","treatment":"annotated","question":"What happens when the selected channels are removed in one cut?","scope":"The illustrated recovery procedure differs from the iterative example; the comparison does not isolate schedule independently of training budget.","regions":{"network":{"x":0,"y":0.09,"w":0.45,"h":0.91,"label":"Initial network and selected channels"},"drop":{"x":0.52,"y":0.27,"w":0.12,"h":0.56,"label":"Post-prune accuracy"},"finetune":{"x":0.72,"y":0.27,"w":0.12,"h":0.56,"label":"Fine-tune new structure"},"final":{"x":0.88,"y":0.27,"w":0.12,"h":0.56,"label":"Recovered accuracy"}},"steps":[{"title":"Remove all selected channels","description":"The red slices are removed together from the network starting at 0.995 accuracy. One-shot pruning changes the structure before any recovery stage.","focus":["network"]},{"title":"Measure the immediate loss","description":"The first Test Accuracy box reports 0.914 after the cut. This is the effect before the shown fine-tuning procedure has compensated.","focus":["drop"]},{"title":"Allow recovery training","description":"Fine-tuning operates on the new structure. Its cost and effectiveness depend on the recovery budget and task.","focus":["finetune"]},{"title":"Inspect the remaining gap","description":"The final box reaches 0.943 rather than the starting 0.995. This illustrative outcome motivates validation rather than guaranteeing one schedule always wins.","focus":["final","network"]}],"artwork_reviewed":true,"art_sha1":"5d76137b8bfc85c0ccde1e1769c17547030c8137","art_kind":"svg","art_width":1200,"art_height":284,"art_structural_sha1":"c84fef65dfa6ff13c4dac9d7ff5ab9ce6ae6b6be"},"vol1:fig-onnx":{"key":"vol1:fig-onnx","figure_id":"fig-onnx","source":"books/vol1/13_model_serving/13_model_serving.qmd","title":"Framework Interoperability","status":"ready","treatment":"annotated","question":"What must be compatible on both sides of an ONNX artifact?","scope":"Historical framework interoperability schematic; logos do not guarantee current exporter, operator, or runtime support.","regions":{"export":{"x":0,"y":0.05,"w":0.43,"h":0.94,"label":"Framework exports"},"artifact":{"x":0.33,"y":0.32,"w":0.3,"h":0.18,"label":"Shared ONNX representation"},"load":{"x":0.6,"y":0.05,"w":0.4,"h":0.94,"label":"Runtime and framework loads"}},"steps":[{"title":"Export a model representation","description":"Inward spokes carry models from source frameworks into ONNX. Export must represent the operations and relevant semantics used by the model.","focus":["export","artifact"]},{"title":"Keep the artifact boundary explicit","description":"The central ONNX label denotes a shared representation, not an execution device or an automatic optimizer. A serialized graph still needs compatible consumers.","focus":["artifact"]},{"title":"Check the destination support","description":"Outward spokes denote loading into tools or runtimes. Successful portability requires operator and semantic support at both export and load boundaries.","focus":["load"]}],"artwork_reviewed":true,"art_sha1":"96bd3aa801e3edb1bf7611ef22d468ee64050e61","art_kind":"jpg","art_width":1522,"art_height":1343},"vol1:fig-operator-surface":{"key":"vol1:fig-operator-surface","figure_id":"fig-operator-surface","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"Eager Operator Surfaces versus Compiler Cores","status":"ready","treatment":"annotated","question":"Why can a small compiler core support a much larger eager API?","scope":"Counts use the printed definitions and releases; schemas, primitives, and registered operators are not identical measures.","regions":{"legend":{"x":0.02,"y":0,"w":0.96,"h":0.18,"label":"Count definitions"},"eager":{"x":0.11,"y":0.27,"w":0.79,"h":0.27,"label":"Large eager surfaces"},"core":{"x":0.18,"y":0.68,"w":0.72,"h":0.16,"label":"Compiler-facing sets"},"dates":{"x":0.09,"y":0.9,"w":0.9,"h":0.1,"label":"Release dates"}},"steps":[{"title":"Check what is counted","description":"The legend distinguishes PyTorch schemas including overloads, TensorFlow registered operators, and compiler-facing operation sets. Their counts describe different interfaces.","focus":["legend"]},{"title":"Inspect the eager surface","description":"The upper curves show the large and growing operator vocabularies exposed to users. Supporting each public spelling directly would make a backend expensive to implement.","focus":["eager"]},{"title":"Locate the smaller target","description":"The lower curves show Core ATen, XLA, ONNX, and JAX primitives. Decomposition and lowering express richer APIs using smaller vocabularies.","focus":["core"]},{"title":"Read this as dated evidence","description":"The horizontal axis is release date. These observations motivate a coverage argument; the plot does not measure execution speed or prove that all operators lower without exceptions.","focus":["dates","eager","core"]}],"artwork_reviewed":true,"art_sha1":"657be2f0b994ad314b2e94a0df364cea1b0bda90","art_kind":"png","art_width":3516,"art_height":2883},"vol1:fig-ops-cicd":{"key":"vol1:fig-ops-cicd","figure_id":"fig-ops-cicd","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"ML CI/CD Pipeline","status":"ready","treatment":"annotated","question":"Which evidence and artifacts must survive a continuous-training run?","scope":"Illustrative pipeline adapted from the cited guidance; registration is not an unconditional production rollout.","regions":{"input":{"x":0.0,"y":0.36,"w":0.2,"h":0.35,"label":"Dataset and feature repository"},"prepare":{"x":0.23,"y":0.47,"w":0.11,"h":0.31,"label":"Ingestion and data validation"},"transform":{"x":0.37,"y":0.66,"w":0.11,"h":0.12,"label":"Data transformation"},"train":{"x":0.37,"y":0.47,"w":0.11,"h":0.11,"label":"Model training and tuning"},"evaluate":{"x":0.52,"y":0.47,"w":0.11,"h":0.31,"label":"Model evaluation and validation"},"register":{"x":0.66,"y":0.66,"w":0.11,"h":0.12,"label":"Model registration"},"repository":{"x":0.81,"y":0.37,"w":0.19,"h":0.33,"label":"Trained-model repository"},"metadata":{"x":0.45,"y":0.0,"w":0.21,"h":0.36,"label":"Metadata and artifact repository"}},"steps":[{"title":"Ingest and validate the data","description":"The dataset repository feeds ingestion, then data validation. Transformation prepares the validated input for training rather than bypassing a data-quality gate.","focus":["input","prepare","transform"]},{"title":"Train, then test the candidate","description":"Training and tuning produce a candidate for model evaluation and validation. These stages are separate evidence gates before registration.","focus":["train","evaluate"]},{"title":"Preserve the reproducible result","description":"Registration leads to the model repository, while metadata and artifacts are recorded above the pipeline. Reproducing a run requires these records alongside weights and the dataset.","focus":["register","repository","metadata"]}],"artwork_reviewed":true,"art_sha1":"71c51eae18a13ec1db1fdc703ef9436dfa504e78","art_kind":"svg","art_width":1200,"art_height":495,"art_structural_sha1":"ca52de8f9a83db7747479fb4f1baccf764123fde"},"vol1:fig-ops-layers":{"key":"vol1:fig-ops-layers","figure_id":"fig-ops-layers","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"MLOps Stack Layers","status":"ready","treatment":"annotated","question":"Where does MLOps bridge model software and physical execution?","scope":"Five implementation columns; these are stack positions rather than an organizational ownership chart.","regions":{"applications":{"x":0.0,"y":0.04,"w":0.19,"h":0.12,"label":"Models and applications"},"frameworks":{"x":0.2,"y":0.04,"w":0.21,"h":0.12,"label":"Frameworks and platforms"},"orchestration":{"x":0.44,"y":0.04,"w":0.18,"h":0.95,"label":"Model orchestration tasks"},"infrastructure":{"x":0.63,"y":0.04,"w":0.2,"h":0.65,"label":"Infrastructure tasks"},"hardware":{"x":0.85,"y":0.04,"w":0.15,"h":0.12,"label":"Hardware"},"boundary":{"x":0.42,"y":0.0,"w":0.42,"h":0.99,"label":"MLOps span"}},"steps":[{"title":"Locate the stack interfaces","description":"Models and frameworks appear to the left, hardware to the right. The middle tiers translate model intent into reproducible execution on available machines.","focus":["applications","frameworks","hardware"]},{"title":"Follow model orchestration responsibilities","description":"Data management, CI/CD, training, evaluation, deployment, and serving are grouped in the orchestration column. They connect artifacts and pipeline stages across a model’s lifecycle.","focus":["orchestration"]},{"title":"Supply the execution substrate","description":"Job scheduling, resource management, capacity management, and monitoring occupy infrastructure. MLOps spans both middle columns because model workflows and machine state must be coordinated.","focus":["infrastructure","boundary"]}],"artwork_reviewed":true,"art_sha1":"ebc13bbcdf7a1146b68adaf80b4f2b31707b87f8","art_kind":"svg","art_width":1200,"art_height":636,"art_structural_sha1":"18895975776a6bcb83bb5f43b920eb0d7729f867"},"vol1:fig-optimization-flowchart":{"key":"vol1:fig-optimization-flowchart","figure_id":"fig-optimization-flowchart","source":"books/vol1/08_training/08_training.qmd","title":"Training Optimization Decision Flowchart","status":"ready","treatment":"annotated","question":"How should profile signals guide the next training experiment?","scope":"The 70 percent and 90 percent thresholds are illustrative triage values, not definitions of resource bounds.","regions":{"start":{"x":0.39,"y":0.0,"w":0.25,"h":0.1,"label":"Profile training run"},"activity":{"x":0.38,"y":0.15,"w":0.28,"h":0.21,"label":"Accelerator activity check"},"idle":{"x":0.02,"y":0.19,"w":0.25,"h":0.3,"label":"Idle-gap investigation"},"capacity":{"x":0.02,"y":0.55,"w":0.64,"h":0.22,"label":"Capacity-pressure check"},"memory":{"x":0.02,"y":0.73,"w":0.25,"h":0.15,"label":"Memory-saving candidates"},"kernels":{"x":0.78,"y":0.55,"w":0.22,"h":0.32,"label":"Kernel-limit investigation"},"reprofile":{"x":0.39,"y":0.9,"w":0.25,"h":0.1,"label":"Re-profile and iterate"}},"steps":[{"title":"Start from a trace","description":"Profile Training Run leads to an illustrative accelerator-activity check. Low activity calls for tracing input, host work, and synchronization rather than immediately naming a unique cause.","focus":["start","activity","idle"]},{"title":"Test capacity pressure","description":"OOM errors or high allocated memory motivate capacity investigation. Mixed precision, checkpointing, and accumulation are candidates with different arithmetic and memory costs.","focus":["capacity","memory"]},{"title":"Inspect kernel limits","description":"If idle gaps and capacity do not explain the result, profile bandwidth, arithmetic, and launch limits. Every branch returns to Re-profile & Iterate to verify the intervention.","focus":["kernels","reprofile"]}],"artwork_reviewed":true,"art_sha1":"14c4a1e48b430e225a7a091f5e0a90011193c82d","art_kind":"svg","art_width":1200,"art_height":719,"art_structural_sha1":"f180862d2529ab7d1028ec7b66276de72793716b"},"vol1:fig-optimization-stack":{"key":"vol1:fig-optimization-stack","figure_id":"fig-optimization-stack","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"The Optimization Stack","status":"ready","treatment":"annotated","question":"Which artifacts change as an optimization travels toward deployment?","scope":"Artifact-flow schematic; less training data does not imply smaller model weights or cheaper serving.","regions":{"data":{"x":0,"y":0,"w":0.6,"h":0.34,"label":"Raw selection and curated data"},"training":{"x":0.62,"y":0,"w":0.38,"h":0.64,"label":"Training and resulting model"},"compression":{"x":0.43,"y":0.64,"w":0.39,"h":0.36,"label":"Compression and compact model"},"deployment":{"x":0,"y":0.64,"w":0.37,"h":0.36,"label":"Hardware and deployed system"}},"steps":[{"title":"Change the training input first","description":"Raw data passes through selection into a curated artifact. This intervention changes what training consumes and can change quality as well as cost.","focus":["data"]},{"title":"Separate data savings from model compression","description":"Training emits a model; compression produces a compact model later. Reducing examples upstream does not automatically reduce the resulting parameter count.","focus":["training","compression"]},{"title":"Measure the deployment consequence","description":"Hardware executes the compact model to form a deployed system. Quality, latency, and resource effects must be checked across these artifact boundaries rather than inferred from one smaller dataset.","focus":["deployment"]}],"artwork_reviewed":true,"art_sha1":"5c3173cb5f136dcc11f9472215fca151a3141b8f","art_kind":"svg","art_width":1200,"art_height":404,"art_structural_sha1":"1f6656694a511db324854e9ea3247e0e962c59f1"},"vol1:fig-parameter-growth":{"key":"vol1:fig-parameter-growth","figure_id":"fig-parameter-growth","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Parameter Counts of Notable Models, 1950 to the Present","status":"ready","treatment":"annotated","question":"What does historical parameter growth tell us about system state?","scope":"Notable-model observations and least-squares fits, not a representative sample of all models or a causal forecast.","regions":{"early":{"x":0.06,"y":0.56,"w":0.4,"h":0.38,"label":"Pre-2010 observations and fitted trend"},"late":{"x":0.47,"y":0.05,"w":0.44,"h":0.7,"label":"Post-2010 observations and fitted trend"},"legend":{"x":0.08,"y":0.02,"w":0.24,"h":0.23,"label":"Domain-color legend"},"running":{"x":0.0,"y":0.59,"w":0.45,"h":0.07,"label":"Running MNIST reference"}},"steps":[{"title":"Read the logarithmic parameter axis","description":"Each point is one notable model at its publication date. The legend distinguishes domains; point counts and vertical height do not directly measure deployment popularity.","focus":["legend","early"]},{"title":"Compare the two historical fits","description":"The later segment is steeper than the earlier one. These descriptive fits summarize selected historical observations rather than promising a future doubling schedule.","focus":["early","late"]},{"title":"Translate size into state obligations","description":"The MNIST reference shows the small running example on the same scale. Larger dense parameter counts multiply weight storage and, during training, gradient and optimizer state.","focus":["running","late"]}],"artwork_reviewed":true,"art_sha1":"570388b7f714ae835199e762019dfc1be43c5370","art_kind":"png","art_width":3417,"art_height":2449},"vol1:fig-perceptron":{"key":"vol1:fig-perceptron","figure_id":"fig-perceptron","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Perceptron Architecture","status":"ready","treatment":"annotated","question":"What repeated work produces one neuron output?","scope":"Symbolic per-neuron computation; no particular trained weights or numerical prediction are implied.","regions":{"inputs":{"x":0.0,"y":0.01,"w":0.16,"h":0.95,"label":"Input components"},"weights":{"x":0.2,"y":0.02,"w":0.16,"h":0.96,"label":"Per-input weights"},"sum":{"x":0.43,"y":0.31,"w":0.18,"h":0.33,"label":"Summation node"},"bias":{"x":0.47,"y":0.63,"w":0.15,"h":0.21,"label":"Bias input"},"activation":{"x":0.69,"y":0.31,"w":0.13,"h":0.51,"label":"Activation function"},"output":{"x":0.87,"y":0.36,"w":0.13,"h":0.24,"label":"Output"}},"steps":[{"title":"Multiply each input by its weight","description":"Each left-hand component has its own weighted path. These products are the work repeated across all neurons in a dense layer.","focus":["inputs","weights"]},{"title":"Accumulate before activation","description":"The weighted products meet at the summation node and the bias shifts the preactivation. Adding the bias is distinct from changing an individual input weight.","focus":["sum","bias"]},{"title":"Transform the scalar result","description":"The activation receives the accumulated score and emits the neuron output. A layer evaluates many such outputs with different parameter columns.","focus":["activation","output"]}],"artwork_reviewed":true,"art_sha1":"52de601f0df03b9dad83827b7702be2ed6bddcab","art_kind":"svg","art_width":1200,"art_height":693,"art_structural_sha1":"3b5e80017aa6f11a1e1957d9f93a1e0ebdccac8f"},"vol1:fig-pipeline-flow":{"key":"vol1:fig-pipeline-flow","figure_id":"fig-pipeline-flow","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"End-to-End Data Pipeline","status":"ready","treatment":"annotated","question":"How does the pipeline separate ingestion from iterative dataset preparation?","scope":"This is the offline model-building pipeline, not the smart speaker’s live audio path.","regions":{"sources":{"x":0.02,"y":0.05,"w":0.95,"h":0.15,"label":"Source layer"},"ingest":{"x":0.08,"y":0.23,"w":0.85,"h":0.15,"label":"Ingestion layer"},"storage":{"x":0.39,"y":0.4,"w":0.26,"h":0.08,"label":"Storage layer"},"training":{"x":0.04,"y":0.52,"w":0.39,"h":0.29,"label":"ML training branch"},"processing":{"x":0.59,"y":0.52,"w":0.38,"h":0.48,"label":"Processing and labeling loop"},"governance":{"x":0.0,"y":0.0,"w":1,"h":0.05,"label":"Governance boundary"}},"steps":[{"title":"Normalize arrivals","description":"Raw Data Sources, External APIs, and Streaming Sources enter batch or stream ingestion. These heterogeneous arrivals must be checked before downstream use.","focus":["sources","ingest"]},{"title":"Use a persistent boundary","description":"The Storage Layer decouples arrival from later processing. Stored records can feed training and transformation without requiring the original sources to replay every iteration.","focus":["storage"]},{"title":"Close the preparation loop","description":"Validation, transformation, feature engineering, and labeling feed back toward storage. The separate ML Training branch consumes the prepared training data.","focus":["processing","training"]},{"title":"Maintain the perimeter","description":"Data Governance bounds all stages, including stored and relabeled records. Retention and access decisions therefore apply across the pipeline rather than only at acquisition.","focus":["governance"]}],"artwork_reviewed":true,"art_sha1":"56c9a4712a3cf197fe83a16031e99456a7fe8301","art_kind":"svg","art_width":1200,"art_height":1111,"art_structural_sha1":"d197467a97e419308aea14a52c0046149b637455"},"vol1:fig-power-diagram":{"key":"vol1:fig-power-diagram","figure_id":"fig-power-diagram","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Power Measurement Boundaries","status":"ready","treatment":"annotated","question":"Which components are included in each reported power boundary?","scope":"Use the sourced enclosures exactly; node or rack power does not mean whole-data-center energy.","regions":{"tiny":{"x":0.0,"y":0.02,"w":0.16,"h":0.58,"label":"Tiny SoC boundary"},"soc":{"x":0.2,"y":0.02,"w":0.22,"h":0.93,"label":"Inference SoC boundary"},"node":{"x":0.48,"y":0.02,"w":0.19,"h":0.94,"label":"Inference node boundary"},"remote":{"x":0.44,"y":0.08,"w":0.025,"h":0.79,"label":"Excluded remote storage"},"rack":{"x":0.71,"y":0.02,"w":0.19,"h":0.94,"label":"Training rack boundary"},"excluded":{"x":0.73,"y":0.5,"w":0.15,"h":0.4,"label":"Excluded storage and cooling"},"key":{"x":0.0,"y":0.64,"w":0.18,"h":0.32,"label":"Boundary key"}},"steps":[{"title":"Read the enclosure convention","description":"The key distinguishes a solid Power Measurement Boundary from dashed Not in Boundary elements. Tiny encloses its compute, switch, and on-chip SRAM.","focus":["key","tiny"]},{"title":"Inspect inference scope","description":"The SoC example includes off-chip DRAM; the node example includes host resources, accelerator memory, and active cooling. Dashed Remote Storage remains outside the measured node boundary.","focus":["soc","node","remote"]},{"title":"Keep rack exclusions visible","description":"Training racks include measured compute nodes and indicated networking. Dashed Storage Node and DC Cooling Components are excluded, so rack results cannot be read as total facility energy.","focus":["rack","excluded"]}],"artwork_reviewed":true,"art_sha1":"11bbb6c7a275db8cb07f6fc2d360fad97562b903","art_kind":"svg","art_width":1200,"art_height":271,"art_structural_sha1":"22eb142fd0e449161ba2176c494a89013e72b9a7"},"vol1:fig-power-differentials":{"key":"vol1:fig-power-differentials","figure_id":"fig-power-differentials","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Power Consumption Differentials","status":"ready","treatment":"annotated","question":"Why must a power benchmark match its deployment division?","scope":"Pairs are official-submission minima and maxima, not typical-device ranges or probability intervals.","regions":{"tiny":{"x":0.14,"y":0.6,"w":0.1,"h":0.34,"label":"Tiny submission range"},"edge":{"x":0.38,"y":0.27,"w":0.1,"h":0.35,"label":"Edge submission range"},"dc":{"x":0.62,"y":0.18,"w":0.1,"h":0.23,"label":"Data-center submission range"},"training":{"x":0.86,"y":0.0,"w":0.1,"h":0.29,"label":"Training submission range"},"legend":{"x":0.15,"y":0.02,"w":0.27,"h":0.16,"label":"Minimum and maximum key"}},"steps":[{"title":"Read the extrema","description":"Blue marks minimum and red maximum submission power. The logarithmic axis makes vertical distance a ratio, not a difference in watts.","focus":["legend","tiny"]},{"title":"Match the operating scale","description":"Tiny, Edge, and Data center spans occupy very different power scales. A battery-powered keyword spotter and a server node answer to different constraints and measurement boundaries.","focus":["tiny","edge","dc"]},{"title":"Avoid a universal efficiency ranking","description":"Training submissions reach a much larger system scale. Comparing watts alone across these divisions omits workload output and scope, so it cannot establish which system is more efficient.","focus":["training"]}],"artwork_reviewed":true,"art_sha1":"5649e6cdfac41c112d82132149ffcb77d13c0022","art_kind":"png","art_width":3365,"art_height":2321},"vol1:fig-power-trends":{"key":"vol1:fig-power-trends","figure_id":"fig-power-trends","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Data-Center Energy Efficiency Gains","status":"ready","treatment":"annotated","question":"What can normalized efficiency curves legitimately compare?","scope":"Each workload is normalized to its own first plotted version; heights do not rank absolute samples per joule.","regions":{"early":{"x":0.08,"y":0.05,"w":0.36,"h":0.84,"label":"Early workload trajectories"},"late":{"x":0.64,"y":0.05,"w":0.34,"h":0.84,"label":"Later workload trajectories"},"legend":{"x":0.09,"y":0.06,"w":0.16,"h":0.38,"label":"Workload legend"},"axis":{"x":0.09,"y":0.86,"w":0.89,"h":0.14,"label":"Version axis"}},"steps":[{"title":"Identify the normalization","description":"The vertical axis is normalized energy efficiency. Use the legend to identify workloads before comparing improvement relative to each workload’s own starting result.","focus":["legend","early"]},{"title":"Compare progress within a workload","description":"RetinaNet and ResNet rise toward three times their own initial values. This reports relative progress, not equal absolute efficiency at the endpoint.","focus":["late"]},{"title":"Respect different starting versions","description":"GPT-J, DLRM-v2, and Llama 2 begin later on the version axis. Their baselines occur at different dates, so the curves cover different improvement windows.","focus":["axis","late"]}],"artwork_reviewed":true,"art_sha1":"1f711996954eb1e5a4c9abcb479bc397f3fd09ab","art_kind":"png","art_width":2250,"art_height":1035},"vol1:fig-ppd-curve":{"key":"vol1:fig-ppd-curve","figure_id":"fig-ppd-curve","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"Illustrative Diminishing Returns of Data","status":"ready","treatment":"annotated","question":"How do equal data budget and equal quality give different comparisons?","scope":"Synthetic diminishing-return curves; real workloads need not share their shape or plateau.","regions":{"gap":{"x":0.23,"y":0.14,"w":0.08,"h":0.36,"label":"Vertical fixed-budget gap"},"blue":{"x":0.08,"y":0.08,"w":0.3,"h":0.59,"label":"Efficient-selection curve"},"gray":{"x":0.38,"y":0.15,"w":0.39,"h":0.45,"label":"Random-sampling curve"},"plateau":{"x":0.6,"y":0.08,"w":0.37,"h":0.08,"label":"Common modeled plateau"}},"steps":[{"title":"Hold dataset size fixed","description":"The red vertical arrow compares the two curves at one dataset size. Its height is a quality gap at equal data budget.","focus":["gap"]},{"title":"Hold quality fixed instead","description":"A horizontal comparison asks how much data each curve needs for the same quality. The more rapidly rising blue curve reaches many intermediate targets sooner.","focus":["blue","gray"]},{"title":"Do not extrapolate the example","description":"Both synthetic curves approach the same plotted plateau. The picture motivates measuring data value; it does not prove every selection method improves every dataset.","focus":["plateau"]}],"artwork_reviewed":true,"art_sha1":"afbcac91d7f1d23f9307b87baf08a6bb02d45921","art_kind":"png","art_width":3393,"art_height":2267},"vol1:fig-precision-ladder":{"key":"vol1:fig-precision-ladder","figure_id":"fig-precision-ladder","source":"books/vol1/08_training/08_training.qmd","title":"Peak Throughput by Number Format","status":"ready","treatment":"annotated","question":"Why do hardware peak rates depend strongly on the number format?","scope":"These are vendor dense peaks, not achieved application throughput. Missing bars are not zero-rate measurements.","regions":{"legend":{"x":0.15,"y":0.01,"w":0.51,"h":0.18,"label":"Execution-format legend"},"v100":{"x":0.16,"y":0.55,"w":0.15,"h":0.4,"label":"V100 formats"},"a100":{"x":0.35,"y":0.46,"w":0.15,"h":0.49,"label":"A100 formats"},"h100":{"x":0.54,"y":0.27,"w":0.15,"h":0.68,"label":"H100 formats"},"b200":{"x":0.73,"y":0.07,"w":0.18,"h":0.88,"label":"B200 formats"}},"steps":[{"title":"Separate arithmetic paths","description":"The legend distinguishes FP32 without tensor cores from tensor execution formats. The logarithmic axis reports rate ratios rather than equal absolute increments.","focus":["legend","v100"]},{"title":"Compare like formats across generations","description":"Follow the same color from V100 through A100 and H100. Newer hardware also introduces paths absent from older devices, so support must be checked as well as width.","focus":["v100","a100","h100"]},{"title":"Do not equate peak with training speed","description":"B200’s format bars differ sharply, but a full training job also depends on numerical suitability, memory traffic, and implementation. A peak-rate gain is not the same as time-to-quality improvement.","focus":["b200"]}],"artwork_reviewed":true,"art_sha1":"efeea0fecaa554096e912492a6826358edcbe8b5","art_kind":"png","art_width":3315,"art_height":2411},"vol1:fig-prefill-decode":{"key":"vol1:fig-prefill-decode","figure_id":"fig-prefill-decode","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Prefill and Decode","status":"ready","treatment":"annotated","question":"Why do prompt processing and token generation stress different resources?","scope":"Schematic small-batch autoregressive inference; compute/bandwidth classifications are typical regimes, not timing measurements.","regions":{"prefill":{"x":0.09,"y":0.2,"w":0.31,"h":0.43,"label":"Prompt-wide prefill"},"cache":{"x":0.1,"y":0.65,"w":0.37,"h":0.24,"label":"Prompt cache and added entries"},"decode":{"x":0.53,"y":0.19,"w":0.47,"h":0.45,"label":"Sequential decode steps"},"cost":{"x":0.01,"y":0.88,"w":0.98,"h":0.12,"label":"Resource-regime explanations"}},"steps":[{"title":"Process the prompt together","description":"Prefill applies matrix–matrix products over all prompt positions, reusing each model weight across those tokens.","focus":["prefill"]},{"title":"Keep keys and values","description":"Prefill writes the prompt keys and values to the KV cache. This persistent per-request state remains available for later token generation.","focus":["cache"]},{"title":"Read history and append one entry","description":"Each decode output becomes the next input. Every step reads the existing cache and adds one token’s keys and values, while rereading model weights.","focus":["decode","cache"]},{"title":"Relate reuse to the bottleneck","description":"Prompt-wide weight reuse often makes prefill compute-bound. At small batch, repeatedly reading weights and cache often makes decode bandwidth-bound.","focus":["cost"]}],"artwork_reviewed":true,"art_sha1":"ffe0e289997708201789d299a33ed3377b160c5a","art_kind":"svg","art_width":1200,"art_height":536,"art_structural_sha1":"639bee09cad1e13256befabfa813c7331908fb11"},"vol1:fig-ptq-calibration":{"key":"vol1:fig-ptq-calibration","figure_id":"fig-ptq-calibration","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Post-Training Quantization Pipeline","status":"ready","treatment":"annotated","question":"What does calibration learn when pretrained weights stay frozen?","scope":"This PTQ workflow does not retrain weights. Calibration quality and supported integer execution must be validated before deployment.","regions":{"model":{"x":0,"y":0,"w":0.47,"h":0.18,"label":"Pretrained model"},"data":{"x":0.53,"y":0,"w":0.47,"h":0.18,"label":"Calibration data"},"calibrate":{"x":0,"y":0.27,"w":1,"h":0.18,"label":"Calibration stage"},"quantize":{"x":0,"y":0.55,"w":1,"h":0.18,"label":"Quantization stage"},"output":{"x":0,"y":0.83,"w":1,"h":0.17,"label":"Quantized model"}},"steps":[{"title":"Start from a trained model","description":"The pretrained model enters with its learned floating-point weights. PTQ avoids a new gradient-training phase.","focus":["model"]},{"title":"Observe representative activation ranges","description":"Calibration data passes through the model so the calibration stage can estimate ranges and associated scale and zero-point metadata. Unrepresentative data can miss deployment tails.","focus":["data","calibrate"]},{"title":"Convert the representation","description":"Quantization maps weights and supported activation boundaries to lower precision using the chosen metadata. Calibration itself has not adapted the model weights.","focus":["quantize"]},{"title":"Validate the exported candidate","description":"The quantized model is a deployment candidate. Check task quality and the real kernel path; a frozen-weight conversion can require revised ranges, granularity, or QAT.","focus":["output"]}],"artwork_reviewed":true,"art_sha1":"54c36a0da64dd5719551fda7d332c3dcd7dc4e28","art_kind":"svg","art_width":1200,"art_height":711,"art_structural_sha1":"0f5d6be969ea75abc987ae99ff80bdd886612975"},"vol1:fig-ptq-qat":{"key":"vol1:fig-ptq-qat","figure_id":"fig-ptq-qat","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"PTQ-to-QAT Pipeline","status":"ready","treatment":"annotated","question":"Why can calibration data initialize a later QAT training phase?","scope":"This is one candidate workflow, not a requirement for every quantized deployment. Calibration data and gradient-training data have distinct roles.","regions":{"pretrained":{"x":0.59,"y":0,"w":0.35,"h":0.11,"label":"Pretrained starting model"},"ptq":{"x":0.01,"y":0.14,"w":0.99,"h":0.36,"label":"PTQ initialization phase"},"caldata":{"x":0.07,"y":0.35,"w":0.34,"h":0.11,"label":"Calibration examples"},"ptqout":{"x":0.59,"y":0.53,"w":0.35,"h":0.11,"label":"PTQ model"},"qat":{"x":0.01,"y":0.67,"w":0.99,"h":0.18,"label":"QAT fine-tuning phase"},"qatout":{"x":0.59,"y":0.89,"w":0.35,"h":0.11,"label":"QAT model"}},"steps":[{"title":"Initialize from a trained model","description":"The pretrained model enters the PTQ group. Its learned weights provide the starting behavior for calibration.","focus":["pretrained","ptq"]},{"title":"Estimate ranges without gradients","description":"Calibrate data feeds Calibrate model in PTQ. The resulting ranges and scales initialize the lower-precision candidate while weights remain frozen in this phase.","focus":["caldata","ptq"]},{"title":"Adapt with training data","description":"The PTQ model enters the QAT group. Training data now drives Fine-tune model with simulated quantization and floating-point weight updates.","focus":["ptqout","qat"]},{"title":"Export the adapted candidate","description":"The QAT model is the result of the training phase. It must still satisfy quality thresholds and supported target execution.","focus":["qatout"]}],"artwork_reviewed":true,"art_sha1":"a7514b80556e62a51b08043b99f1f1bef2888119","art_kind":"svg","art_width":1200,"art_height":1216,"art_structural_sha1":"8b07c38a04c6e0a8e2a7277a1ba80b2fa7e38c94"},"vol1:fig-python-tax":{"key":"vol1:fig-python-tax","figure_id":"fig-python-tax","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"Python Dispatch Overhead","status":"ready","treatment":"annotated","question":"Where does host dispatch leave the accelerator idle?","scope":"The displayed timeline is an illustrative Python-overhead model; omitted launch costs and workload dependence prevent a universal speedup claim.","regions":{"first":{"x":0.18,"y":0.06,"w":0.16,"h":0.23,"label":"First dispatch and kernel"},"eager":{"x":0.18,"y":0.06,"w":0.77,"h":0.23,"label":"Repeated eager dispatch"},"compiled":{"x":0.18,"y":0.59,"w":0.14,"h":0.23,"label":"Compiled/fused submission"},"axis":{"x":0.17,"y":0.86,"w":0.81,"h":0.14,"label":"Execution time"}},"steps":[{"title":"Separate dispatch from arithmetic","description":"The first red block is Python overhead; the narrow blue block is GPU computation. Host dispatch dominates this small-operation example.","focus":["first"]},{"title":"Repeat the gap","description":"The eager row repeats dispatch before every kernel. The red intervals explain why fast individual kernels can still produce a slow end-to-end sequence.","focus":["eager"]},{"title":"Submit a captured region","description":"The compiled/fused row has one submission followed by a fused compute region. Fusion also avoids intermediate global-memory round trips; this chart isolates the stated overhead scenario.","focus":["compiled"]},{"title":"Compare total elapsed time","description":"Both rows share the microsecond axis. The improvement belongs to this fine-grained example, not to every large compute-bound kernel.","focus":["axis","eager","compiled"]}],"artwork_reviewed":true,"art_sha1":"8c6ead062a1042d0f5cfdacc928c7c4a50d8b8d1","art_kind":"png","art_width":3613,"art_height":2033},"vol1:fig-qat":{"key":"vol1:fig-qat","figure_id":"fig-qat","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Quantization-Aware Training Pipeline","status":"ready","treatment":"annotated","question":"How can training adapt weights to the errors of quantized inference?","scope":"The flowchart abstracts fake quantization and STE. It does not mean that master weights or gradient updates are stored and optimized entirely as INT8.","regions":{"model":{"x":0,"y":0,"w":0.47,"h":0.18,"label":"Pretrained model"},"quantize":{"x":0,"y":0.28,"w":0.47,"h":0.17,"label":"Quantization simulation"},"data":{"x":0.53,"y":0,"w":0.47,"h":0.45,"label":"Training data"},"retrain":{"x":0,"y":0.55,"w":1,"h":0.18,"label":"Retraining and fine-tuning"},"output":{"x":0,"y":0.83,"w":1,"h":0.17,"label":"Quantized export"}},"steps":[{"title":"Begin with pretrained weights","description":"The model supplies a learned floating-point starting point. Quantization-aware training adds the deployment precision constraints to the training procedure.","focus":["model","quantize"]},{"title":"Simulate rounding and clipping","description":"The quantization stage represents fake quantization in the forward graph. It exposes the model to the numerical distortion expected at deployment.","focus":["quantize"]},{"title":"Update floating-point parameters","description":"Training data drives Retraining/Finetuning. Approximate STE gradients pass through the rounding operation so floating-point master weights can adapt.","focus":["data","retrain"]},{"title":"Export and validate inference","description":"The final Quantized model uses the chosen integer representation and scales. Training adaptation has a compute cost and does not remove the need for deployment quality checks.","focus":["output"]}],"artwork_reviewed":true,"art_sha1":"5d4676daea9c1add32cfe4b87142f4f822e29621","art_kind":"svg","art_width":1200,"art_height":861,"art_structural_sha1":"52e34ffd2f894b81712ad3ceb996a306b53dbded"},"vol1:fig-quantization-error-dist":{"key":"vol1:fig-quantization-error-dist","figure_id":"fig-quantization-error-dist","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Illustrative Aggregate Quantization Residuals","status":"ready","treatment":"annotated","question":"What distinguishes bounded rounding error from larger aggregate residual tails?","scope":"Illustrative aggregate residual density, not one uniform quantizer with a declared scale. The horizontal values are not a universal half-step bound.","regions":{"center":{"x":0.36,"y":0.12,"w":0.35,"h":0.63,"label":"Residual concentration around zero"},"left":{"x":0.09,"y":0.68,"w":0.14,"h":0.16,"label":"Negative residual tail"},"right":{"x":0.8,"y":0.68,"w":0.17,"h":0.16,"label":"Positive residual tail"},"axis":{"x":0.08,"y":0.83,"w":0.9,"h":0.12,"label":"Residual axis"}},"steps":[{"title":"Locate the typical residual","description":"The tallest bars cluster near zero. Quantization changes values even when most differences remain small.","focus":["center"]},{"title":"Inspect both tails","description":"The red callouts draw attention to larger negative and positive residuals. Rare larger errors can matter even when the distribution is centered.","focus":["left","right"]},{"title":"Keep the quantizer boundary explicit","description":"For one unclipped uniform quantizer, nearest rounding stays within half a step. These aggregate tails instead represent clipping or a mixture of step sizes, so the displayed axis does not define that bound.","focus":["axis","center"]}],"artwork_reviewed":true,"art_sha1":"a1b8cd960f3457eaac583e3f9f55a1430696518b","art_kind":"svg","art_width":1200,"art_height":665,"art_structural_sha1":"20ed84ba2f30c163f44702824ef3f95720c65944"},"vol1:fig-quantization-free-lunch":{"key":"vol1:fig-quantization-free-lunch","figure_id":"fig-quantization-free-lunch","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Illustrative Quantization Regimes","status":"ready","treatment":"annotated","question":"Why must a low-bit deployment validate the accuracy cliff for its own model?","scope":"The two named curves are illustrative assumed regimes, not measured ResNet-50 or BERT benchmarks. Breakpoints are not general precision recommendations.","regions":{"plateau":{"x":0.1,"y":0.04,"w":0.71,"h":0.18,"label":"Illustrative accuracy plateau"},"cliff":{"x":0.86,"y":0.04,"w":0.12,"h":0.76,"label":"Low-bit cliff"},"bits":{"x":0.1,"y":0.81,"w":0.88,"h":0.18,"label":"Precision formats"},"legend":{"x":0.1,"y":0.67,"w":0.37,"h":0.12,"label":"Two illustrative curves"}},"steps":[{"title":"Read precision in the plotted direction","description":"The axis runs from FP32 on the left toward fewer bits on the right. This is a precision choice, not training time.","focus":["bits"]},{"title":"Inspect the assumed plateau","description":"Both curves stay relatively flat over part of the range. This illustrates tolerance to some quantization error, not a guarantee of lossless conversion.","focus":["plateau"]},{"title":"Locate the model-dependent cliff","description":"At the narrowest formats the illustrative curves fall sharply and differently. Calibration, outliers, quantizer design, and task evaluation determine the actual boundary.","focus":["cliff"]},{"title":"Treat the labels as scenarios","description":"The legend names example model families, but the plotted values are stipulated. A deployment decision requires quality measurements for the actual model and execution path.","focus":["legend"]}],"artwork_reviewed":true,"art_sha1":"91ed03039a2d67d084bd86e6b805ff341dca78e2","art_kind":"png","art_width":3278,"art_height":2463},"vol1:fig-quantization-granularity":{"key":"vol1:fig-quantization-granularity","figure_id":"fig-quantization-granularity","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Quantization Range Variation","status":"ready","treatment":"annotated","question":"Why can one layerwide range underserve narrow channels?","scope":"The distributions are schematic. Per-channel scales add metadata and require supported kernels; the figure is not a measured accuracy comparison.","regions":{"layer":{"x":0,"y":0.08,"w":0.16,"h":0.85,"label":"Selected convolution layer"},"filters":{"x":0.3,"y":0.02,"w":0.13,"h":0.88,"label":"Individual filters"},"layerwise":{"x":0.46,"y":0,"w":0.25,"h":0.98,"label":"Shared layerwise range"},"channelwise":{"x":0.75,"y":0,"w":0.25,"h":0.98,"label":"Channel-specific ranges"}},"steps":[{"title":"Separate the filters","description":"The selected layer expands into filters 1 through C. Their weight distributions have different widths.","focus":["layer","filters"]},{"title":"Share one range","description":"The Layerwise Quantization column uses common red bounds. A range wide enough for the broadest filter leaves fewer effective levels across a narrow filter's values.","focus":["layerwise"]},{"title":"Fit each channel locally","description":"The Channelwise Quantization column adapts blue bounds to each distribution. Local ranges can preserve resolution at the cost of additional scale metadata and execution complexity.","focus":["channelwise"]},{"title":"Validate the complete format","description":"Per-channel ranges are a representation choice, not a guarantee of faster inference. Metadata, packing, arithmetic, and kernel support must fit the deployment.","focus":["filters","channelwise"]}],"artwork_reviewed":true,"art_sha1":"30ebed70fc63416140539c8cdb3ae456a86d6706","art_kind":"svg","art_width":1200,"art_height":818,"art_structural_sha1":"4008562a67da2ce241278cf1952b006f2d4cfdce"},"vol1:fig-quantization-impact":{"key":"vol1:fig-quantization-impact","figure_id":"fig-quantization-impact","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Illustrative Quantization Scenario","status":"ready","treatment":"annotated","question":"Why is fourfold raw weight reduction different from latency speedup?","scope":"These paired bars are illustrative. Raw weight storage excludes auxiliary metadata, activations, and runtime state; latency is architecture- and kernel-dependent.","regions":{"latency":{"x":0,"y":0.09,"w":0.49,"h":0.87,"label":"Inference-time comparison"},"storage":{"x":0.51,"y":0.09,"w":0.49,"h":0.87,"label":"Weight-storage comparison"},"inception":{"x":0.07,"y":0.18,"w":0.12,"h":0.68,"label":"Inception latency pair"},"mobile":{"x":0.22,"y":0.25,"w":0.12,"h":0.61,"label":"MobileNet latency pair"},"resnet":{"x":0.37,"y":0.55,"w":0.12,"h":0.31,"label":"ResNet latency pair"}},"steps":[{"title":"Count weight bits","description":"The Weight Storage panel compares FP32 with INT8. Moving each raw value from 32 to 8 bits gives a fourfold weight-value reduction across all three models.","focus":["storage"]},{"title":"Compare latency independently","description":"The Inference Time panel has a different vertical axis and unequal reductions. Its bars do not follow one shared fourfold latency ratio.","focus":["latency"]},{"title":"Notice architecture dependence","description":"The MobileNet pair improves much more strongly than the Inception pair in this illustrative setting. Operator shapes and kernel support influence realized execution.","focus":["inception","mobile","resnet"]},{"title":"Keep total memory separate","description":"Weight storage is only one part of inference memory. The panel does not claim a fourfold reduction in activations, metadata, or total allocated memory.","focus":["storage"]}],"artwork_reviewed":true,"art_sha1":"fa5a739293bf5b363b1d3c28952383715c4913ac","art_kind":"svg","art_width":1200,"art_height":555,"art_structural_sha1":"d108c3893fd229d6374fc59e842805ff078ba264"},"vol1:fig-quantization-roadmap":{"key":"vol1:fig-quantization-roadmap","figure_id":"fig-quantization-roadmap","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Quantization Engineering Workflow","status":"ready","treatment":"annotated","question":"When should frozen-weight calibration give way to training or custom execution?","scope":"The tiers order engineering effort rather than guaranteeing quality. INT8, INT4, per-channel scaling, and mixed precision can appear across stages.","regions":{"ptq":{"x":0,"y":0.02,"w":0.3,"h":0.96,"label":"Post-training quantization"},"qat":{"x":0.34,"y":0.02,"w":0.29,"h":0.96,"label":"Quantization-aware training"},"special":{"x":0.68,"y":0.02,"w":0.32,"h":0.96,"label":"Specialized and extreme formats"}},"steps":[{"title":"Try calibration without retraining","description":"Post-Training (PTQ) starts with frozen pretrained weights. It avoids gradient updates but still requires representative calibration and task validation.","focus":["ptq"]},{"title":"Recover quality through training","description":"Quantization-Aware (QAT) introduces simulated noise while fine-tuning floating-point weights. It spends training compute when the frozen-weight candidate falls short.","focus":["qat"]},{"title":"Require a matching datapath","description":"Specialized & Extreme formats may need custom kernels and hardware co-design. A narrower representation is useful only with supported execution and validated quality.","focus":["special"]}],"artwork_reviewed":true,"art_sha1":"e0fece918cccf5705322c6f2a64dd30edee063e1","art_kind":"svg","art_width":1200,"art_height":377,"art_structural_sha1":"6d8963becb8d7fc2178cecf1cc2e95cd88705549"},"vol1:fig-resnet-activations-histogram":{"key":"vol1:fig-resnet-activations-histogram","figure_id":"fig-resnet-activations-histogram","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Activation Distribution","status":"ready","treatment":"annotated","question":"Why can a long activation tail waste integer resolution?","scope":"The marked boundary near 1.1 is a candidate, not an identified percentile. Choosing it requires cumulative counts and task validation.","regions":{"bulk":{"x":0.09,"y":0.13,"w":0.39,"h":0.66,"label":"Dense activation bulk"},"threshold":{"x":0.47,"y":0.13,"w":0.025,"h":0.67,"label":"Candidate clipping threshold"},"tail":{"x":0.52,"y":0.65,"w":0.31,"h":0.15,"label":"Sparse outlier tail"},"axis":{"x":0.07,"y":0.79,"w":0.91,"h":0.14,"label":"Activation values"}},"steps":[{"title":"Inspect the dense bulk","description":"The tallest bars sit near small activation values. Allocating most integer levels to this populated range can improve resolution.","focus":["bulk"]},{"title":"Find the long tail","description":"A sparse tail extends beyond the bulk. Keeping its full span consumes part of a fixed integer grid even where few activation values occur.","focus":["tail"]},{"title":"Test a candidate boundary","description":"The dashed threshold proposes clipping near the end of the bulk. Clipping can distort rare but important cases, so its apparent visual convenience is not enough.","focus":["threshold","tail"]},{"title":"Validate rather than infer a percentile","description":"The axis shows activation magnitude, not cumulative frequency. The diagram does not establish which percentile the candidate boundary represents.","focus":["axis","bulk"]}],"artwork_reviewed":true,"art_sha1":"846d4f1b1be9aeb10b152d2ec8c5a109ac201da5","art_kind":"svg","art_width":1200,"art_height":508,"art_structural_sha1":"2b752fc40e4f7afae8be6d7ce77d61c59f7f2cf8"},"vol1:fig-responsible-lifecycle":{"key":"vol1:fig-responsible-lifecycle","figure_id":"fig-responsible-lifecycle","source":"books/vol1/15_responsible_engr/15_responsible_engr.qmd","title":"The Responsible Engineering Lifecycle","status":"ready","treatment":"annotated","question":"How do responsible-engineering requirements become continuing operational work?","scope":"Lifecycle and resource-accounting schematic; controls supply evidence rather than automatic legal compliance.","regions":{"specify":{"x":0,"y":0.19,"w":0.21,"h":0.39,"label":"Specify requirements"},"measure":{"x":0.26,"y":0.19,"w":0.21,"h":0.39,"label":"Measure release gates"},"explain":{"x":0.52,"y":0.19,"w":0.22,"h":0.39,"label":"Explain and document"},"operate":{"x":0.78,"y":0.19,"w":0.22,"h":0.39,"label":"Operate and observe"},"feedback":{"x":0.09,"y":0,"w":0.83,"h":0.2,"label":"Operational feedback"},"resource":{"x":0,"y":0.68,"w":1,"h":0.15,"label":"Resource every stage"},"govern":{"x":0,"y":0.84,"w":1,"h":0.16,"label":"Govern every stage"}},"steps":[{"title":"Turn goals into release evidence","description":"Specify names the target populations and oversight boundary. Measure evaluates those requirements per slice and can require mitigation training.","focus":["specify","measure"]},{"title":"Carry explanation and monitoring into production","description":"Explain and document makes decisions and models reviewable; Operate collects per-group telemetry. Operational evidence feeds the next specification rather than ending at release.","focus":["explain","operate","feedback"]},{"title":"Budget and govern the entire lifecycle","description":"Resource and Govern span all four stages. Labeled data, reviewer hours, explanation compute, telemetry, energy, and audit evidence remain engineering costs across the lifecycle.","focus":["resource","govern"]}],"artwork_reviewed":true,"art_sha1":"f8967dae185bf287c0e189989932f824d6ae4fe7","art_kind":"svg","art_width":1200,"art_height":434,"art_structural_sha1":"5607708e9c50911c0c1102c20c40d558fb14f499"},"vol1:fig-rising-ridge":{"key":"vol1:fig-rising-ridge","figure_id":"fig-rising-ridge","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"The Rising Ridge","status":"ready","treatment":"annotated","question":"Why does newer compute hardware require more reuse to reach its peak?","scope":"Dense FP16 peak divided by device-memory bandwidth; the selected generations are not an exhaustive vendor history.","regions":{"early":{"x":0.1,"y":0.54,"w":0.43,"h":0.24,"label":"V100 and A100 ridge points"},"later":{"x":0.58,"y":0.29,"w":0.36,"h":0.3,"label":"H100 and B200 ridge points"},"low":{"x":0.09,"y":0.79,"w":0.52,"h":0.14,"label":"Lower ridge region"},"high":{"x":0.25,"y":0.1,"w":0.66,"h":0.19,"label":"Higher ridge region"}},"steps":[{"title":"Interpret the ridge as a ratio","description":"Each point divides dense tensor peak by memory bandwidth. It is the arithmetic intensity needed to leave the bandwidth-limited regime, not an achieved application rate.","focus":["early"]},{"title":"Follow the higher requirement","description":"The rise from V100 and A100 toward H100 means the same low-intensity kernel can remain bandwidth limited despite added arithmetic capacity. B200 stays near that higher requirement.","focus":["later"]},{"title":"Connect the ratio to reuse","description":"A higher ridge requires more operations per byte fetched. Reuse must raise kernel intensity before the extra peak compute can be fully useful.","focus":["low","high"]}],"artwork_reviewed":true,"art_sha1":"e95953c888882a697b1c9c097c7d4d4bbc93d656","art_kind":"png","art_width":3324,"art_height":2234},"vol1:fig-rnn":{"key":"vol1:fig-rnn","figure_id":"fig-rnn","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Recurrent Neural Network Unfolding","status":"ready","treatment":"annotated","question":"Why does a longer RNN sequence reuse parameters but add sequential work?","scope":"Three unfolded steps illustrate a recurrent cell with shared weights; hidden-state values differ at each time.","regions":{"compact":{"x":0,"y":0,"w":0.12,"h":1,"label":"Compact recurrent cell"},"first":{"x":0.34,"y":0,"w":0.12,"h":1,"label":"Previous time step"},"middle":{"x":0.6,"y":0,"w":0.12,"h":1,"label":"Current time step"},"next":{"x":0.85,"y":0,"w":0.14,"h":1,"label":"Next time step"}},"steps":[{"title":"Read one recurrent cell","description":"The compact graph maps input x and previous hidden state through W_hx and W_hh, then maps hidden state to output through W_yh.","focus":["compact"]},{"title":"Follow the hidden-state dependency","description":"The horizontal arrow passes h from one time step to the next. The current step requires the preceding state even though input projections can have separate implementation choices.","focus":["first","middle"]},{"title":"Reuse the same matrices","description":"The repeated W labels denote shared parameters, not separate learned matrices for each time step. Sequence length adds activations and work without increasing these parameter matrices.","focus":["middle","next"]}],"artwork_reviewed":true,"art_sha1":"b6fe98c9c2e816834300972f3a87acb841bbdbce","art_kind":"svg","art_width":1200,"art_height":391,"art_structural_sha1":"c6dd25879fdbe7166465e166b7ab274cd886c435"},"vol1:fig-roofline":{"key":"vol1:fig-roofline","figure_id":"fig-roofline","source":"books/vol1/backmatter/appendix_machine.qmd","title":"The Roofline Model","status":"ready","treatment":"annotated","question":"How does arithmetic intensity determine the relevant hardware ceiling?","scope":"The schematic has no calibrated workload coordinates; a ceiling bounds attainable performance rather than guaranteeing it.","regions":{"memory":{"x":0.14,"y":0.29,"w":0.31,"h":0.55,"label":"Memory-bandwidth ceiling"},"ridge":{"x":0.41,"y":0.23,"w":0.09,"h":0.66,"label":"Ridge point"},"compute":{"x":0.48,"y":0.19,"w":0.32,"h":0.15,"label":"Peak-compute ceiling"},"axis":{"x":0.14,"y":0.85,"w":0.85,"h":0.15,"label":"Arithmetic-intensity axis"}},"steps":[{"title":"Count computation per byte","description":"Arithmetic Intensity is FLOP/byte. Moving right means more arithmetic for the bytes moved, for example through data reuse rather than simply adding operations without a purpose.","focus":["axis"]},{"title":"Read the bandwidth ceiling","description":"Left of the ridge, available memory bandwidth determines the sloped ceiling. Reducing memory traffic can increase the achievable bound in this regime.","focus":["memory"]},{"title":"Meet the compute ceiling","description":"At the Ridge Point, the two limits meet. Beyond it, the flat compute ceiling applies; more reuse alone cannot exceed the peak arithmetic rate.","focus":["ridge","compute"]}],"artwork_reviewed":true,"art_sha1":"c213f1d95e751987950625d9c1a399bf50452728","art_kind":"svg","art_width":1200,"art_height":637,"art_structural_sha1":"b52adbc4eb5837ddc00485c77ce12db87fde3cbf"},"vol1:fig-rotting-asset-curve":{"key":"vol1:fig-rotting-asset-curve","figure_id":"fig-rotting-asset-curve","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"The Rotting Asset Curve","status":"ready","treatment":"annotated","question":"What do fixed schedules and threshold triggers assume about recovery?","scope":"Illustrative exponential decay with instantaneous, fully restoring retraining resets; real labeling, training, validation, and rollout delays can breach the trigger floor.","regions":{"scheduled":{"x":0.1,"y":0.26,"w":0.8,"h":0.56,"label":"Scheduled orange decay and resets"},"triggered":{"x":0.1,"y":0.05,"w":0.8,"h":0.24,"label":"Triggered green sawtooth"},"threshold":{"x":0.06,"y":0.28,"w":0.86,"h":0.04,"label":"Drift-threshold line"},"time":{"x":0.07,"y":0.89,"w":0.86,"h":0.1,"label":"Days since deployment"}},"steps":[{"title":"Start from the same deployed quality","description":"Both policies begin at the same accuracy and follow the same decay model. The horizontal axis measures elapsed deployment days rather than number of training steps.","focus":["time","triggered"]},{"title":"Inspect a calendar-driven reset","description":"The orange policy waits for each 90-day reset, so its curve crosses the threshold before recovery. A fixed calendar does not react to the observed crossing.","focus":["scheduled","threshold"]},{"title":"Expose the idealization in triggering","description":"The green curve resets at each threshold crossing and therefore maintains a higher depicted floor. Zero response delay creates that floor; a deployed trigger cannot guarantee it without accounting for the full recovery path.","focus":["triggered","threshold"]}],"artwork_reviewed":true,"art_sha1":"03709fe2d6a35fde9cae70ec895a566519ab7795","art_kind":"png","art_width":3422,"art_height":2096},"vol1:fig-row-vs-col":{"key":"vol1:fig-row-vs-col","figure_id":"fig-row-vs-col","source":"books/vol1/backmatter/appendix_data.qmd","title":"Storage Layouts","status":"ready","treatment":"annotated","question":"How can a column-oriented layout avoid irrelevant field reads?","scope":"This is the illustrated Age projection. Real savings depend on file format, compression, query planning, and physical I/O.","regions":{"row1":{"x":0.11,"y":0.1,"w":0.41,"h":0.19,"label":"First row record"},"row2":{"x":0.56,"y":0.1,"w":0.4,"h":0.19,"label":"Second row record"},"age":{"x":0.44,"y":0.66,"w":0.27,"h":0.17,"label":"Age column chunk"},"other":{"x":0.44,"y":0.49,"w":0.27,"h":0.49,"label":"Other column chunks"},"scan":{"x":0.77,"y":0.76,"w":0.23,"h":0.16,"label":"Age-only scan label"}},"steps":[{"title":"Read whole records","description":"The Row-Oriented (CSV) strip interleaves ID, Age, and Loc for each record. The depicted scan reads all these fields even though only Age is requested.","focus":["row1","row2"]},{"title":"Group values by feature","description":"The Column-Oriented (Parquet) block groups both Age values together. Projection can request that chunk without reading the ID and Loc chunks shown around it.","focus":["age","other"]},{"title":"Connect layout to traffic","description":"The lower scan reads ONLY Age in this example. This reduces irrelevant movement for this query; it does not imply every query favors column storage or that bytes saved equal proportional speedup.","focus":["scan","age"]}],"artwork_reviewed":true,"art_sha1":"77fc1df0ea1fae8765902a457bb1ba86e49dabea","art_kind":"svg","art_width":1200,"art_height":371,"art_structural_sha1":"8af9aa7d36ac0b12bd4e84598e22c077c7e5e60f"},"vol1:fig-running-out-of-human-data":{"key":"vol1:fig-running-out-of-human-data","figure_id":"fig-running-out-of-human-data","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Training Data Approaching the Stock of Public Text","status":"ready","treatment":"annotated","question":"How should reported training tokens be compared with uncertain text supply?","scope":"This is a dated constraint scenario, not an exhaustion forecast. Repeated training tokens are not unique usable text.","regions":{"reported":{"x":0.16,"y":0.37,"w":0.59,"h":0.53,"label":"Reported model token counts"},"stock":{"x":0.16,"y":0.09,"w":0.79,"h":0.23,"label":"Estimated public-text stock"},"projection":{"x":0.7,"y":0.1,"w":0.25,"h":0.36,"label":"Extrapolated fit"},"legend":{"x":0.56,"y":0.86,"w":0.39,"h":0.12,"label":"Reported points and fitted line"}},"steps":[{"title":"Read the observed demand","description":"Labeled points report pre-training token counts for particular model releases. The logarithmic vertical axis makes equal vertical distances represent multiplicative changes.","focus":["reported"]},{"title":"Read the uncertain supply","description":"The orange band is the estimated stock of public human text with a 90 percent interval; the dotted line marks its median. This estimate is not the same quantity as repeated training-token use.","focus":["stock"]},{"title":"Bound the extrapolation","description":"The dashed fit continues beyond reported releases and enters the stock band. Licensing, filtering, synthetic generation, and other modalities can change the constraint, so this extension is a scenario rather than a date prediction.","focus":["projection","legend"]}],"artwork_reviewed":true,"art_sha1":"f31290635dcfdada0a5e210e3302921835c92d6f","art_kind":"png","art_width":3347,"art_height":2419},"vol1:fig-sciml-graph":{"key":"vol1:fig-sciml-graph","figure_id":"fig-sciml-graph","source":"books/vol1/12_benchmarking/12_benchmarking.qmd","title":"Performance Spectrum","status":"ready","treatment":"annotated","question":"Why do scientific and mobile workloads need different benchmark constraints?","scope":"Sourced operating ranges and the shaded benchmark envelope are descriptive, not a universal feasibility boundary.","regions":{"sensor":{"x":0.1,"y":0.0,"w":0.32,"h":0.12,"label":"LHC sensor operating point"},"trigger":{"x":0.12,"y":0.26,"w":0.36,"h":0.18,"label":"Trigger and plasma-control region"},"instrument":{"x":0.24,"y":0.43,"w":0.4,"h":0.27,"label":"Scientific instrument region"},"mobile":{"x":0.5,"y":0.7,"w":0.26,"h":0.16,"label":"IoT and mobile region"},"envelope":{"x":0.08,"y":0.0,"w":0.48,"h":0.81,"label":"Fast ML for Science envelope"}},"steps":[{"title":"Read both physical requirements","description":"The LHC sensor point combines a very high byte rate with a very short computation window. Both logarithmic axes matter when deciding whether a system can keep up.","focus":["sensor"]},{"title":"Inspect instrument constraints","description":"Triggers, plasma control, and scientific instruments occupy distinct timing and data-rate ranges. Their error bars and positions preserve application-specific requirements rather than one generic throughput target.","focus":["trigger","instrument"]},{"title":"Choose a representative benchmark","description":"Mobile and IoT points lie far from several scientific operating points. The shaded Fast ML for Science region motivates matching evaluation to the application’s timing and data movement constraints.","focus":["mobile","envelope"]}],"artwork_reviewed":true,"art_sha1":"83a0c452903eeac588b5e5484bd75731bdb75c0f","art_kind":"svg","art_width":1200,"art_height":1140,"art_structural_sha1":"d315e47a7fb2ea821ad698b00f53f58b130730a3"},"vol1:fig-selection-inequality":{"key":"vol1:fig-selection-inequality","figure_id":"fig-selection-inequality","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"The Selection Inequality","status":"ready","treatment":"annotated","question":"When does selection save end-to-end training time?","scope":"Normalized illustrative costs at matched quality; savings include selection overhead, not just subset training.","regions":{"baseline":{"x":0.14,"y":0.19,"w":0.12,"h":0.73,"label":"Full-training cost 100"},"efficient":{"x":0.48,"y":0.6,"w":0.12,"h":0.32,"label":"Selection 5 plus training 40"},"expensive":{"x":0.82,"y":0.19,"w":0.12,"h":0.73,"label":"Selection 60 plus training 40"},"savings":{"x":0.54,"y":0.21,"w":0.19,"h":0.4,"label":"55 percent savings comparison"}},"steps":[{"title":"Establish the full-training baseline","description":"The blue baseline costs 100 normalized time units. It is the total against which a selected-subset pipeline must be compared.","focus":["baseline"]},{"title":"Include cheap selection in the total","description":"Efficient selection costs 5 and subset training costs 40, totaling 45. The net saving is 55 relative to 100, rather than the 60 suggested by subset training alone.","focus":["efficient","savings"]},{"title":"Expensive scoring can erase the gain","description":"The expensive selector costs 60 before the same 40-unit subset training. Its total is 100, so reducing training samples produces no net time saving here.","focus":["expensive"]}],"artwork_reviewed":true,"art_sha1":"b1b0da08ad43b801d3ed076fe90354e50d087c9b","art_kind":"png","art_width":3397,"art_height":2237},"vol1:fig-server-anatomy":{"key":"vol1:fig-server-anatomy","figure_id":"fig-server-anatomy","source":"books/vol1/13_model_serving/13_model_serving.qmd","title":"Inference Server Anatomy","status":"ready","treatment":"annotated","question":"How does a server decouple irregular requests from accelerator execution?","scope":"Logical server stages; no queue capacity, batch window, service duration, or throughput is encoded by the arrows.","regions":{"ingress":{"x":0,"y":0.02,"w":0.43,"h":0.46,"label":"Client and network ingress"},"queue":{"x":0.45,"y":0.02,"w":0.21,"h":0.46,"label":"Request queue"},"batch":{"x":0.67,"y":0.02,"w":0.3,"h":0.46,"label":"Dynamic batcher"},"runner":{"x":0.51,"y":0.5,"w":0.47,"h":0.2,"label":"Inference runner"},"accelerator":{"x":0.51,"y":0.78,"w":0.47,"h":0.22,"label":"Accelerator"}},"steps":[{"title":"Admit requests separately from executing them","description":"Network ingress handles arriving client requests before accelerator work begins. This separates network-facing work from the device execution path.","focus":["ingress"]},{"title":"Distinguish waiting from batch formation","description":"The queue absorbs waiting requests; the dynamic batcher groups work for efficient execution. Waiting may improve utilization while consuming the response-time budget.","focus":["queue","batch"]},{"title":"Dispatch through a runner","description":"The inference runner prepares executable work for the accelerator. Optimizing the runner and hardware does not erase ingress, queue, or batching delay.","focus":["runner","accelerator"]}],"artwork_reviewed":true,"art_sha1":"320cfeb19fab4646cfeae51d6f1b71a80152fad0","art_kind":"svg","art_width":1200,"art_height":698,"art_structural_sha1":"285955c9e861e7e0d474d2a4051bbe8ac6be31b0"},"vol1:fig-serving-inference-pipeline":{"key":"vol1:fig-serving-inference-pipeline","figure_id":"fig-serving-inference-pipeline","source":"books/vol1/13_model_serving/13_model_serving.qmd","title":"The Inference Pipeline","status":"ready","treatment":"annotated","question":"Why is model execution only part of inference latency?","scope":"A stage schematic, without timing encoded by icon spacing or arrow length.","regions":{"pre":{"x":0,"y":0,"w":0.33,"h":0.97,"label":"Raw input and preprocessing"},"network":{"x":0.35,"y":0,"w":0.14,"h":0.97,"label":"Neural network"},"post":{"x":0.51,"y":0,"w":0.49,"h":0.97,"label":"Raw output postprocessing and final output"}},"steps":[{"title":"Prepare a model-ready input","description":"Preprocessing transforms raw data into the representation expected by the neural network. Its work occurs before model arithmetic can consume the input.","focus":["pre"]},{"title":"Execute the model","description":"The neural network converts prepared input into raw model output. This stage can dominate some workloads, but the diagram deliberately retains the surrounding operations.","focus":["network"]},{"title":"Return a usable result","description":"Postprocessing converts raw outputs into the final response. End-to-end latency must include this stage as well as preprocessing and inference.","focus":["post"]}],"artwork_reviewed":true,"art_sha1":"07af8bfdbbae42d19d7cc20c58c078175883075a","art_kind":"svg","art_width":1200,"art_height":226,"art_structural_sha1":"61daaaa1f48ed98e19c366aed5de86ce10a1eed3"},"vol1:fig-serving-pipeline-timing":{"key":"vol1:fig-serving-pipeline-timing","figure_id":"fig-serving-pipeline-timing","source":"books/vol1/13_model_serving/13_model_serving.qmd","title":"Request Pipelining","status":"ready","treatment":"annotated","question":"How can pipelining improve utilization without changing a model?","scope":"Schematic independent CPU and GPU operations; overlap improves steady-state throughput, not necessarily a single request’s intrinsic latency.","regions":{"serial":{"x":0,"y":0.04,"w":1,"h":0.29,"label":"Serial execution and idle gap"},"cpu":{"x":0,"y":0.58,"w":0.81,"h":0.21,"label":"Pipelined preprocessing"},"gpu":{"x":0.2,"y":0.79,"w":0.8,"h":0.21,"label":"Pipelined GPU execution"}},"steps":[{"title":"Find the serial idle interval","description":"In row A, preprocessing and GPU execution do not overlap across requests. The accelerator waits again before the next prepared request becomes available.","focus":["serial"]},{"title":"Overlap independent requests","description":"In row B, CPU Pre 2 runs while GPU 1 executes. These operations belong to different requests and can use distinct resources concurrently.","focus":["cpu","gpu"]},{"title":"Read the filled pipeline","description":"After the initial fill, the device receives successive ready requests with less idle time. The gain comes from scheduling and resource overlap rather than reducing the model’s arithmetic.","focus":["gpu"]}],"artwork_reviewed":true,"art_sha1":"ac49c3d3d884a18f038ea5f02b52bfce8532968d","art_kind":"svg","art_width":1200,"art_height":431,"art_structural_sha1":"e2e5e9d04f0e60135950b5845c6edf58cc3ce7bb"},"vol1:fig-smallest-capable-model":{"key":"vol1:fig-smallest-capable-model","figure_id":"fig-smallest-capable-model","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Smallest Model Reaching a Fixed Score","status":"ready","treatment":"annotated","question":"How can a fixed capability threshold later fit a smaller model?","scope":"Reported MMLU scores and name-derived parameter counts form an observational lower envelope. Training data, specialization, and evaluation differences prevent attribution to compression alone.","regions":{"legend":{"x":0.12,"y":0.66,"w":0.43,"h":0.19,"label":"Threshold and envelope legend"},"early":{"x":0.17,"y":0.1,"w":0.34,"h":0.25,"label":"Early Gopher and Chinchilla steps"},"later":{"x":0.57,"y":0.33,"w":0.42,"h":0.33,"label":"Later Llama Mistral and Qwen steps"},"below":{"x":0.29,"y":0.38,"w":0.63,"h":0.38,"label":"Below-threshold observations"}},"steps":[{"title":"Choose a fixed capability test","description":"Blue points reach the stated 60 percent MMLU threshold; gray points do not. A small gray model cannot lower the threshold-qualified envelope.","focus":["legend","below"]},{"title":"Track the first qualifying sizes","description":"The red step line follows the smallest qualifying model available up to each date. The early Gopher and Chinchilla steps establish the initial scale.","focus":["early"]},{"title":"Follow the lower envelope","description":"Later named models lower the red line toward smaller parameter counts. This shows a reported capability fitting smaller models, not the same model being repeatedly pruned.","focus":["later"]},{"title":"Keep the comparison boundary","description":"The gray observations and dispersed blue points show this is a selection from reported models. It is not a controlled experiment isolating one compression method.","focus":["below","legend"]}],"artwork_reviewed":true,"art_sha1":"569cb0daa4611675e654edbe38c0a5e53ecd275b","art_kind":"png","art_width":3646,"art_height":2419},"vol1:fig-sparse-heat-map":{"key":"vol1:fig-sparse-heat-map","figure_id":"fig-sparse-heat-map","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Illustrative Layer-Wise Sparsity Distribution","status":"ready","treatment":"annotated","question":"Does a darker layer necessarily execute faster?","scope":"This mixed-layer schematic is not a measurement from one trained model. Zero density alone establishes neither redundancy nor runtime benefit.","regions":{"conv":{"x":0,"y":0.09,"w":0.8,"h":0.35,"label":"Convolutional-layer rows"},"fc":{"x":0,"y":0.43,"w":1,"h":0.17,"label":"Fully connected rows"},"attention":{"x":0,"y":0.6,"w":0.81,"h":0.12,"label":"Attention rows"},"mlp":{"x":0,"y":0.72,"w":1,"h":0.13,"label":"MLP rows"},"legend":{"x":0.11,"y":0.87,"w":0.67,"h":0.09,"label":"Sparsity shading legend"}},"steps":[{"title":"Decode the shade","description":"The legend maps darker tiles to higher zero density. Shade counts removed weights in this schematic; it is not a time or bandwidth scale.","focus":["legend"]},{"title":"Compare layer families","description":"The convolutional rows show lighter shades while the fully connected rows are darker. This illustrates a nonuniform policy, not verified redundancy in all fully connected layers.","focus":["conv","fc"]},{"title":"Keep transformer components distinct","description":"Attention and MLP rows have their own patterns. Different tensors can use different layouts and kernels even when their zero density is similar.","focus":["attention","mlp"]},{"title":"Profile the usable representation","description":"To claim savings, pair each row's density with a sparse storage format and supported kernel profile. Dense execution may still process every zero.","focus":["fc","attention","legend"]}],"artwork_reviewed":true,"art_sha1":"5aa0d31ec6c7aa68071ab33290767349d767e29f","art_kind":"svg","art_width":1200,"art_height":945,"art_structural_sha1":"5baea89ecfa81d3a2c5bea01a7443aff140783dd"},"vol1:fig-sparse-matrix":{"key":"vol1:fig-sparse-matrix","figure_id":"fig-sparse-matrix","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Sparse Matrix Transformation","status":"ready","treatment":"annotated","question":"What does magnitude pruning change before any sparse kernel runs?","scope":"This example illustrates a mask over weight values. Zero entries in an unchanged dense allocation do not by themselves reduce allocated bytes or runtime.","regions":{"before":{"x":0,"y":0.11,"w":0.45,"h":0.89,"label":"Original weight matrix"},"after":{"x":0.55,"y":0.11,"w":0.45,"h":0.89,"label":"Pruned weight matrix"},"removed":{"x":0.55,"y":0.11,"w":0.1,"h":0.16,"label":"Small weights set to zero"},"retained":{"x":0.63,"y":0.11,"w":0.13,"h":0.16,"label":"Retained larger weights"}},"steps":[{"title":"Inspect magnitudes","description":"The left matrix mixes small values with larger positive and negative weights. Magnitude-based pruning compares absolute values rather than pruning by sign.","focus":["before"]},{"title":"Replace selected values with zeros","description":"The right matrix preserves its grid while many cells become white zero entries. The numerical mask changes values, not automatically the allocation shape.","focus":["after","removed"]},{"title":"Retain important candidates","description":"Larger-magnitude entries remain colored, including negative weights. Magnitude is a pruning heuristic, so task-quality recovery and validation still matter.","focus":["retained"]},{"title":"Require an execution representation","description":"Sparse storage and a matching kernel can turn these zeros into skipped data and work. A dense kernel may still read and multiply the full grid.","focus":["after"]}],"artwork_reviewed":true,"art_sha1":"54b2160313300cafa3be7052f5d84331e927dda1","art_kind":"svg","art_width":1200,"art_height":603,"art_structural_sha1":"b8cc8100cde868c7b4dafc96eb74b56cb731db80"},"vol1:fig-spectrogram-example":{"key":"vol1:fig-spectrogram-example","figure_id":"fig-spectrogram-example","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Audio Feature Representations","status":"ready","treatment":"annotated","question":"What information changes when audio becomes model features?","scope":"The three panels are illustrative; the bottom is an MFCC approximation, not a complete production extraction specification.","regions":{"wave":{"x":0.07,"y":0.02,"w":0.89,"h":0.29,"label":"Amplitude waveform"},"spectrum":{"x":0.07,"y":0.36,"w":0.76,"h":0.3,"label":"Spectrogram"},"power":{"x":0.86,"y":0.36,"w":0.09,"h":0.28,"label":"Power scale"},"mfcc":{"x":0.07,"y":0.73,"w":0.76,"h":0.25,"label":"MFCC approximation"}},"steps":[{"title":"Read amplitude over time","description":"The top waveform records amplitude through the two-second interval. Its axes do not directly separate frequency components.","focus":["wave"]},{"title":"Expose frequency structure","description":"The middle panel distributes signal energy across time and frequency. Read color through the Power (dB) scale; the bright low-frequency band marks stronger energy.","focus":["spectrum","power"]},{"title":"Use a compact representation","description":"The bottom panel arranges a smaller coefficient set over time. Training and serving must use matching feature-extraction parameters to preserve the representation expected by the model.","focus":["mfcc"]}],"artwork_reviewed":true,"art_sha1":"230bd90eb43f383907afa9ce313267db8f14fe08","art_kind":"png","art_width":2320,"art_height":1979},"vol1:fig-storage-price-trend":{"key":"vol1:fig-storage-price-trend","figure_id":"fig-storage-price-trend","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Price per Terabyte by Storage Tier, 1956 to 2023","status":"ready","treatment":"annotated","question":"Why does falling storage cost not erase tier-selection trade-offs?","scope":"The chart shows lowest recorded prices in constant 2020 dollars, not current quotes or latency measurements.","regions":{"early":{"x":0.12,"y":0.03,"w":0.31,"h":0.61,"label":"Early DRAM and disk history"},"dram":{"x":0.43,"y":0.42,"w":0.48,"h":0.36,"label":"Later DRAM prices"},"disk":{"x":0.43,"y":0.53,"w":0.48,"h":0.4,"label":"Later disk and solid-state prices"},"endpoints":{"x":0.86,"y":0.7,"w":0.14,"h":0.25,"label":"Latest price labels"},"legend":{"x":0.69,"y":0.02,"w":0.25,"h":0.25,"label":"Storage media legend"}},"steps":[{"title":"Read the logarithmic decline","description":"The long DRAM and hard-disk series descend across many orders of magnitude. The vertical log scale encodes price ratios rather than equal dollar increments.","focus":["early"]},{"title":"Compare tiers at the same date","description":"DRAM remains above disk while flash and solid-state storage occupy intermediate parts of the chart. Falling absolute price has not made all media economically interchangeable.","focus":["dram","disk","legend"]},{"title":"Choose within a hierarchy","description":"The latest labels retain substantial price-per-terabyte gaps. These capacity prices must be combined with bandwidth and latency requirements; this chart alone does not show whether a medium can feed training.","focus":["endpoints"]}],"artwork_reviewed":true,"art_sha1":"f0eea80f123aa20f1ee6d9239682d622fc9c1794","art_kind":"png","art_width":3476,"art_height":2419},"vol1:fig-structured-unstructured":{"key":"vol1:fig-structured-unstructured","figure_id":"fig-structured-unstructured","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Unstructured vs. Structured Pruning","status":"ready","treatment":"annotated","question":"Why does pruning granularity affect the execution format?","scope":"The drawings illustrate structural choices; dashed items denote pruning candidates, not measured device speedups.","regions":{"connections":{"x":0,"y":0.03,"w":0.21,"h":0.94,"label":"Unstructured connection pruning"},"neurons":{"x":0.23,"y":0.04,"w":0.2,"h":0.83,"label":"Structured neuron pruning"},"channels":{"x":0.46,"y":0.04,"w":0.54,"h":0.92,"label":"Structured convolution channels"}},"steps":[{"title":"Remove individual connections","description":"The left network masks arbitrary edges while retaining its nodes. Exploiting those irregular zeros usually needs sparse metadata and a matching kernel.","focus":["connections"]},{"title":"Remove complete neurons","description":"The middle network drops whole nodes and their connections. A rewritten layer can become a smaller dense tensor instead of an irregular mask.","focus":["neurons"]},{"title":"Remove complete channels","description":"The convolution illustration extends this regular cut to channels and associated kernels. Smaller dense shapes remain compatible with conventional kernels, but their realized speed must be profiled.","focus":["channels"]}],"artwork_reviewed":true,"art_sha1":"ade72dd4e7f52d84f2301be1a92805d334123c9b","art_kind":"svg","art_width":1200,"art_height":423,"art_structural_sha1":"704d50f3f3eea0612e7ecf0ea62c1366057b6a75"},"vol1:fig-switch-transformer":{"key":"vol1:fig-switch-transformer","figure_id":"fig-switch-transformer","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Switch Transformer Architecture","status":"ready","treatment":"annotated","question":"How does sparse expert routing separate total parameters from per-token work?","scope":"The diagram shows top-1 routing for two example tokens. Unselected experts can remain resident in memory; routing overhead and imbalance still matter.","regions":{"block":{"x":0,"y":0.16,"w":0.18,"h":0.57,"label":"Switching FFN within transformer"},"more":{"x":0.53,"y":0.88,"w":0.11,"h":0.12,"label":"More token"},"parameters":{"x":0.81,"y":0.88,"w":0.12,"h":0.12,"label":"Parameters token"},"experts":{"x":0.45,"y":0.3,"w":0.55,"h":0.12,"label":"Expert banks"},"weights":{"x":0.52,"y":0.17,"w":0.44,"h":0.11,"label":"Weighted expert outputs"},"router-more":{"x":0.51,"y":0.445,"w":0.09,"h":0.135,"label":"Router for More token"},"router-parameters":{"x":0.785,"y":0.445,"w":0.085,"h":0.135,"label":"Router for Parameters token"}},"steps":[{"title":"Replace the dense FFN stage","description":"The left block places Switching FFN between the transformer's attention and normalization stages. The right panel expands this one stage.","focus":["block"]},{"title":"Route each token","description":"The More and Parameters tokens reach routers that select one expert each. Different tokens can take different expert paths.","focus":["more","parameters","router-more","router-parameters"]},{"title":"Execute only the selected expert","description":"The shown routes choose FFN 2 for one token and FFN 1 for the other. The full expert bank increases model capacity without executing every expert for every token.","focus":["experts"]},{"title":"Keep the systems cost visible","description":"The expert output is weighted and returned to the transformer path. All-resident expert weights still consume memory, and uneven routing can leave some experts overloaded and others idle.","focus":["weights","experts"]}],"artwork_reviewed":true,"art_sha1":"f4424037f8ced4ccbb590b9136205b7269f02947","art_kind":"svg","art_width":1200,"art_height":738,"art_structural_sha1":"041d868d45d7f34e7bf0726c864e42b30f0cff81"},"vol1:fig-synthetic-data":{"key":"vol1:fig-synthetic-data","figure_id":"fig-synthetic-data","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Synthetic Data Augmentation","status":"ready","treatment":"annotated","question":"What do synthetic and historical data each contribute to training?","scope":"Simulation supplements observed data; fidelity and label correctness still require validation.","regions":{"sim":{"x":0.0,"y":0.0,"w":0.17,"h":0.45,"label":"Simulation model"},"synthetic":{"x":0.27,"y":0.0,"w":0.15,"h":0.45,"label":"Synthetic data"},"real":{"x":0.0,"y":0.53,"w":0.17,"h":0.47,"label":"Real system"},"historical":{"x":0.27,"y":0.53,"w":0.15,"h":0.47,"label":"Historical data"},"merge":{"x":0.43,"y":0.1,"w":0.12,"h":0.65,"label":"Combined training input"},"model":{"x":0.58,"y":0.24,"w":0.42,"h":0.45,"label":"Algorithm and trained model"}},"steps":[{"title":"Generate missing cases","description":"The upper branch converts a Simulation model into Synthetic data. It can supply rare or dangerous cases that are expensive to collect physically.","focus":["sim","synthetic"]},{"title":"Retain observed behavior","description":"The lower branch converts observations of a Real system into Historical data. These observations anchor training to actual operating conditions.","focus":["real","historical"]},{"title":"Validate the combination","description":"Both datasets feed the ML algorithm before the trained model emerges. Combining sources expands coverage only when the simulated and observed examples are appropriate for the deployment task.","focus":["merge","model"]}],"artwork_reviewed":true,"art_sha1":"3af83e0336ae2f7a30adafcdc18b89a41bc0815f","art_kind":"svg","art_width":1200,"art_height":407,"art_structural_sha1":"969c215370e386e1c8efe220b2dc58b729a4e2d7"},"vol1:fig-systolic-array":{"key":"vol1:fig-systolic-array","figure_id":"fig-systolic-array","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"Systolic Array Dataflow Architecture","status":"ready","treatment":"annotated","question":"How does neighbor-to-neighbor dataflow reuse operands in an array?","scope":"The drawing is one possible matrix-multiplication dataflow; it does not specify a universal stationary strategy or utilization.","regions":{"control":{"x":0.0,"y":0.0,"w":0.35,"h":0.13,"label":"Control and input staging"},"fifo":{"x":0.18,"y":0.09,"w":0.13,"h":0.7,"label":"Input FIFO buffers"},"horizontal":{"x":0.34,"y":0.09,"w":0.52,"h":0.16,"label":"Horizontal data movement"},"vertical":{"x":0.43,"y":0.26,"w":0.44,"h":0.49,"label":"Vertical partial sums"},"output":{"x":0.31,"y":0.77,"w":0.68,"h":0.22,"label":"Adder-accumulator output chain"}},"steps":[{"title":"Stage operands before the array","description":"The control path feeds the input FIFO buffers. These buffers decouple incoming operands from the regular consumption pattern inside the array.","focus":["control","fifo"]},{"title":"Reuse values across neighbors","description":"The upper arrows show data progressing horizontally through the grid. A value can serve successive processing elements instead of requiring an independent external fetch for each use.","focus":["horizontal"]},{"title":"Carry partial results to completion","description":"The downward arrows represent partial sums. The bottom adder-accumulator chain receives them and produces completed outputs; these paths differ from the horizontal operand stream.","focus":["vertical","output"]}],"artwork_reviewed":true,"art_sha1":"10563af3444fb949a595798fe9522649953364eb","art_kind":"svg","art_width":1200,"art_height":961,"art_structural_sha1":"3e9ba096f2de214d2e4e548bb0f06fa47e863f6e"},"vol1:fig-tail-latency-explosion":{"key":"vol1:fig-tail-latency-explosion","figure_id":"fig-tail-latency-explosion","source":"books/vol1/13_model_serving/13_model_serving.qmd","title":"The Tail Latency Explosion","status":"ready","treatment":"annotated","question":"Why does high average utilization threaten the tail-latency budget?","scope":"Illustrative M/M/1 queue with normalized service time; p99 approximation is about 4.6 times mean. The 70 percent marker is not a universal threshold.","regions":{"low":{"x":0.09,"y":0.69,"w":0.43,"h":0.21,"label":"Lower-utilization delays"},"knee":{"x":0.6,"y":0.46,"w":0.15,"h":0.2,"label":"Illustrative planning knee"},"tail":{"x":0.74,"y":0.04,"w":0.17,"h":0.52,"label":"Rapid p99 growth"},"mean":{"x":0.74,"y":0.66,"w":0.18,"h":0.24,"label":"Mean latency near saturation"}},"steps":[{"title":"Read latency relative to service time","description":"The vertical axis normalizes delay to service time. Even before saturation, queueing adds latency beyond the time required to serve one request.","focus":["low"]},{"title":"Reserve headroom before the steep rise","description":"The labeled knee is a planning marker, not a model-derived discontinuity. The red curve rises continuously as utilization increases.","focus":["knee"]},{"title":"Protect the tail separately from the mean","description":"Near saturation, the p99 curve becomes large before the mean looks equally dramatic. Under the stated queue model, p99 is approximately 4.6 times the mean; real arrival and service patterns require measurement.","focus":["tail","mean"]}],"artwork_reviewed":true,"art_sha1":"b2aab797e1f65ca09b29177daf3d16f80395c626","art_kind":"png","art_width":3384,"art_height":2406},"vol1:fig-technical-debt":{"key":"vol1:fig-technical-debt","figure_id":"fig-technical-debt","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"Hidden Infrastructure of ML Systems","status":"ready","treatment":"annotated","question":"What operational surface surrounds the modeling code?","scope":"Component taxonomy from the cited ML-debt discussion; circle counts, areas, and positions do not measure code volume, cost, or failure likelihood.","regions":{"center":{"x":0.32,"y":0.31,"w":0.31,"h":0.32,"label":"ML system center"},"data":{"x":0.07,"y":0.0,"w":0.42,"h":0.42,"label":"Data collection and verification"},"execution":{"x":0.5,"y":0.0,"w":0.48,"h":0.42,"label":"Configuration and resource management"},"operations":{"x":0.63,"y":0.4,"w":0.37,"h":0.41,"label":"Process and analysis tools"},"model":{"x":0.5,"y":0.73,"w":0.27,"h":0.27,"label":"ML code"},"serving":{"x":0.0,"y":0.4,"w":0.45,"h":0.6,"label":"Serving, monitoring, and feature extraction"}},"steps":[{"title":"Locate modeling within the whole","description":"ML code is one peripheral component around the central system. The drawing does not say that each component contributes an equal fraction of effort.","focus":["center","model"]},{"title":"Inspect dependencies before inference","description":"Data collection, verification, configuration, and machine resource management supply the inputs and execution environment on which modeling depends.","focus":["data","execution"]},{"title":"Carry the deployed system’s maintenance surface","description":"Serving, monitoring, feature extraction, process tools, and analysis tools must continue operating alongside the model. Their interfaces can accumulate debt even when the model code is stable.","focus":["serving","operations"]}],"artwork_reviewed":true,"art_sha1":"e7bf943d0c4f130f4c61eabc516cc0d25cc02d65","art_kind":"svg","art_width":1200,"art_height":1155,"art_structural_sha1":"1f85909dab79be895b20b9f7791d9b5d17396007"},"vol1:fig-technique-decision-tree":{"key":"vol1:fig-technique-decision-tree","figure_id":"fig-technique-decision-tree","source":"books/vol1/09_data_selection/09_data_selection.qmd","title":"Data Selection Decision Tree","status":"ready","treatment":"annotated","question":"How does the binding data problem narrow candidate techniques?","scope":"Decision aid rather than a unique optimal policy; multiple constraints can require multiple branches.","regions":{"root":{"x":0.4,"y":0,"w":0.2,"h":0.23,"label":"Primary bottleneck"},"label":{"x":0,"y":0.23,"w":0.36,"h":0.77,"label":"Labeling-cost branch"},"compute":{"x":0.35,"y":0.23,"w":0.29,"h":0.77,"label":"Compute-cost branch"},"scarcity":{"x":0.64,"y":0.23,"w":0.36,"h":0.77,"label":"Data-scarcity branch"}},"steps":[{"title":"Start with the binding constraint","description":"The top question distinguishes expensive labeling, expensive compute, and insufficient data. A technique chosen without this diagnosis may optimize the wrong resource.","focus":["root"]},{"title":"Use the available supervision","description":"The labeling branch asks about a large pool and an oracle. Those conditions separate self-supervised, semi-supervised, and active-learning candidates.","focus":["label"]},{"title":"Use redundancy and data sources","description":"The compute branch separates redundancy reduction from curriculum choices. The scarcity branch distinguishes a teacher, simulator, or augmentation route. These leaves identify candidates that still need evaluation.","focus":["compute","scarcity"]}],"artwork_reviewed":true,"art_sha1":"53e23a0f58edf52389dd34392e093037666cd220","art_kind":"svg","art_width":1200,"art_height":556,"art_structural_sha1":"0a73e3aae267f74612e0fd74e7ab490b2d03f682"},"vol1:fig-temporal-shift":{"key":"vol1:fig-temporal-shift","figure_id":"fig-temporal-shift","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"Measured Accuracy Loss over Time","status":"ready","treatment":"annotated","question":"What changes when the same trained model meets a later time period?","scope":"Wild-Time measured comparison with one standard deviation over three training seeds; MIMIC mortality uses AUC while other rows use accuracy.","regions":{"yearbook":{"x":0.0,"y":0.0,"w":0.99,"h":0.18,"label":"Yearbook portraits"},"mimic":{"x":0.0,"y":0.18,"w":0.99,"h":0.35,"label":"MIMIC mortality and readmission"},"text":{"x":0.0,"y":0.53,"w":0.99,"h":0.32,"label":"HuffPost and arXiv"},"satellite":{"x":0.0,"y":0.85,"w":0.99,"h":0.1,"label":"FMoW-Time satellite"},"legend":{"x":0.63,"y":0.76,"w":0.36,"h":0.21,"label":"Training-period versus later-period legend"}},"steps":[{"title":"Compare within a dataset","description":"Each row pairs a blue training-period test result with a red later-period result for the same trained model. The printed difference is a percentage-point drop, not relative percentage loss.","focus":["yearbook"]},{"title":"Keep metric definitions visible","description":"MIMIC mortality is measured by AUC; readmission is accuracy. Their shared horizontal scale does not make the two tasks interchangeable. Error bars summarize seed variation.","focus":["mimic"]},{"title":"Observe breadth without inventing a law","description":"News, papers, and satellite images also show later-period losses. These observed results motivate fresh-outcome monitoring, but they do not establish a universal decay rate for all deployments.","focus":["text","satellite","legend"]}],"artwork_reviewed":true,"art_sha1":"cc5e177042d044f348828cddae41e5049c2a7cbe","art_kind":"png","art_width":3697,"art_height":2419},"vol1:fig-tensor-data-structure-a":{"key":"vol1:fig-tensor-data-structure-a","figure_id":"fig-tensor-data-structure-a","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"Tensor Rank Hierarchy","status":"ready","treatment":"annotated","question":"What does tensor rank add beyond stored numerical values?","scope":"Rank counts indexing axes; the drawing does not prescribe physical storage order or imply that rank alone determines bytes.","regions":{"scalar":{"x":0,"y":0.27,"w":0.09,"h":0.6,"label":"Rank 0 scalar"},"vector":{"x":0.14,"y":0,"w":0.09,"h":1,"label":"Rank 1 vector"},"matrix":{"x":0.31,"y":0,"w":0.3,"h":1,"label":"Rank 2 matrix"},"volume":{"x":0.69,"y":0,"w":0.31,"h":1,"label":"Rank 3 volume"}},"steps":[{"title":"Begin with one value","description":"Rank 0 is a scalar: no index is needed to choose an element within it. Its data type still determines the bytes used for that value.","focus":["scalar"]},{"title":"Add a first index","description":"The Rank 1 column groups values along one axis. Its vertical appearance is a drawing convention, not a required memory orientation.","focus":["vector"]},{"title":"Use two coordinates","description":"Rank 2 needs a row and a column index. Shape describes the lengths of these axes, while strides map those indices to storage.","focus":["matrix"]},{"title":"Add another organizational axis","description":"Rank 3 introduces a third index. Higher rank changes the coordinate system; layout and data type still determine addresses and footprint.","focus":["volume"]}],"artwork_reviewed":true,"art_sha1":"827834074f3557652f451955ad084f7f00790bdc","art_kind":"svg","art_width":1200,"art_height":420,"art_structural_sha1":"371404686f0c8c51937e23a54b90deca902f57fa"},"vol1:fig-tensor-data-structure-b":{"key":"vol1:fig-tensor-data-structure-b","figure_id":"fig-tensor-data-structure-b","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"Image as an RGB Tensor","status":"ready","treatment":"annotated","question":"How does an RGB image become a rank-3 tensor?","scope":"The stacked planes show logical channel organization; they do not establish channel-first or channel-last physical storage.","regions":{"red":{"x":0.32,"y":0.34,"w":0.41,"h":0.52,"label":"Red channel grid"},"green":{"x":0.46,"y":0.17,"w":0.4,"h":0.51,"label":"Green channel grid"},"blue":{"x":0.59,"y":0,"w":0.4,"h":0.52,"label":"Blue channel grid"},"height":{"x":0,"y":0.34,"w":0.29,"h":0.53,"label":"Height axis"},"width":{"x":0.31,"y":0.9,"w":0.43,"h":0.1,"label":"Width axis"},"channels":{"x":0.09,"y":0.01,"w":0.46,"h":0.32,"label":"Channel axis"}},"steps":[{"title":"Locate a channel plane","description":"The red grid has three rows and three columns. One entry is one channel value, rather than a complete RGB pixel.","focus":["red"]},{"title":"Add the other colors","description":"Green and blue planes supply the other channel values at matching spatial positions. Height, width, and channel are distinct logical axes.","focus":["green","blue"]},{"title":"Distinguish axes from layout","description":"The labels identify three pixels of height, three pixels of width, and three channels. Channel-first and channel-last layouts can represent these same logical values with different strides.","focus":["height","width","channels","red"]}],"artwork_reviewed":true,"art_sha1":"9a6c71fc25b6d3923baea1d5116be00b938d365c","art_kind":"svg","art_width":1200,"art_height":945,"art_structural_sha1":"69fb6bd134eca504378f995946370d834089f8de"},"vol1:fig-tensor-decomposition":{"key":"vol1:fig-tensor-decomposition","figure_id":"fig-tensor-decomposition","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Tensor Decomposition","status":"ready","treatment":"annotated","question":"How do three mode-specific factors reconstruct one tensor entry?","scope":"This is a low-rank approximation. The highlighted vectors identify one entry; the image does not guarantee a particular accuracy or speedup.","regions":{"tensor":{"x":0,"y":0.18,"w":0.45,"h":0.82,"label":"Original three-dimensional tensor"},"entry":{"x":0.19,"y":0.47,"w":0.13,"h":0.18,"label":"Highlighted tensor entry"},"a":{"x":0.51,"y":0.27,"w":0.16,"h":0.6,"label":"Row-mode factor A"},"b":{"x":0.72,"y":0.3,"w":0.28,"h":0.43,"label":"Column-mode factor B transpose"},"c":{"x":0.64,"y":0,"w":0.24,"h":0.26,"label":"Depth-mode factor C"}},"steps":[{"title":"Keep the three axes distinct","description":"The tensor has dimensions I, J, and T. Its selected entry uses one coordinate from each mode, rather than treating all axes as one flattened matrix.","focus":["tensor","entry"]},{"title":"Select matching factor vectors","description":"The red slices in A, B-transpose, and C correspond to the chosen coordinates. Each slice has components along the shared rank dimension k.","focus":["a","b","c"]},{"title":"Combine across rank","description":"Products of matching rank components are summed to reconstruct the selected entry approximately. The factors replace a full three-dimensional array with mode-specific representations.","focus":["entry","a","b","c"]}],"artwork_reviewed":true,"art_sha1":"cc2a23eb526f2a0b9c361407691f5da8c6ec4199","art_kind":"svg","art_width":1200,"art_height":713,"art_structural_sha1":"d465691ae88ab35923666ce4dd4841847fc3b9ee"},"vol1:fig-tensorflow-architecture":{"key":"vol1:fig-tensorflow-architecture","figure_id":"fig-tensorflow-architecture","source":"books/vol1/07_frameworks/07_frameworks.qmd","title":"TensorFlow Training-to-Deployment Pipeline","status":"ready","treatment":"annotated","question":"How does one TensorFlow model reach different execution targets?","scope":"The figure depicts the chapter's TensorFlow architecture and named interfaces; it is not a claim that all current APIs or platforms share feature parity.","regions":{"data":{"x":0,"y":0.07,"w":0.43,"h":0.17,"label":"Read and preprocess data"},"apis":{"x":0,"y":0.29,"w":0.43,"h":0.17,"label":"Model-building interfaces"},"strategy":{"x":0,"y":0.51,"w":0.43,"h":0.17,"label":"Distribution strategy"},"devices":{"x":0,"y":0.76,"w":0.43,"h":0.2,"label":"CPU GPU TPU"},"saved":{"x":0.48,"y":0.4,"w":0.13,"h":0.2,"label":"SavedModel boundary"},"targets":{"x":0.68,"y":0.07,"w":0.32,"h":0.91,"label":"Deployment targets"}},"steps":[{"title":"Build from input","description":"Read & Preprocess Data feeds tf.keras, TensorFlow Hub, and Premade Estimators in this architecture. These interfaces describe model computation above the device layer.","focus":["data","apis"]},{"title":"Choose execution resources","description":"Distribution Strategy connects the model to CPU, GPU, or TPU execution. Device support and placement remain systems choices below the model-building API.","focus":["strategy","devices"]},{"title":"Export an artifact","description":"SavedModel is the central export boundary in the diagram. A deployable artifact must carry the computation and state its consumer requires.","focus":["saved"]},{"title":"Match the serving environment","description":"The right branches show Serving, Lite, JavaScript, and other language bindings. Export does not guarantee identical operator coverage or performance across those targets.","focus":["targets"]}],"artwork_reviewed":true,"art_sha1":"f4b956f7177f33f05a6c7caac75f3d88e5a9e3f8","art_kind":"svg","art_width":1200,"art_height":507,"art_structural_sha1":"9081c7a809942c74f4366f51a3da314de4d12b16"},"vol1:fig-test-set-label-errors":{"key":"vol1:fig-test-set-label-errors","figure_id":"fig-test-set-label-errors","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"Label Errors in Benchmark Test Sets","status":"ready","treatment":"annotated","question":"Which error estimates are directly reviewed and which are extrapolated?","scope":"These are study-specific test-set error shares, not current universal error rates.","regions":{"quick":{"x":0.0,"y":0.02,"w":1,"h":0.14,"label":"QuickDraw estimate"},"confirmed":{"x":0.0,"y":0.15,"w":0.73,"h":0.19,"label":"CIFAR-100 and ImageNet reviewed errors"},"amazon":{"x":0.0,"y":0.34,"w":0.74,"h":0.1,"label":"Amazon Reviews estimate"},"lower":{"x":0.0,"y":0.44,"w":0.65,"h":0.43,"label":"Remaining datasets"},"legend":{"x":0.84,"y":0.71,"w":0.16,"h":0.22,"label":"Modality legend"}},"steps":[{"title":"Read the largest estimate","description":"QuickDraw’s hatched bar reports 10.12 percent, extrapolated from a reviewed sample. The hatch distinguishes estimation from the solid reviewed counts.","focus":["quick"]},{"title":"Inspect confirmed errors","description":"CIFAR-100 and ImageNet validation have solid bars with similar reported error shares. Their neighboring labels give the confirmed counts as well as percentages.","focus":["confirmed"]},{"title":"Separate modality and certainty","description":"Amazon Reviews is also hatched. Color encodes image, text, or audio modality; it does not encode whether a result is extrapolated. Even the shorter bars motivate test-label auditing when leaderboard gaps are small.","focus":["amazon","lower","legend"]}],"artwork_reviewed":true,"art_sha1":"961d154bc6a6dd288919629741ccb7177cd6723b","art_kind":"png","art_width":3759,"art_height":2234},"vol1:fig-tf-bottleneck-trace":{"key":"vol1:fig-tf-bottleneck-trace","figure_id":"fig-tf-bottleneck-trace","source":"books/vol1/08_training/08_training.qmd","title":"Data-Bound Profiler Trace","status":"ready","treatment":"annotated","question":"Where does the trace suggest an input-pipeline investigation should start?","scope":"The screenshot is evidence to inspect, not a causal experiment; confirm host dependencies before assigning a bottleneck.","regions":{"streams":{"x":0.0,"y":0.08,"w":1,"h":0.49,"label":"Device stream rows"},"gap":{"x":0.4,"y":0.12,"w":0.055,"h":0.4,"label":"Idle interval between device bursts"},"host":{"x":0.0,"y":0.56,"w":1,"h":0.44,"label":"Host execution rows"},"burst":{"x":0.46,"y":0.12,"w":0.075,"h":0.4,"label":"Device activity burst"}},"steps":[{"title":"Locate device execution","description":"The upper stream rows contain short colored activity blocks. These mark device work, distinct from the host operation rows below.","focus":["streams","burst"]},{"title":"Inspect the empty intervals","description":"The white interval between bursts shows that streams are not executing continuously. Idle time motivates checking data readiness, transfers, and synchronization.","focus":["gap"]},{"title":"Correlate host work","description":"Compare host operations with the adjacent device bursts. Follow dependencies in the profiler to determine whether batch preparation or transfers explain the waiting; a white gap alone cannot prove the cause.","focus":["host","burst"]}],"artwork_reviewed":true,"art_sha1":"c766aecbab28ce464b960d94844f8bbbc90b4bec","art_kind":"png","art_width":1000,"art_height":398},"vol1:fig-throughput-latency-knee":{"key":"vol1:fig-throughput-latency-knee","figure_id":"fig-throughput-latency-knee","source":"books/vol1/13_model_serving/13_model_serving.qmd","title":"The Throughput-Latency Knee","status":"ready","treatment":"annotated","question":"What does a larger batch buy and what does it cost in this serving model?","scope":"Modeled reference profile, not measured benchmarks; one worker waits a 10 ms formation window before serving each batch.","regions":{"small":{"x":0.13,"y":0.69,"w":0.46,"h":0.16,"label":"Small-batch region"},"knee":{"x":0.63,"y":0.27,"w":0.15,"h":0.45,"label":"Planning knee"},"large":{"x":0.8,"y":0.02,"w":0.1,"h":0.48,"label":"Large-batch throughput and latency"}},"steps":[{"title":"Amortize fixed overhead","description":"At small batch sizes, more requests share fixed work and the formation window. Throughput rises while latency grows relatively slowly.","focus":["small"]},{"title":"Read both metrics at the knee","description":"The planning knee marks twice the batch-one latency and half the modeled throughput ceiling. It is a stated planning definition rather than a hardware phase transition.","focus":["knee"]},{"title":"Pay increasing latency for diminishing throughput gain","description":"At larger batches, throughput approaches its ceiling while latency rises. Each throughput point is batch size divided by the plotted formation-plus-service latency for this single worker.","focus":["large"]}],"artwork_reviewed":true,"art_sha1":"ce513ba70b35029f73aa576cf973010082da8317","art_kind":"png","art_width":3692,"art_height":2476},"vol1:fig-timeline":{"key":"vol1:fig-timeline","figure_id":"fig-timeline","source":"books/vol1/11_hw_acceleration/11_hw_acceleration.qmd","title":"Hardware Specialization Timeline","status":"ready","treatment":"annotated","question":"What repeats across generations of specialized hardware?","scope":"Historical examples organized by era; columns are not equal-duration performance measurements.","regions":{"early":{"x":0.0,"y":0.0,"w":0.19,"h":0.97,"label":"1980s floating-point and signal processors"},"graphics":{"x":0.2,"y":0.0,"w":0.19,"h":0.97,"label":"1990s graphics and SIMD"},"media":{"x":0.4,"y":0.0,"w":0.19,"h":0.97,"label":"2000s media and network processors"},"tensor":{"x":0.6,"y":0.0,"w":0.19,"h":0.97,"label":"2010s tensor operations"},"application":{"x":0.8,"y":0.0,"w":0.19,"h":0.97,"label":"2020s application-specific acceleration"}},"steps":[{"title":"Specialize the dominant operation","description":"The 1980s examples move floating-point and signal work into dedicated units. Later integration of the FPU illustrates that specialization and integration can coexist.","focus":["early"]},{"title":"Change the workload, change the unit","description":"Graphics, SIMD, codecs, and network processors target different repeated operations. Their specialized datapaths anticipate the same principle used by tensor hardware.","focus":["graphics","media"]},{"title":"Reuse the principle for learning workloads","description":"The final columns shift toward deep-learning tensor operations and application-specific acceleration. This chronology does not establish that one accelerator is best for every workload.","focus":["tensor","application"]}],"artwork_reviewed":true,"art_sha1":"a515e7d979997d18826140418f4b015852d00f3c","art_kind":"svg","art_width":1200,"art_height":475,"art_structural_sha1":"6ad9e4e5a1122dbeb10f43fb6c0020208c1d875e"},"vol1:fig-tiny-ml":{"key":"vol1:fig-tiny-ml","figure_id":"fig-tiny-ml","source":"books/vol1/02_system_paradigms/02_system_paradigms.qmd","title":"TinyML Constraint Map","status":"ready","treatment":"annotated","question":"What must fit before always-on microcontroller inference is feasible?","scope":"The map identifies resource and operational requirements; compression is not guaranteed to preserve quality or battery life.","regions":{"binding":{"x":0.02,"y":0.2,"w":0.22,"h":0.79,"label":"TinyML resource envelope"},"response":{"x":0.33,"y":0.2,"w":0.16,"h":0.79,"label":"On-chip execution responses"},"boundary":{"x":0.58,"y":0.2,"w":0.18,"h":0.79,"label":"TinyML failure boundaries"},"workloads":{"x":0.85,"y":0.2,"w":0.15,"h":0.79,"label":"Tiny sensing workloads"}},"steps":[{"title":"Check capacity and power first","description":"Milliwatt Power Budget and Kilobyte Memory Envelope constrain the entire pipeline. Always-on duty cycle and sparse connectivity further limit execution and updates.","focus":["binding"]},{"title":"Keep work on chip and sleep","description":"Fit Model and Activations on Chip addresses memory fit. Integer arithmetic and sleeping between detections can reduce resource demand when supported by the workload.","focus":["response"]},{"title":"Preserve the engineering caveats","description":"Compression-Driven Accuracy Loss, Firmware Update Risk, Toolchain Fragmentation, and No Local Full Training are explicit boundaries. Fitting bytes does not resolve them.","focus":["boundary"]},{"title":"Use a bounded sensing task","description":"Wake-word detection, wildlife monitoring, wearables, and factory sensors illustrate small local decisions. Their complete sensing and update paths still require validation.","focus":["workloads"]}],"artwork_reviewed":true,"art_sha1":"d13ccf6380f775912dfd65e47474144b28b29acb","art_kind":"svg","art_width":1200,"art_height":493,"art_structural_sha1":"4a8751591dd4d3e6f12915442a1b2ee4b9d8f30a"},"vol1:fig-traditional":{"key":"vol1:fig-traditional","figure_id":"fig-traditional","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Traditional Programming Flow","status":"ready","treatment":"annotated","question":"Which inputs does a rule-based program require?","scope":"This is a program interface diagram, not a comparison of measured accuracy or runtime.","regions":{"upper":{"x":0.0,"y":0.0,"w":0.24,"h":0.29,"label":"Rules input"},"lower":{"x":0.0,"y":0.69,"w":0.24,"h":0.3,"label":"Data input"},"process":{"x":0.31,"y":0.34,"w":0.38,"h":0.31,"label":"Processing stage"},"output":{"x":0.77,"y":0.34,"w":0.23,"h":0.31,"label":"Answers output"}},"steps":[{"title":"Identify the supplied information","description":"Rules and data are both inputs. The rules encode the developer’s decision procedure.","focus":["upper","lower"]},{"title":"Follow the processing boundary","description":"Traditional programming applies those supplied rules to the data.","focus":["process"]},{"title":"Read what the system produces","description":"Answers leave the program as outputs; they do not enter as training labels.","focus":["output"]}],"artwork_reviewed":true,"art_sha1":"b6ed73f567ba8e18d55e05c9103408b91b664143","art_kind":"svg","art_width":1200,"art_height":319,"art_structural_sha1":"8b6e3dc1f3fff1a6af19c62706af1363db497b8f"},"vol1:fig-train-data-parallelism":{"key":"vol1:fig-train-data-parallelism","figure_id":"fig-train-data-parallelism","source":"books/vol1/08_training/08_training.qmd","title":"Data Parallelism","status":"ready","treatment":"annotated","question":"What is replicated and what is synchronized in data parallel training?","scope":"This is logical synchronous data parallelism; communication overlap and exact averaging rules are implementation-specific.","regions":{"input":{"x":0.39,"y":0.0,"w":0.22,"h":0.23,"label":"Input data"},"replicas":{"x":0.05,"y":0.26,"w":0.91,"h":0.25,"label":"Four model replicas"},"sync":{"x":0.39,"y":0.54,"w":0.23,"h":0.22,"label":"Gradient synchronization"},"update":{"x":0.39,"y":0.79,"w":0.23,"h":0.21,"label":"Model update"}},"steps":[{"title":"Shard examples, replicate the model","description":"Input Data splits into four batches. Each GPU performs forward and backward computation with a complete model copy, so this strategy does not shrink the model state required per replica.","focus":["input","replicas"]},{"title":"Combine gradients","description":"Gradient Sync / AllReduce aggregates local gradient contributions across workers. Correct scaling is required to implement the intended global-batch objective.","focus":["sync"]},{"title":"Keep replicas aligned","description":"The Model Update uses the synchronized gradient so replicas can proceed from matching parameters. Communication, input supply, and imbalance limit how close throughput gets to linear scaling.","focus":["update","replicas"]}],"artwork_reviewed":true,"art_sha1":"b90bfb180822002b0ba20db8ffd13843000b4461","art_kind":"svg","art_width":1200,"art_height":893,"art_structural_sha1":"72cce7248c6d10f1d6391078ed57e405d161da0f"},"vol1:fig-training-loop":{"key":"vol1:fig-training-loop","figure_id":"fig-training-loop","source":"books/vol1/08_training/08_training.qmd","title":"The Iterative Training Loop","status":"ready","treatment":"annotated","question":"What must finish before parameters can be updated?","scope":"This is a logical dependency graph; it does not specify execution timing or exact tensor storage.","regions":{"predict":{"x":0.05,"y":0.0,"w":0.73,"h":0.29,"label":"Prediction path"},"truth":{"x":0.85,"y":0.33,"w":0.15,"h":0.25,"label":"Ground truth"},"loss":{"x":0.58,"y":0.33,"w":0.17,"h":0.25,"label":"Loss computation"},"backward":{"x":0.05,"y":0.32,"w":0.42,"h":0.26,"label":"Backward pass and gradients"},"update":{"x":0.05,"y":0.67,"w":0.43,"h":0.3,"label":"Optimizer and parameter update"},"return":{"x":0.0,"y":0.91,"w":0.55,"h":0.09,"label":"Next-iteration loop"}},"steps":[{"title":"Produce predictions","description":"Training Batch enters Forward Pass to produce Predicted Labels. The batch is an input, separate from the parameter-update feedback path.","focus":["predict"]},{"title":"Compare against ground truth","description":"Predicted Labels and Ground Truth supply the Loss Function. The loss seeds the Backward Pass, which produces Parameter Gradients.","focus":["truth","loss","backward"]},{"title":"Update only after gradients","description":"The optimizer consumes Parameter Gradients and updates parameters. The dashed Next Iteration path returns those parameters to a later forward pass, not to work still using the old values.","focus":["update","return"]}],"artwork_reviewed":true,"art_sha1":"f1e45f345360330398de65d52183a3c0c6d23f7d","art_kind":"svg","art_width":1200,"art_height":425,"art_structural_sha1":"d901b6a2eab9194053c9d0fe37b21c425bdd16bf"},"vol1:fig-training-pipeline":{"key":"vol1:fig-training-pipeline","figure_id":"fig-training-pipeline","source":"books/vol1/08_training/08_training.qmd","title":"Training System Overview","status":"ready","treatment":"annotated","question":"Which interfaces can keep the accelerator waiting during training?","scope":"Subsystems can overlap; the schematic does not specify concurrency or evaluation frequency.","regions":{"data":{"x":0.0,"y":0.0,"w":0.2,"h":1,"label":"Data pipeline"},"batch":{"x":0.19,"y":0.19,"w":0.24,"h":0.19,"label":"Processed batches"},"loop":{"x":0.43,"y":0.0,"w":0.19,"h":1,"label":"Training loop"},"evaluation":{"x":0.82,"y":0.0,"w":0.18,"h":1,"label":"Evaluation pipeline"},"feedback":{"x":0.61,"y":0.16,"w":0.23,"h":0.31,"label":"Metrics and feedback"}},"steps":[{"title":"Prepare the next batch","description":"The Data Pipeline ingests, preprocesses, and batches examples before the training loop can consume them. A slow producer can leave accelerator kernels without ready input.","focus":["data","batch"]},{"title":"Execute dependent computation","description":"The Training Loop performs the forward pass, loss computation, and backward pass. Its arithmetic dependencies remain even when input preparation overlaps it.","focus":["loop"]},{"title":"Budget evaluation work","description":"Evaluation receives metrics and returns feedback. Its schedule and shared resources can impose pauses, so evaluation cadence is part of the system throughput budget.","focus":["evaluation","feedback"]}],"artwork_reviewed":true,"art_sha1":"6c9a033c0ea675468cad792c83c279e3b46fabd1","art_kind":"svg","art_width":1200,"art_height":299,"art_structural_sha1":"a3b4175ee1371dd2a4a8fe00dc8ac5a7d3481be9"},"vol1:fig-training-roofline":{"key":"vol1:fig-training-roofline","figure_id":"fig-training-roofline","source":"books/vol1/08_training/08_training.qmd","title":"Illustrative Training Roofline","status":"ready","treatment":"annotated","question":"When does less HBM traffic raise a training kernel’s performance ceiling?","scope":"Coordinates are assumed, not a measured execution profile; real kernels need not cross the ridge.","regions":{"low":{"x":0.1,"y":0.42,"w":0.39,"h":0.42,"label":"Softmax and LayerNorm"},"attention":{"x":0.37,"y":0.24,"w":0.23,"h":0.16,"label":"Standard attention"},"ridge":{"x":0.69,"y":0.03,"w":0.07,"h":0.83,"label":"Ridge point"},"dense":{"x":0.73,"y":0.02,"w":0.27,"h":0.18,"label":"MatMul and FlashAttention"},"arrow":{"x":0.53,"y":0.11,"w":0.37,"h":0.23,"label":"Traffic-reduction arrow"}},"steps":[{"title":"Identify the bandwidth side","description":"Softmax and LayerNorm lie at low arithmetic intensity under the sloped memory-bandwidth ceiling. Reducing bytes moved can raise the ceiling for this regime.","focus":["low"]},{"title":"Read the attention comparison","description":"The standard-attention point is left of the ridge. The arrow toward FlashAttention represents increased arithmetic intensity from avoiding HBM traffic, rather than a measured time animation.","focus":["attention","arrow"]},{"title":"Respect the compute ceiling","description":"At the ridge, the bandwidth and compute ceilings meet. The plotted MatMul and FlashAttention points reach the flat ceiling in this illustration; further intensity alone cannot raise that hardware peak.","focus":["ridge","dense"]}],"artwork_reviewed":true,"art_sha1":"25723c4f022780c2f3f82ab28123782a1c2d3f7d","art_kind":"png","art_width":3371,"art_height":2052},"vol1:fig-training-step-memory":{"key":"vol1:fig-training-step-memory","figure_id":"fig-training-step-memory","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Memory Over One Training Step","status":"ready","treatment":"annotated","question":"Which memory survives across forward, backward, and update events?","scope":"FP32 running network with two persistent Adam buffers; dashed inference line is a peak comparison, not an overlapping job.","regions":{"small":{"x":0.03,"y":0.03,"w":0.45,"h":0.78,"label":"Batch-32 event sequence"},"large":{"x":0.53,"y":0.03,"w":0.45,"h":0.78,"label":"Batch-1024 event sequence"},"forward":{"x":0.65,"y":0.12,"w":0.15,"h":0.64,"label":"Large-batch retained forward activations"},"backward":{"x":0.8,"y":0.12,"w":0.13,"h":0.64,"label":"Backward activation release and gradients"},"update":{"x":0.92,"y":0.52,"w":0.06,"h":0.24,"label":"Update-time parameter and gradient state"},"legend":{"x":0.0,"y":0.85,"w":1.0,"h":0.14,"label":"Memory-state legend"}},"steps":[{"title":"Identify persistent and transient state","description":"The legend separates weights, Adam state, gradients, and saved activations. Weights and Adam buffers remain throughout, while the other categories vary with the training event.","focus":["legend","small"]},{"title":"Retain forward outputs for backward","description":"In the large-batch panel, forward events F1 to F3 build up saved activations. Increasing batch size enlarges these tensors without multiplying the model’s parameter state.","focus":["large","forward"]},{"title":"Release only after the backward consumer","description":"B3 to B1 consume and release saved activations while parameter gradients accumulate. The peak can therefore occur at a different event depending on batch size.","focus":["backward","small"]},{"title":"Inspect update-time state","description":"At the plotted update event, saved activations are gone while weights, Adam state, and allocated gradients remain in the accounting. Clearing or reusing gradient buffers is a separate runtime decision. The dashed inference peak uses a different execution regime.","focus":["update"]}],"artwork_reviewed":true,"art_sha1":"f119dd60d0c4f62af1bebbb5b9fd3eed32713f8d","art_kind":"png","art_width":3692,"art_height":2628},"vol1:fig-training-vs-inference":{"key":"vol1:fig-training-vs-inference","figure_id":"fig-training-vs-inference","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Inference vs. Training Flow","status":"ready","treatment":"annotated","question":"What state and computation does training add to inference?","scope":"Same schematic network in two operating regimes; large training batches and small variable inference batches are tendencies rather than universal requirements.","regions":{"trainingbatch":{"x":0.0,"y":0.0,"w":0.27,"h":0.48,"label":"Large uniform training batch"},"trainingnetwork":{"x":0.42,"y":0.0,"w":0.55,"h":0.48,"label":"Training forward and backward paths"},"inferencebatch":{"x":0.0,"y":0.52,"w":0.39,"h":0.48,"label":"Smaller varied inference batch"},"inferencenetwork":{"x":0.42,"y":0.52,"w":0.55,"h":0.48,"label":"Inference forward-only path"},"error":{"x":0.83,"y":0.15,"w":0.17,"h":0.25,"label":"Training error signal"}},"steps":[{"title":"Keep the network identity fixed","description":"Both rows depict the same network. The input-batch outlines differ to illustrate operational choices rather than different model weights.","focus":["trainingbatch","inferencebatch"]},{"title":"Add reverse work for learning","description":"Training propagates predictions forward, then sends error information backward to compute gradients. Saved activations must remain available for that reverse pass.","focus":["trainingnetwork","error"]},{"title":"Serve with forward-only execution","description":"Inference applies fixed parameters without a backward pass or optimizer update. Its batch size follows serving policy and incoming demand, which changes reuse and latency trade-offs.","focus":["inferencenetwork","inferencebatch"]}],"artwork_reviewed":true,"art_sha1":"5668da65cf36ce2f21a99738547abc8cde411126","art_kind":"svg","art_width":1200,"art_height":468,"art_structural_sha1":"6ef9da8f8e43bf876ab0406d835a3cba93184fff"},"vol1:fig-transformer":{"key":"vol1:fig-transformer","figure_id":"fig-transformer","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Transformer Architecture (Encoder-Decoder)","status":"ready","treatment":"annotated","question":"Which connections distinguish the transformer decoder from the encoder?","scope":"Original encoder–decoder architecture; not a decoder-only model diagram.","regions":{"embedding":{"x":0,"y":0.76,"w":1,"h":0.24,"label":"Embeddings and positional encodings"},"encoder":{"x":0.04,"y":0.33,"w":0.38,"h":0.45,"label":"Encoder stack"},"masked":{"x":0.61,"y":0.61,"w":0.3,"h":0.1,"label":"Decoder masked attention"},"cross":{"x":0.61,"y":0.43,"w":0.3,"h":0.1,"label":"Decoder cross-attention"},"head":{"x":0.6,"y":0,"w":0.3,"h":0.18,"label":"Output projection and softmax"}},"steps":[{"title":"Supply order information","description":"Positional encodings are added to token embeddings before the stacks. Attention without positional information does not encode sequence order by itself.","focus":["embedding"]},{"title":"Encode all input positions","description":"The left stack alternates attention and feed-forward transformations, each with residual and normalization paths. The repetition bracket denotes repeated layers.","focus":["encoder"]},{"title":"Preserve decoder causality","description":"Masked self-attention restricts access to future output positions. The next attention block also receives the encoder representations through the cross-stack connection.","focus":["masked","cross"]},{"title":"Predict the output token","description":"The decoder feeds a linear projection and softmax. Parallel training across known positions does not eliminate autoregressive dependencies during generation.","focus":["head"]}],"artwork_reviewed":true,"art_sha1":"04385f26ae1b51b10da7f1456f6cc5a9eac8bf17","art_kind":"svg","art_width":1200,"art_height":1325,"art_structural_sha1":"99daded9e0666cfe079a88a79a24d1da5ea3572c"},"vol1:fig-transformer-attention-visualized":{"key":"vol1:fig-transformer-attention-visualized","figure_id":"fig-transformer-attention-visualized","source":"books/vol1/06_nn_architectures/06_nn_architectures.qmd","title":"Illustrative Attention Pattern","status":"ready","treatment":"annotated","question":"What does the illustrated attention from “they” reveal—and what does it not prove?","scope":"Hypothetical attention strengths, not measured weights or a causal explanation of model behavior.","regions":{"query":{"x":0.7,"y":0.79,"w":0.3,"h":0.08,"label":"Pronoun they"},"student":{"x":0,"y":0.18,"w":0.29,"h":0.09,"label":"Student token"},"finish":{"x":0,"y":0.4,"w":0.29,"h":0.09,"label":"Finish token"},"homework":{"x":0,"y":0.62,"w":0.29,"h":0.09,"label":"Homework token"},"links":{"x":0.28,"y":0.12,"w":0.44,"h":0.86,"label":"Direct attention links"}},"steps":[{"title":"Choose the query position","description":"The violet “they” token is the position whose attention links are illustrated. Every line originates at this same query position.","focus":["query"]},{"title":"Inspect stronger associations","description":"Thicker hypothetical links connect to student, finish, and homework. Thickness encodes the schematic weight magnitude rather than sentence order or execution time.","focus":["student","finish","homework"]},{"title":"Direct access is not proof of reasoning","description":"The links connect distant positions without recurrent hops. This illustrates attention connectivity, but the pattern alone does not establish a faithful explanation of a model decision.","focus":["links","query"]}],"artwork_reviewed":true,"art_sha1":"44de090dfb0fec8f8136da41e9012b30d4528a31","art_kind":"svg","art_width":1200,"art_height":1107,"art_structural_sha1":"c8e9186c8e7a43f29d7fce7746355f695957054c"},"vol1:fig-uptime-iceberg":{"key":"vol1:fig-uptime-iceberg","figure_id":"fig-uptime-iceberg","source":"books/vol1/14_ml_ops/14_ml_ops.qmd","title":"Uptime Dependency Stack","status":"ready","treatment":"annotated","question":"Which failures can remain hidden while a service stays available?","scope":"Conceptual monitoring taxonomy; iceberg area and depth do not encode probability, impact, or severity.","regions":{"uptime":{"x":0.35,"y":0.02,"w":0.28,"h":0.3,"label":"Visible uptime above waterline"},"waterline":{"x":0.0,"y":0.27,"w":0.99,"h":0.08,"label":"Waterline boundary"},"model":{"x":0.25,"y":0.35,"w":0.51,"h":0.6,"label":"Accuracy, drift, bias, and segments"},"data":{"x":0.2,"y":0.49,"w":0.54,"h":0.31,"label":"Pipelines, schemas, and data outages"},"health":{"x":0.06,"y":0.36,"w":0.88,"h":0.13,"label":"Data-health and model-health labels"}},"steps":[{"title":"Separate availability from correctness","description":"Uptime sits above the waterline. A service can return successful responses while producing degraded predictions, so availability is only one monitoring surface.","focus":["uptime","waterline"]},{"title":"Inspect hidden model-health failures","description":"Accuracy, data drift, concept drift, bias, and underperforming segments require evidence beyond a successful request status. The iceberg does not assign them a numerical severity.","focus":["model","health"]},{"title":"Inspect hidden data-pipeline failures","description":"Broken pipelines, schema changes, and data outages can invalidate inputs while the serving process stays alive. Each requires a monitoring signal and an explicit containment action.","focus":["data"]}],"artwork_reviewed":true,"art_sha1":"d2c56da544f135fa05265e2a30735371a727c549","art_kind":"svg","art_width":1200,"art_height":719,"art_structural_sha1":"6316c1e9186a9814fa72a84505806400f0e55655"},"vol1:fig-usps-inference-pipeline":{"key":"vol1:fig-usps-inference-pipeline","figure_id":"fig-usps-inference-pipeline","source":"books/vol1/05_nn_computation/05_nn_computation.qmd","title":"Document-Recognition Pipeline","status":"ready","treatment":"annotated","question":"Which parts of document recognition lie outside neural inference?","scope":"Composite six-stage pipeline distilled from research and deployments, not a reconstruction of one historical machine.","regions":{"raw":{"x":0.0,"y":0.0,"w":0.15,"h":0.86,"label":"Raw data acquisition"},"pre":{"x":0.17,"y":0.0,"w":0.16,"h":0.86,"label":"Conventional preprocessing"},"network":{"x":0.35,"y":0.08,"w":0.13,"h":0.79,"label":"Neural network"},"scores":{"x":0.52,"y":0.08,"w":0.15,"h":0.79,"label":"Raw neural output"},"post":{"x":0.69,"y":0.08,"w":0.14,"h":0.79,"label":"Postprocessing"},"final":{"x":0.85,"y":0.08,"w":0.15,"h":0.79,"label":"Final application output"}},"steps":[{"title":"Prepare the input before inference","description":"Raw data acquisition and conventional preprocessing prepare document images. Their quality and latency affect the system before the neural network runs.","focus":["raw","pre"]},{"title":"Distinguish scores from decisions","description":"The network produces raw output scores. Those scores are intermediate data rather than automatically accepted application results.","focus":["network","scores"]},{"title":"Apply an explicit acceptance policy","description":"Postprocessing checks scores and confidence before producing the final output. Ambiguous cases need further processing or manual review instead of forced classification.","focus":["post","final"]}],"artwork_reviewed":true,"art_sha1":"0e495c0ba588b8456b8a1d2615a2a546629e5f7b","art_kind":"svg","art_width":1200,"art_height":226,"art_structural_sha1":"e0c1e37a7e918b3c8d2e345414fd818a5fe2cd7a"},"vol1:fig-vol1-chapter-dependencies":{"key":"vol1:fig-vol1-chapter-dependencies","figure_id":"fig-vol1-chapter-dependencies","source":"books/vol1/frontmatter/about.qmd","title":"Chapter Dependency Map","status":"ready","treatment":"annotated","question":"Which earlier concepts support the chapter you want to read next?","scope":"Arrows indicate reading dependencies from chapter cross-references, with transitive links omitted; they do not specify an execution schedule.","regions":{"introduction":{"x":0.4,"y":0.03,"w":0.18,"h":0.09,"label":"Chapter 1: Introduction"},"foundations":{"x":0.4,"y":0.2,"w":0.57,"h":0.09,"label":"Chapters 2–4: Foundations"},"computation":{"x":0.2,"y":0.37,"w":0.57,"h":0.09,"label":"Chapters 5–7: Computation to frameworks"},"training":{"x":0.79,"y":0.37,"w":0.18,"h":0.09,"label":"Chapter 8: Model Training"},"selection":{"x":0.2,"y":0.54,"w":0.18,"h":0.09,"label":"Chapter 9: Data Selection"},"optimization":{"x":0.4,"y":0.54,"w":0.57,"h":0.09,"label":"Chapters 10–12: Compression to benchmarking"},"operations":{"x":0.4,"y":0.71,"w":0.57,"h":0.09,"label":"Chapters 13–15: Serving and operations"},"conclusion":{"x":0.79,"y":0.88,"w":0.18,"h":0.09,"label":"Chapter 16: Conclusion"}},"steps":[{"title":"Begin with the foundation path","description":"Introduction points to System Paradigms, which leads through ML Lifecycle to Data Engineering. These arrows identify concepts that later chapters build on; omitted transitive links do not mean the earlier concepts stop mattering.","focus":["introduction","foundations"]},{"title":"Trace the two inputs to training","description":"System Paradigms also leads to Neural Computation, Network Architectures, and ML Frameworks. Model Training then draws on both the frameworks chain and Data Engineering, connecting model execution with its prepared inputs.","focus":["foundations","computation","training"]},{"title":"Separate the optimization branches","description":"Model Training points to Data Selection and Model Compression. Compression leads through Hardware Acceleration to Benchmarking, while Data Selection has its own link into Benchmarking: measured gains depend on both data and execution choices.","focus":["training","selection","optimization"]},{"title":"Carry measured evidence into operation","description":"Benchmarking leads to Model Serving, followed by ML Operations and Responsible Engineering. The sequence connects a measured deployment claim to operation and its obligations.","focus":["optimization","operations"]},{"title":"Choose a path with its prerequisites","description":"Responsible Engineering leads to the Conclusion. To begin at any later chapter, follow its incoming arrows backward and check the prerequisite concepts; the map guides reading rather than requiring one fixed pace.","focus":["operations","conclusion"]}],"artwork_reviewed":true,"art_sha1":"c4addebaa63e4ef02b3198c6afe38ec377d07451","art_kind":"svg","art_width":1200,"art_height":1161,"art_structural_sha1":"1cdf098ca1f7ee93006910ec066476eb15cae27b"},"vol1:fig-weak-supervision":{"key":"vol1:fig-weak-supervision","figure_id":"fig-weak-supervision","source":"books/vol1/04_data_engineering/04_data_engineering.qmd","title":"AI-Augmented Labeling Decision Hierarchy","status":"ready","treatment":"annotated","question":"What evidence supplies labels when expert annotation is too costly?","scope":"Branches name alternative sources of supervision and assumptions, not guaranteed substitutes of equal quality.","regions":{"traditional":{"x":0.08,"y":0.2,"w":0.33,"h":0.19,"label":"Traditional supervision"},"semi":{"x":0.08,"y":0.41,"w":0.33,"h":0.18,"label":"Semi-supervised learning"},"weak":{"x":0.08,"y":0.61,"w":0.33,"h":0.18,"label":"Weak supervision"},"transfer":{"x":0.08,"y":0.82,"w":0.33,"h":0.18,"label":"Transfer learning"},"active":{"x":0.5,"y":0.13,"w":0.25,"h":0.21,"label":"Active learning"},"sources":{"x":0.5,"y":0.36,"w":0.5,"h":0.56,"label":"Weak-supervision sources"}},"steps":[{"title":"Start with expert labels","description":"Traditional Supervision uses subject-matter experts. If labeling everything is too expensive, Active Learning prioritizes which examples should receive their attention.","focus":["traditional","active"]},{"title":"State the added assumption","description":"Semi-supervised Learning uses structure in unlabeled data; Transfer Learning starts from models trained on another task. Each changes what the pipeline must validate.","focus":["semi","transfer"]},{"title":"Inspect programmatic supervision","description":"Weak Supervision obtains cheaper or higher-level signals. The right-hand branches include heuristics, distant supervision, constraints, expected distributions, and invariances; noisy signals still require conflict resolution and quality checks.","focus":["weak","sources"]}],"artwork_reviewed":true,"art_sha1":"f24860c1b45afb88205f2966d65f586e4c713d3f","art_kind":"svg","art_width":1200,"art_height":518,"art_structural_sha1":"3efabb62761714abe904801cf4062f59655d4654"},"vol1:fig-weight-activations-quantization":{"key":"vol1:fig-weight-activations-quantization","figure_id":"fig-weight-activations-quantization","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Quantized Matrix Multiplication Pipeline","status":"ready","treatment":"annotated","question":"Why does INT8 matrix multiplication still need an INT32 accumulation stage?","scope":"The two floating inputs represent operands. This schematic omits implementation details such as bias handling and assumes supported affine integer execution.","regions":{"inputs":{"x":0,"y":0,"w":0.26,"h":0.6,"label":"Operand quantization"},"multiply":{"x":0.26,"y":0.21,"w":0.12,"h":0.18,"label":"INT8 matrix multiplication"},"accumulate":{"x":0.4,"y":0.21,"w":0.12,"h":0.18,"label":"INT32 output"},"requantize":{"x":0.54,"y":0.21,"w":0.12,"h":0.18,"label":"Requantization"},"activation":{"x":0.73,"y":0.21,"w":0.13,"h":0.18,"label":"Activation"},"output":{"x":0.88,"y":0.21,"w":0.12,"h":0.18,"label":"INT8 output"}},"steps":[{"title":"Quantize both operands","description":"The two input paths convert floating-point values to INT8. Their scale and zero-point metadata define how these integers represent real values.","focus":["inputs"]},{"title":"Accumulate with room for sums","description":"Matrix Multiplication consumes INT8 operands, but the sum of many products needs a wider INT32 accumulator. Low-precision inputs do not imply an 8-bit running sum.","focus":["multiply","accumulate"]},{"title":"Rescale before the next layer","description":"Requantization maps the accumulated result back to the intended output scale and clips to the INT8 range. This is a numerical transformation, not merely dropping high bits.","focus":["requantize"]},{"title":"Apply the supported activation path","description":"Activation follows the rescaled values and produces INT8 Output in this diagram. The deployed kernel must preserve the intended scales and nonlinear behavior.","focus":["activation","output"]}],"artwork_reviewed":true,"art_sha1":"fdc641912ccc7f407beeae909bc3ef253bb80d19","art_kind":"svg","art_width":1200,"art_height":362,"art_structural_sha1":"724f64cafa73c097f1de0e7274c7e693c5306d15"},"vol1:fig-winning-ticket":{"key":"vol1:fig-winning-ticket","figure_id":"fig-winning-ticket","source":"books/vol1/10_model_compression/10_model_compression.qmd","title":"Lottery Ticket Iteration Cycle","status":"ready","treatment":"annotated","question":"What is reset when searching for a winning sparse subnetwork?","scope":"The lottery-ticket result is empirical and setting-dependent. Finding a subnetwork may still require expensive dense training and repeated search.","regions":{"init":{"x":0.14,"y":0,"w":0.15,"h":0.24,"label":"Random weight initialization"},"train":{"x":0.14,"y":0.32,"w":0.15,"h":0.24,"label":"Train to convergence"},"prune":{"x":0.27,"y":0.7,"w":0.16,"h":0.24,"label":"Prune lowest weights"},"reset":{"x":0,"y":0.7,"w":0.15,"h":0.24,"label":"Reset surviving weights"},"ticket":{"x":0.51,"y":0.03,"w":0.49,"h":0.96,"label":"Highlighted surviving subnetwork"}},"steps":[{"title":"Record the initialization","description":"Randomly initialize the weights defines the values to which surviving connections can later be reset. The mask has not yet selected a ticket.","focus":["init"]},{"title":"Train and identify a mask","description":"Training to convergence provides weight information for pruning. The pruning step removes a percentage of low-magnitude connections.","focus":["train","prune"]},{"title":"Reset surviving values","description":"Reset weights to initial values preserves the surviving structure while restoring its initial values. Resetting is different from keeping the trained weights and simply fine-tuning.","focus":["reset"]},{"title":"Test the subnetwork","description":"The highlighted red connections show the candidate ticket inside the larger graph. It must be trained in isolation and compared with the dense baseline; comparable quality is not guaranteed.","focus":["ticket"]}],"artwork_reviewed":true,"art_sha1":"9f4c16b8d075883b7ec09f29badc6f92ffb36da3","art_kind":"svg","art_width":1200,"art_height":700,"art_structural_sha1":"8ebff5243d3cfeb6d4f1b19cff7fe8d85e6a7b41"}});
